window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["medcurso:medcurso-gineco-gin-4"]={"block":"medcurso:medcurso-gineco-gin-4","label":"Medcurso · GIN 4","count":458,"questions":[{"id":"medcurso-gineco-gin-4-345477","number":"345477","sourceNumber":"345477","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Mulher de 40 anos trouxe resultado de biopsia de mama direita revelando hiperplasia\nductal atípica. Assinale a opção que indica o risco\npara câncer de mama e a conduta para o caso\napresentado:","options":{"A":"Baixo / uso de progestágeno.","B":"Médio / medidas comportamentais.","C":"Alto / ressecção segmentar.","D":"Indeterminado / uso de tibolona."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-247169","number":"247169","sourceNumber":"247169","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Assinale a alternativa que responde CORRETAMENTE à pergunta abaixo. Paciente do\nsexo feminino, 67 anos, com hipertensão\narterial sistêmica (HAS) e diabética, em uso de enalapril e\nmetformina, procura o posto de saúde por aumento de volume abdominal e plenitude pós-prandial\nhá um mês. Ao exame, PA= 180/90 mmHg; ascite moderada, sem edema de MMII. Qual a causa\nmais provável da ascite na paciente, com base no caso clínico exposto?","options":{"A":"Câncer ginecológico.","B":"Tuberculose.","C":"Síndrome nefrótica.","D":"Cirrose hepática.","E":"Insuficiência cardíaca congestiva."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-251889","number":"251889","sourceNumber":"251889","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"As artérias ovarianas se originam:","options":{"A":"Ambas da aorta.","B":"Ambas da ilíaca interna.","C":"À direita, da aorta e a esquerda, da renal.","D":"À direita, da renal e a esquerda, da aorta."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-251905","number":"251905","sourceNumber":"251905","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente, 35 anos, administradora, vem à consulta com o Médico de Família e\nComunidade (João) para solicitar um exame para\nrastreamento de câncer de mama. Paciente: \"Dr,\nvi as propagandas na televisão sobre o Outubro Rosa e quero fazer uma mamografia.\" O MFC,\ndurante a anamnese não encontra nenhum fator de risco cardiovascular ou para câncer de mama.\nO exame físico de Patrícia está normal. Levando-se em conta a demanda trazida pela paciente e as\nindicações de rastreio para mulheres nessa faixa etária, qual conduta deve ser sugerida pelo\nmédico?","options":{"A":"Recomendar um exame de perfil lipídico e que a sua primeira mamografia seja a partir dos 50\nanos, pois ambos têm graú \"\"A\"\" de recomendação.","B":"Recomendar que se submeta a um ultrassom de mamas, pois a mamografia é indicada a partir\ndos 40 anos.","C":"Recomendar a paciente que realize exames de TSH, perfil lipídico, ultrassom transvaginal e de\nmamas.","D":"Recomendar mamografia a cada 2 anos a partir dos 50 anos e Papanicolau a cada 3 anos, após\n2 exames consecutivos normais no intervalo de\n1 ano."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-247198","number":"247198","sourceNumber":"247198","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"A \"escápula alada\" é uma complicação da lesão acidental durante o tratamento\ncirúrgico do câncer de mama. As estruturas\ncomprometidas são:","options":{"A":"Nervo torácico longo e músculo serrátil anterior.","B":"Nervo torácico longo e músculo subescapular.","C":"Nervo torácico longo e músculo grande dorsal.","D":"Nervo toracodorsal e músculo subescapular.","E":"Nervo toracodorsal e músculo grande dorsal."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-247199","number":"247199","sourceNumber":"247199","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"A lesão benigna de mama que apresenta maior risco relativo para câncer é","options":{"A":"Fibroadenoma.","B":"Adenose esclerosante.","C":"Papiloma múltiplo.","D":"Hamartoma.","E":"Adenoma."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-217668","number":"217668","sourceNumber":"217668","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Em relação aos derrames papilares mamários, pode-se dizer que são considerados\nsuspeitos quando:","options":{"A":"Têm aspecto hemorrágico ou sero-hemorrágico.","B":"São multiductais.","C":"São percebidos apenas quando realizada a expressão mamilar.","D":"Estão associados à mastalgia."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-217671","number":"217671","sourceNumber":"217671","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"O câncer de mama tem risco aumentado nos casos de:","options":{"A":"Menarca precoce e menopausa tardia.","B":"História de parente de primeiro grau acometido pela doença.","C":"Biópsia mostrando hiperplasia ductal atípica.","D":"Todas as anteriores estão corretas."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-183202","number":"183202","sourceNumber":"183202","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma mulher de 21 anos apresenta-se com queixa de dor em fossa ilíca esquerda,\npalpando-se uma massa anexial com\naproximamente 7x7 cm. A ultrassonografia confirma uma\nmassa anexial esquerda complexa com componentes sólidos aparentando conter dente. Qual é a\nhipótese diagnóstica mais provável?","options":{"A":"Teratoma ovariano benigno (cisto dermoide).","B":"Disgerminoma.","C":"Endometrioma.","D":"Cistadenoma seroso.","E":"Cistadenocarcinoma."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-135992","number":"135992","sourceNumber":"135992","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente Aline de 32 anos do sexo feminino, enfermeira, refere sentir uma dor\n(incômodo) há alguns dias e ao fazer\nautoexame, descobriu um nódulo na mama direita. Nega\npatologias anteriores. Tem uma filha de 5 anos que amamentou por 6 meses. Relata uso de\nanticoncepcional oral. Nega história de câncer na família. Ela esta muito abalada e tem medo que\nseu nódulo seja um câncer. Atendendo esta paciente na Unidade de saúde da família, qual a\nmelhor conduta a ser tomada?","options":{"A":"Encaminhar para o especialista;","B":"Exame clínico, ultrassom de mamas e, após diagnóstico de nódulo confirmado considerar\nencaminhamento ao especialista;","C":"Mamografia somente;","D":"Nada a fazer."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-108790","number":"108790","sourceNumber":"108790","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Mulher de 50 anos de idade, G2P1CA1, traz mamografia mostrando aumento da\ndensidade retroareolar na mama esquerda. Ao exame clínico das mamas, detecta-se um derrame\npapilar multiductal de coloração marrom-esverdeada na mama supracitada. Com base nesses\ndados qual o diagnóstico mais provável?","options":{"A":"Carcinoma;","B":"Esteatonecrose;","C":"Ectasia ductal;","D":"Abscesso subareolar."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-84473","number":"84473","sourceNumber":"84473","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"O achado anatomopatológico em tumor de ovário, de elementos ectodérmicos como\ncartilagem e glândulas sebáceas, é compatível com o DIAGNÓSTICO DE:","options":{"A":"Tumor filoide.","B":"Teratoma.","C":"Lipoma calcificado.","D":"Fibroma.","E":"Adenocarcinoma diferenciado."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-84477","number":"84477","sourceNumber":"84477","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Quais marcadores são usados para câncer de ovário germinativo?","options":{"A":"CA-125 e CEA.","B":"Inibina e HE4.","C":"CA-125 e gonadotrofina coriônica.","D":"CEA e alfafetoproteína.","E":"Alfafetoproteína e gonadotrofina coriônica."},"answer":"E","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-84513","number":"84513","sourceNumber":"84513","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"O câncer de mama é uma das doenças com maior influência sobre a mortalidade das\nmulheres no Brasil, e o rastreamento desta doença pode ser conduzido pelos médicos na atenção\nprimária. Sobre o câncer de mama, assinale a alternativa INCORRETA:","options":{"A":"Mulheres com lesões palpáveis de mama e com menos de 35 anos de idade não devem realizar\nmamografia, e sim ultrassonografia das mamas como método de avaliação das lesões.","B":"Pacientes com mamografia classificada nas categorias BIRADS 0, 1 e 2 devem ser\nacompanhadas pelo médico no âmbito da Atenção\nPrimária, e aquelas com BIRADS 3, 4 ou 5\ndevem ser referenciados ao especialista.","C":"A ultrassonografia deve ser solicitada junto com a mamografia em todas as mulheres\nsubmetidas ao rastreamento.","D":"Mulheres assintomáticas com idade entre 50 e 69 anos que apresentam exame clínico das\nmamas e mamografia normal devem passar por\nnova avaliação clínica após um ano e repetir a\nmamografia após dois anos.","E":"Não existem evidências científicas de que o autoexame das mamas seja eficiente para o\nrastreamento e contribua para a redução\nda mortalidade por câncer de mama. Além disso, o auto\nexame traz consequências negativas, como impacto psicológico negativo nos exames falsamente\npositivos, falsa sensação de segurança nos exames falsamente negativos e aumento do número de\nbiópsias de lesões benignas."},"answer":"E","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-66960","number":"66960","sourceNumber":"66960","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Qual das situações abaixo NÃO é considerada fator de risco estabelecido para câncer\nde mama?","options":{"A":"Diagnóstico prévio de hiperplasia atípica;","B":"História familiar positiva em parentes de primeiro grau;","C":"Menarca precoce e menopausa tardia;","D":"Uso de contraceptivo hormonal oral."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-66958","number":"66958","sourceNumber":"66958","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Qual dos cânceres abaixo apresenta maior mortalidade por 100.000 mulheres no\nBrasil?","options":{"A":"Traqueia, Brônquios e Pulmões;","B":"Cólon e Reto;","C":"Colo do útero;","D":"Mama."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-66964","number":"66964","sourceNumber":"66964","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Numa marcação normal de linfonodo sentinela o coloide radioativo em TC 99 m foi\ninjetado na porção posterior do quadrante ínfero-medial da mama direita. Qual o local que irá\nreceber a maior quantidade do marcador?","options":{"A":"Plexo linfático subdiafragmático;","B":"Axila direita;","C":"Axila esquerda;","D":"Linfonodos interpeitorais (cadeia de Rotter);"},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-66968","number":"66968","sourceNumber":"66968","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Qual dessas artérias fornece maior suprimento sanguíneo para a mama?","options":{"A":"Torácica lateral;","B":"Toracoacromial;","C":"Intercostais;","D":"Subescapular."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-50122","number":"50122","sourceNumber":"50122","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma paciente está decidindo se fará ou não uma mamografia e pergunta-lhe sobre as\nvantagens e desvantagens do procedimento. Você pode responder CORRETAMENTE dizendo\nque:","options":{"A":"Uma mamografia pode ser realizada com a exposição à radiação de 1 rad;","B":"A mamografia pode ser utilizada para avaliar massas mamárias;","C":"O rastreio mamográfico de novas populações identificará cerca de um caso de câncer para cada\n1000 mulheres examinadas;","D":"A mamografia é uma técnica muito mais eficaz para o diagnóstico de câncer de mama que a\nultrassonografia;"},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-37053","number":"37053","sourceNumber":"37053","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Mulher de 45 anos, no meio do ciclo, apresenta dor em baixo ventre, ao ser solicitada\nultrassonografia transvaginal, encontra-se um cisto anecoico de 4 cm, trata-se de:","options":{"A":"Cisto dermoide.","B":"Cisto teca-luteinico.","C":"Cisto folicular.","D":"Cistoadenoma seroso.","E":"Pela idade, é mais provável tratar-se de um cistoadenocarcinoma seroso."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-37057","number":"37057","sourceNumber":"37057","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Mulher de 45 anos, no meio do ciclo, apresenta dor em baixo ventre, ao ser solicitado\nultrassonografia transvaginal, encontra-se um cisto anecóico de 4cm. No caso descrito a melhor\nconduta será:","options":{"A":"Orientação.","B":"Solicitar CA-125 e CEA.","C":"Solicitar USG com Doppler somente após os marcadores tumorais.","D":"Sendo atendida na rede básica, mandaria para centro de saúde com ginecologista.","E":"Sendo atendida na rede básica, mandaria para hospital terciário com ginecologista."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-29432","number":"29432","sourceNumber":"29432","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Mulher de 22 anos de idade, vem à consulta por apresentar nódulo na mama, ao\nexaminá-la percebe nódulo de 2 cm na mama direita, a mesma relata história de câncer de mama\nfamiliar, sua mãe teve aos 56 anos, sua conduta será:","options":{"A":"mamografia para afastar câncer de mama.","B":"ressonância nuclear magnética da mama, pois mamografia nesta idade não esclarece\ndiagnóstico.","C":"ultrassonografia de mama para diferenciar tumor sólido de cístico.","D":"indica exérese do nódulo, pois o tumor é palpável e superficial.","E":"pesquisa do BRCA para afastar câncer de origem familiar."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-341088","number":"341088","sourceNumber":"341088","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Mulher, 57 anos de idade, foi à Unidade Básica de Saúde onde foi solicitada\nultrassonografia pélvica para acompanhamento de\nmenopausa. O resultado de exame revelou\ncistos ovarianos bilaterais, sendo que o cisto à esquerda foi considerado como O-RADS 4. A\npaciente foi encaminhada ao ginecologista que solicitou uma ultrassonografia endovaginal com\nDoppler. Após o resultado desse ultimo exame houve indicação para internamento hospitalar no\nSUS. Quanto ao caráter da internação dessa paciente, o ginecologista deve informar, no pedido,\nque","options":{"A":"é de caráter de urgência, pois existe risco imediato de morte.","B":"é de caráter de urgência, pois se trata de neoplasia que deve ser abordada o quanto antes.","C":"é de caráter eletivo, pois não há riscos imediatos ou sofrimento agudo intenso.","D":"será definido após a internação, com base na realização de outros exames complementares."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-343208","number":"343208","sourceNumber":"343208","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"São considerados fatores de risco para Câncer Epitelial de Ovário, exceto:","options":{"A":"Síndrome de Lynch.","B":"Raça branca.","C":"Salpingectomia prévia.","D":"Mutação nos genes BRCA 1 e 2."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-307054","number":"307054","sourceNumber":"307054","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Mulher, 72 anos de idade, hipertensa e com obesidade grau 1, vem, há um mês,\nreferindo aumento do volume abdominal e dispneia\nleve. Realizou ultrassonografia pélvica que\nevidenciou lesão sólida em ovário esquerdo, hipoecóica, bem delimitada, sem fluxo ao Doppler, de\n2,0cm, com sombra acústica posterior; presença de grande volume de líquido livre em cavidade.\n\nExame de imagem evidenciou derrame pleural. Nega perda ponderal. Feito estudo de CA-125 que\nveio em baixos níveis. Diante do caso, identifique o tumor ovariano mais provável:","options":{"A":"Fibroma.","B":"Disgerminoma.","C":"Carcinoma seroso.","D":"Carcinoma endometrioide."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-307055","number":"307055","sourceNumber":"307055","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Mulher, 72 anos de idade, hipertensa e com obesidade grau 1, vem, há um mês,\nreferindo aumento do volume abdominal e dispneia\nleve. Realizou ultrassonografia pélvica que\nevidenciou lesão sólida em ovário esquerdo, hipoecóica, bem delimitada, sem fluxo ao Doppler, de\n2,0cm, com sombra acústica posterior; presença de grande volume de líquido livre em cavidade.\n\nExame de imagem evidenciou derrame pleural. Nega perda ponderal. Feito estudo de CA-125 que\nveio em baixos níveis. Indique o diagnóstico sindrômico mais provável para o caso:","options":{"A":"Síndrome Carcinoide.","B":"Síndrome de Meigs.","C":"Síndrome de Cushing.","D":"Síndrome de Fitz-Hugh-Curtis."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-307056","number":"307056","sourceNumber":"307056","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Mulher, 72 anos de idade, hipertensa e com obesidade grau 1, vem, há um mês,\nreferindo aumento do volume abdominal e dispneia\nleve. Realizou ultrassonografia pélvica que\nevidenciou lesão sólida em ovário esquerdo, hipoecóica, bem delimitada, sem fluxo ao Doppler, de\n2,0cm, com sombra acústica posterior; presença de grande volume de líquido livre em cavidade.\n\nExame de imagem evidenciou derrame pleural. Nega perda ponderal. Feito estudo de CA-125 que\nveio em baixos níveis. Especifique a conduta inicial que deve ser adotada nesse caso,\nconsiderando a principal hipótese diagnóstica:","options":{"A":"Quimioterapia.","B":"Salpingooforectomia esquerda.","C":"Salpingooforectomia bilateral, histerectomia e citorredução ótima.","D":"Salpingooforectomia bilateral seguido de quimioterapia."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-315195","number":"315195","sourceNumber":"315195","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"A mamografia é o exame preconizado para o rastreamento do câncer de mama. Sobre\no sistema de classificação Bi-Rads para\nachados mamográficos e orientação de seguimento,\nassinale a alternativa CORRETA.","options":{"A":"A classificação Bi-Rads 0 significa que o achado foi suspeito e deve prosseguir investigação com\nultrassonografia.","B":"A classificação Bi-Rads 1 significa que o achado foi de lesão benigna e não demanda prosseguir\ninvestigação.","C":"A classificação Bi-Rads 2 significa que o achado foi de lesão benigna.","D":"A classificação Bi-Rads 6 refere-se a uma lesão maligna ainda sem confirmação por exame\nhistopatológico.","E":"A classificação Bi-rads 0 significa exame inconclusivo e que não demanda prosseguir\ninvestigação."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-314228","number":"314228","sourceNumber":"314228","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Mulher de 26 anos vai ao consultório referindo nódulo na mama esquerda há 15 dias.\nNulípara, nega antecedentes familiares de câncer de mama. Ao exame físico das mamas apresenta\nnódulo fibroelástico, móvel, de 2,5 cm no quadrante superior lateral da mama esquerda, sem sinais\nflogísticos, sem retração de pele, axilas e fossas supraclaviculares livres. Diante da história\nclínica e\nexame físico, o mais provável diagnóstico e exame complementar são, respectivamente:","options":{"A":"nódulo benigno, ultrassonografia.","B":"câncer de mama, mamografia.","C":"nódulo benigno, mamografia.","D":"mastite, mamografia."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-279076","number":"279076","sourceNumber":"279076","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"A alteração mamária congênita ocasionada por agenesia da porção esternal do\nmúsculo peitoral maior tem o nome de","options":{"A":"Síndrome de Sthein-Leventhal.","B":"Síndrome de Morrisom.","C":"Doença de Mondor.","D":"Síndrome de Poland."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-278135","number":"278135","sourceNumber":"278135","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Segundo a Sociedade Brasileira de Mastologia, para mulheres entre 40 e 69 anos, a\nindicação de rastreamento mamário incluindo o ultrassom de mamas deve ser realizada em caso\nde","options":{"A":"antecedente de fibroadenoma.","B":"mamas densas à mamografia.","C":"antecedente familiar.","D":"antecedente de primeiro parto após os 30 anos de idade."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-279086","number":"279086","sourceNumber":"279086","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"O uso do ultrassom em rastreamento mamário apresenta como principal limitação a\ndificuldade de visualização de","options":{"A":"nódulos sólidos.","B":"microcalcificações agrupadas.","C":"Fibroadenomas.","D":"cistos espessos."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-231372","number":"231372","sourceNumber":"231372","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Qual dos seguintes é o melhor tratamento para a suspeita de um cisto dermóide\nencontrado em uma nulípara de 18 anos de idade?","options":{"A":"Histerectomia abdominal total","B":"Salpingo-ooforectomia unilateral","C":"Cistectomia ovariana","D":"Salpingo-cistectomia ovariana","E":"observação"},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-249437","number":"249437","sourceNumber":"249437","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente procura mastologista com queixa de descarga papilar. No exame das mamas\nfica evidente que se trata de fluxo benigno\nporque este é:","options":{"A":"Uniductal, bilateral.","B":"Uniductal, unilateral.","C":"Multiductal, unilateral.","D":"Multiductal, bilateral."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-219865","number":"219865","sourceNumber":"219865","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Com relação à mamografia para rastreamento do câncer de mama na mulher, assinale\na alternativa INCORRETA:","options":{"A":"A sensibilidade desse exame varia de acordo com o tamanho da lesão e da densidade das\nmamas.","B":"Diante do laudo de \"achado suspeito\" classificar a mamografia como categoria 5 e encaminhar\npara mastologista.","C":"Diante do laudo de mamografia categoria 3 é recomendado o controle radiológico por 3 anos.","D":"Não indicar mamografia na ausência de sintomas ou suspeita clínica em pacientes com menos\nde 49 anos."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-215531","number":"215531","sourceNumber":"215531","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Os teratomas são tumores embrionários derivados das células germinativas, mais\nfrequentemente com componentes de, pelo menos, dois folhetos embrionários: ecto e mesoderma.\nAssinale a alternativa INCORRETA com relação ao teratoma sacrococcígeo.","options":{"A":"É o tumor mais comum no período neonatal, representando de 37 a 52% de todas as neoplasias\ncongênitas e apresentando incidência de cerca de 1:35.000 nascidos vivos/ano.","B":"O tumor pode apresentar períodos de crescimento acelerado, que leva a um aumento do volume\nplacentário e à hidropsia fetal.","C":"Tumores muito volumosos podem produzir compressão cardíaca e consequente insuficiência\ncardíaca com evolução para hidropsia.","D":"O polidrâmnio associado a tumores volumosos por si só pode promover trabalho de parto\nprematuro, ou rotura prematura de membranas, aumentando, assim a mortalidade associada a\nesses tumores."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-212194","number":"212194","sourceNumber":"212194","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Assinale a alternativa que afirma CORRETAMENTE características frequentes de\ntumores ovarianos benignos:","options":{"A":"Cisto multilocular, parede lisa, bordas irregulares.","B":"Parede lisa, componentes sólidos, cisto multilocular.","C":"Parede lisa, ausência de ascite, sem septos internos.","D":"Cisto unilocular, presença de componentes sólidos, sem septos internos.","E":"Bordas irregulares, presença de ascite, espessamento na parede do tumor."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-212232","number":"212232","sourceNumber":"212232","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"As doenças benignas da mama incluem todas as condições não malignas e\nclassicamente não aumentam o risco para\nmalignidade. Na maioria dos casos, o acompanhamento\ncom exames de imagem é o procedimento mais indicado. Porém, em algumas dessas patologias,\ndeve ser optado para exérese da lesão como, por exemplo, as que possuem um crescimento\nprogressivo não maligno. Diante do exposto, qual das doenças benignas, com base no achado\nhistológico por biópsia, não tem indicação de exérese?","options":{"A":"Lesão esclerosante complexa.","B":"Papiloma intraductal.","C":"Cicatriz radiada.","D":"Tumor filoide.","E":"Hamartoma."},"answer":"E","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-215260","number":"215260","sourceNumber":"215260","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"A presença de granuloma lipofágico que ocorre em mama exposta ao trauma e que\npode simular câncer leva o nome de:","options":{"A":"Citoesteatonecrose.","B":"Eczema areolar.","C":"Ectasia ductal.","D":"Doença de Mondor."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-215490","number":"215490","sourceNumber":"215490","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"O principal fator de risco isolado para câncer de mama é:","options":{"A":"Idade.","B":"Antecedente familiar.","C":"Nuliparidade.","D":"Uso de terapia de reposição hormonal."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-215521","number":"215521","sourceNumber":"215521","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Mulher de 32 anos com descarga papilar procura o ginecologista, preocupada com a\npossibilidade de se tratar de câncer de mama. Das situações abaixo, aquela que representa menor\nrisco de câncer de mama é descarga:","options":{"A":"Multiductal, bilateral, amarelada.","B":"Uniductal, bilateral, esbranquiçada.","C":"Multiductal, unilateral, cristalina.","D":"Multiductal, unilateral, serossanguínea."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-181300","number":"181300","sourceNumber":"181300","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Em relação às neoplasias de mama, assinale a alternativa correta.","options":{"A":"Os fatores de risco para neoplasias de mama são menarca e menopausa precoces e\nmultiparidade.","B":"Pacientes com neoplasia de ovário com doença residual se beneficiam da mastectomia bilateral\nprofilática.","C":"História familiar de câncer de mama não representa sinônimo de herança de mutação de BRCA1\ne BRCA2.","D":"Pacientes com mutação de BRCA1 e BRCA2 que nunca tiveram câncer se beneficiam de\nquimioprevenção com tamoxifeno.","E":"O gene BRCA 1 está envolvido no desenvolvimento do câncer, pois sua atividade inativa a\nregulação do ciclo celular da glândula mamária."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-180112","number":"180112","sourceNumber":"180112","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente de 37 anos apresenta ultrassonografia transvaginal demonstrando massa\nanexial cística de pequeno volume e sem novivascularização ao estudo do Doppler. Esse quadro\nsugere","options":{"A":"Cisto folicular ovariano.","B":"Prenhez ectópica.","C":"Tumor maligno do ovário.","D":"Abscesso tubovariano","E":"Nenhuma resposta acima."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-183078","number":"183078","sourceNumber":"183078","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Em relação ao uso de marcadores tumorais em ginecologia, assinale a alternativa\nINCORRETA:","options":{"A":"São substâncias produzidas pelos tumores e encontradas no sangue periférico.","B":"Podem auxiliar na confirmação diagnóstica.","C":"Tem alta especificidade, identificando inclusive o tipo histológico do tumor em quase todos os\ncasos.","D":"Servem como indicador da persistência de células neoplásicas após o tratamento cirúrgico."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-181324","number":"181324","sourceNumber":"181324","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente deu entrada na emergência com dor abdominal, principalmente em fossa\nilíaca esquerda. Foi submetida a ultrassom com\nsuspeita de torção ovariana. Dentre os tumores\novarianos, qual o mais provável responsável pelo quadro em questão?","options":{"A":"Sarcoma ovariano.","B":"Cistoadenoma seroso.","C":"Endometrioma ovariano.","D":"Adenocarcinoma de ovário.","E":"Cisto dermoide (teratoma maduro)."},"answer":"E","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-182803","number":"182803","sourceNumber":"182803","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"As veias ovarianas direita e esquerda drenam, respectivamente, para:","options":{"A":"Veia renal direita e veia cava inferior.","B":"Veia cava inferior e veia renal esquerda.","C":"Ambas para a veia cava inferior.","D":"Veia renal direita e veia renal esquerda."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-152674","number":"152674","sourceNumber":"152674","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Qual o principal fator prognóstico independente no câncer de mama em suas fases\niniciais?","options":{"A":"Tamanho tumoral na mamografia e no estudo\nanatomopatológico (considerar o maior tamanho).","B":"Determinação do Her-2 por hibridização in situ por\nfluorescência (FISH).","C":"Status dos linfonodos axilares após avaliação cirúrgica por biópsia de linfonodo sentinela ou por\ndissecção linfonodal axilar completa.","D":"Determinação do Ki-67 por estudo imunohistoquímico.","E":"Tamanho tumoral na ultrassonografia."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-161128","number":"161128","sourceNumber":"161128","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Indique a alternativa que contém a MELHOR conduta em caso de Hipertrofia Mamária\ndo recém-nascido.","options":{"A":"Radioterapia.","B":"Expectante.","C":"Quimioterapia.","D":"Biópsia."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-161132","number":"161132","sourceNumber":"161132","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Em relação aos fatores de risco para câncer de mama, marque a opção INCORRETA.","options":{"A":"Menarca precoce é fator de risco.","B":"Primeira gestação após os 30 anos é fator de risco.","C":"Terapia de reposição hormonal na menopausa, mesmo que por curto período de tempo, é fator\nde risco para câncer de mama.","D":"Menopausa tardia é fator de risco."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-161322","number":"161322","sourceNumber":"161322","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Em relação às descargas papilares, marque a opção INCORRETA.","options":{"A":"As descargas multiductais, que ocorrem somente após expressão mamária, são consideradas\nfisiológicas na maioria das vezes.","B":"A gravidez é causa frequente de descarga espontânea.","C":"Em caso de descarga uniductal, o exame físico cuidadoso pode detectar o ponto de gatilho no\ncanto areolar que induz a descarga quando é pressionado.","D":"Secreções translúcidas ou sanguinolentas são de caráter benigno, necessitando apenas\ncomplementação ultrassonográfica para controle."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-134857","number":"134857","sourceNumber":"134857","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Em relação à Mastectomia Radical, pode-se afirmar que","options":{"A":"A reconstrução com prótese é possível, sem necessidade de mobilização de retalhos\nmusculares.","B":"Apenas em 15% dos casos obtém-se a cura do câncer de mama, a não ser que realize\nmastectomia profilática da mama, sem neoplasia.","C":"É o procedimento mais realizado para o tratamento definitivo do câncer de mama.","D":"a mama e os músculos peitorais subjacentes são sacrificados e, também, os linfonodos\nregionais ao longo da veia axilar até o ligamento costo clavicular."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-134322","number":"134322","sourceNumber":"134322","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"São indicações da realização de PET/CT em câncer de mamas, EXCETO uma das\nelencadas abaixo. Marque-a.","options":{"A":"Estadiamento pré-operatório da axila clinicamente negativa.","B":"Doenças localmente avançadas.","C":"Investigar metástases ocultas.","D":"Monitorar resposta terapêutica das metástases."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-134850","number":"134850","sourceNumber":"134850","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente de 55 anos apresentando microcalcificações agrupadas na mama\ndireita, em quadrante superior externo, ao exame de mamografia, nas 2 incidências e na\ncompressão localizada com magnificação. Qual é a conduta APROPRIADA para esse caso?","options":{"A":"Ultrassonografia mamária.","B":"Punção aspirativa com agulha fina (PAAF).","C":"Biópsia guiada por agulhamento prévio.","D":"Setorectomia de mama direita."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-134081","number":"134081","sourceNumber":"134081","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Qual é a alternativa em que todos os fatores são conhecidamente de risco para\ndesenvolvimento do câncer de mama?","options":{"A":"Idade, sexo, promiscuidade sexual, alto nível socioeconômico e hereditariedade.","B":"História familiar, sexo e baixo nível socioeconômico.","C":"Idade, sexo, história familiar, exposição à radiação ionizante, alto nível socioeconômico e\ningestão de álcool.","D":"Promiscuidade sexual, sexo, idade e obesidade."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-134088","number":"134088","sourceNumber":"134088","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente de 53 anos de idade, assintomática, realizou mamografia de rastreamento em\nque foi encontrado lesão nodular com\nbordos microlobulados em quadrante ínfero-interno da mama\ndireita. O laudo da mamografia é compatível com Bi-Rads 0. O exame físico é normal e a paciente\nnão tem qualquer antecedente derisco para câncer de mama. Qual é a conduta?","options":{"A":"Quadrantectomia com exame histológico intraoperatório (congelação).","B":"Ressonância nuclear magnética da mama.","C":"Ultrassonografia mamária.","D":"Punção biópsia aspirativa nos dois quadrantes internos."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-4-134118","number":"134118","sourceNumber":"134118","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Grande número de cirurgias ginecológicas deve-se ao diagnóstico de tumores anexiais.\nEstes são encontrados em todas as fases da\nvida da mulher, podendo gerar dúvidas quanto à\nnecessidade de indicação cirúrgica. Analisando os aspectos prognósticos clínicos e\nultrassonográficos, assinale a alternativa CORRETA.","options":{"A":"A suspeita de cisto funcional só será pertinente se a paciente for jovem e se o volume for\npequeno, uma vez que esses cistos não\n\natingem grandes dimensões.","B":"Tumores sólidos, porém multiloculados são benignos na maioria dos casos.","C":"Cistos de paredes finas e sem projeções papilares para seu interior têm valor preditivo para\nbenignidade.","D":"A frequência do teratoma cístico benigno aumenta com a idade da paciente."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-110561","number":"110561","sourceNumber":"110561","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"O principal exame de rastreamento do câncer de mama é:","options":{"A":"Autoexame das mamas.","B":"Ressonância magnética.","C":"Mamografia.","D":"Ultrassonografia.","E":"Tomografia."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-110590","number":"110590","sourceNumber":"110590","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Com relação à classificação de BIRADS, podemos afirmar que BIRADS I corresponde\na:","options":{"A":"lesão de difícil avaliação pelo alta densidade tecidual que necessita de exame complementar.","B":"exame normal, sem qualquer alteração.","C":"lesão provavelmente maligna, necessitando de biópsia.","D":"lesão provavelmente benigna, necessitando de controle semestral.","E":"lesão maligna, positivo para neoplasia."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-109759","number":"109759","sourceNumber":"109759","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente, 33 anos, refere antecedente na família de câncer de mama (mãe), aos 40\nanos de idade. Diante de tal caso, qual é a\nMELHOR conduta?","options":{"A":"Realizar mamografia anual.","B":"Realizar exame de palpação mamária semestral.","C":"Realizar PAAF anual.","D":"Realizar core biopsy anual."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-109981","number":"109981","sourceNumber":"109981","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Na Anatomia Mamária existem traves de tecido fibroso, interlobulares da mama, que\nsão conhecidos como ligamentos suspensores de:","options":{"A":"Halsted.","B":"Urban.","C":"Cooper.","D":"Bell."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-109794","number":"109794","sourceNumber":"109794","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Ao realizar exame de ultrassonografia mamária, devido à mastalgia, paciente de 40\nanos, vem exame mostrando tumoração em mama direita às 12 horas, medindo 3,0 cm, irregular,\ncom sombra acústica posterior, heterogênea. Diante de tal caso, qual é a MELHOR conduta?","options":{"A":"Realizar core biopsy.","B":"Realizar ultrassonografia em 6 meses.","C":"Realizar PAAF.","D":"Realizar mastectomia."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-110044","number":"110044","sourceNumber":"110044","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Em relação à drenagem venosa ovariana esquerda, ou seja, a vascularização venosa\ndo ovário esquerdo ocorre para a veia","options":{"A":"cava inferior.","B":"renal.","C":"ilíaca.","D":"hipogástrica."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-158401","number":"158401","sourceNumber":"158401","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente em acompanhamento de tratamento de câncer de ovário (epitelial). Qual a\nmelhor opção em relação aos marcadores tumorais?","options":{"A":"CA-19-9 e Alfafetoproteína.","B":"CA 19-9 e CA 15-3.","C":"CA 19-9 e CEA.","D":"CA 125 e CEA.","E":"CA 19-9 e hCG."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-108602","number":"108602","sourceNumber":"108602","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Qual dos itens a seguir é o principal fator de risco para o desenvolvimento do câncer de\nmama?","options":{"A":"Tabagismo.","B":"Aumento na ingestão de gordura.","C":"História familiar de câncer de mama.","D":"Primiparidade tardia.","E":"Hiperplasia epitelial atípica."},"answer":"E","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-108603","number":"108603","sourceNumber":"108603","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Na terminologia BI-RADS (American College of Radiology Breast Imaging Reporting\nand Data System), a designação 0 (zero) quer\ndizer:","options":{"A":"Mamografia normal.","B":"Lesão provavelmente benigna.","C":"Lesão benigna.","D":"Suspeita de malignidade.","E":"Necessita de avaliação adicional."},"answer":"E","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-49606","number":"49606","sourceNumber":"49606","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"O tipo histológico mais comum de neoplasia maligna da mama é:","options":{"A":"Carcicoma inflamatório.","B":"Ductal in situ.","C":"Paget.","D":"Carcinoma lobular infiltrante.","E":"Carcinoma ductal infiltrante."},"answer":"E","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-13130","number":"13130","sourceNumber":"13130","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Intervalo recomendado para mamografia em mulheres assintomáticas, pela Sociedade\nBrasileira de Mastologia:","options":{"A":"básica entre 35-40 anos, anual após 40 anos.","B":"básica aos 40 anos e anual após 50 anos.","C":"básica aos 40 anos e anual após 40 anos.","D":"básica aos 40 anos e bianual após 50 anos.","E":"básica aos 35 anos e bianual após 50 anos."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-13131","number":"13131","sourceNumber":"13131","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Qual tipo histológico mais frequente do câncer de mama?","options":{"A":"Carcinoma papilifero da mama.","B":"Adenocarcinoma da mama.","C":"Carcinoma ductal invasivo.","D":"Carcinoma inflamatório.","E":"Carcinoma lobular da mama."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-362496","number":"362496","sourceNumber":"362496","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente 38 anos foi ao mastologista com resultado de ultrassonografia, evidenciando\nnódulo complexo sólido cístico, de forma oval,\nmargens circunscritas, medindo 12 x 10 mm,\nlocalizado em quadrante supero-lateral da mama direita. Qual classificação Bi Rads e conduta\nrecomendada?","options":{"A":"Bi Rads 3, reavaliar em 6 meses.","B":"Bi Rads 2, controle anual.","C":"Bi Rads 4B, core biopsy.","D":"Bi Rads 0, complementar com mamografia."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-362495","number":"362495","sourceNumber":"362495","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente 40 anos foi ao mastologista com resultado de ultrassonografia evidenciando\nimagem cística, de forma oval, margens\ncircunscritas, com conteúdo espesso, medindo 18x12 mm,\nlocalizado em quadrante supero lateral da mama direita. Qual classificação Bi Rads e conduta\nrecomendada?","options":{"A":"Bi Rads 4B, core biopsy.","B":"Bi Rads 2, controle anual.","C":"Bi Rads 3, reavaliar em 6 meses.","D":"Bi Rads 0, complementar com mamografia."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-362468","number":"362468","sourceNumber":"362468","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Assinale a alternativa CORRETA sobre drenagem venosa da veia ovariana:","options":{"A":"À direita desemboca na veia renal predispondo a varicosidades.","B":"À esquerda desemboca na veia renal predispondo a varicosidades.","C":"Ambas desembocam na veia cava inferior sendo a chance de varicosidade igual em ambos os\nlados.","D":"Ambas desembocam na veia renal do respectivo lado, sendo a chance de varicosidade igual em\nambos os lados."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-327256","number":"327256","sourceNumber":"327256","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente do sexo feminino, 13 anos, vem à consulta médica queixando dor em FID e\npélvica, de leve intensidade, há 1 mês. Nega vômitos, febre e alterações do hábito intestinal.\nRefere\nmenarca aos 12 anos, com ciclos menstruais irregulares. Ao exame físico, a paciente se encontra\nnormocorada, eupneica, afebril, hemodinamicamente estável. Exame cardiorrespiratório sem\nalterações. Seu abdome é plano, flácido, discretamente doloroso à palpação profunda em FIE e\nhipogástrio, onde se palpa massa sólida, firme e móvel. Qual o próximo passo para a investigação\ndiagnóstica e seu provável achado?","options":{"A":"Ultrassonografia de abdome - Massa ovariana mista com focos de calcificação.","B":"Ultrassonografia transvaginal e dosagem de Beta-HCG - Prenhez tubária não rôta.","C":"Ressonância Magnética de pelve - Hidrossalpinge.","D":"Radiografia de abdome - Fecaloma."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-327262","number":"327262","sourceNumber":"327262","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente 30 anos, foi ao ambulatório de ginecologia com dor mamária referindo nódulo\nem mama esquerda. Levou ultrassonografia com achado de imagem anecóica, de paredes lisas,\ncom reforço acústico posterior, medindo 40 mm. Qual a melhor conduta para este caso?","options":{"A":"Puncão por agulha fina","B":"Core biopsy","C":"Mamografia","D":"Ressonancia Magnética"},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-298233","number":"298233","sourceNumber":"298233","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente 33 anos, realizou ultrassonografia transvaginal que evidenciou imagem cística\nanecóica unilocular que mede 28 mm em seu maior diâmetro. Qual a conduta adequada?","options":{"A":"Não necessita de seguimento","B":"Iniciar anticoncepcional oral","C":"Reavaliar em 3 meses","D":"Retirada por laparoscopia"},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-298238","number":"298238","sourceNumber":"298238","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Qual a classificação BI RADS de um nódulo mamário espiculado, de contornos\nirregulares, sombra acústica posterior, vascularização central à Dopplervelocimetria?","options":{"A":"6","B":"5","C":"4","D":"3"},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-298282","number":"298282","sourceNumber":"298282","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Durante a campanha do Outubro Rosa, você recebe um ofício circular da Secretaria de\nSaúde informando que, tendo em vista o apoio a\ncampanha, a Secretaria contratou empresa que\nrealiza serviços de mamografia e que não haverá restrição no número de exames a serem\nrealizados durante este mês. Muitas mulheres vêm à unidade de saúde solicitar que sejam\nsubmetidas à mamografia. Várias delas não estão dentro da faixa preconizada para o rastreamento\ncom o exame e algumas já foram submetidas ao exame no ano passado, estando o resultado sem\nalteração que sugerisse outra etapa para o rastreamento. Com base no melhor conhecimento\ncientífico existente, o médico de família deve:","options":{"A":"Oferecer o exame para as mulheres dentro da faixa etária e periodicidade preconizadas pelo\nINCA / Ministério da Saúde.","B":"Solicitar mamografia para as pacientes entre 40 e 65 anos e naquelas acima de 65 e abaixo de\n40 anos, solicitar ultrassonografia das mamas\ncomo rastreamento.","C":"Relativizar as informações, porque as condutas recomendadas pelo Ministério da Saúde devem\nser aplicadas em situações de recursos escassos\ne como não há restrição, ampliar a faixa etária\npara mulheres, a partir dos 40 anos.","D":"Aproveitar a oportunidade de não haver restrição na oferta de exames e solicitar mamografia\npara todas as mulheres que desejam ser submetidas\nao exame"},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-286757","number":"286757","sourceNumber":"286757","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente 35 anos vai ao ginecologia com laudo mamográfico de Bi rads 0. Qual o\nsignificado deste resultado?","options":{"A":"Necessária complementação por outro método de imagem.","B":"Mama normal seguimento anual.","C":"Necessária core biopsy de mama para definir diagnóstico.","D":"Alta suspeição para lesão maligna da mama."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-286758","number":"286758","sourceNumber":"286758","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente 22 anos, foi ao hospital da mulher com dor pélvica de início súbito em fossa\nilíaca direita, náuseas e vômitos. Ao exame\nfísico observou-se dor intensa e massa palpável em\ntopografia anexial. a ultrassonografia evidenciou ovário direito aumentado de volume e líquido livre\nem fundo de saco posterior. O estudo Doppler não identificou nenhum tipo de fluxo. Qual a hipótese\ndiagnóstica?","options":{"A":"Torção ovariana","B":"Endometrioma","C":"Tumor de ovário","D":"Doença Inflamatória pélvica"},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-252259","number":"252259","sourceNumber":"252259","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Na categoria de BI-RADS 3 da mamografia, qual a conduta mais apropriada e qual risco\nde malignidade está associada?","options":{"A":"Controle mamográfico de 6/6 meses, risco de 2%.","B":"Controle mamográfico anual, risco de 10%.","C":"Investigação histopatológica e risco de 30%.","D":"Controle com USG e risco de 8%."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-252267","number":"252267","sourceNumber":"252267","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente realizou ultrassonografia mamária que evidenciou nódulo de forma oval,\nparalela a pele, margens circunscritas e conteúdo anecóico. Qual classificação BI-RADS e\nconduta?","options":{"A":"Bi-rads 3, controle anual.","B":"BI-RADS 3, controle semestral.","C":"BI-RADS 2, controle semestral.","D":"BI-RADS 2, controle anual."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-176094","number":"176094","sourceNumber":"176094","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente do sexo feminino, 18 anos, dá entrada no pronto atendimento queixando-se\nde dor de início súbito, em fossa ilíaca\ndireita, tipo contínua, há cerca de 8 horas, associada a\nnáuseas e vômitos. A dor tinha intensidade moderada mas passou a ser intensa rapidamente e não\ncedia ao uso de sintomáticos no domicílio. Nega febre. Refere leucorreia esbranquiçada sem odor e\nciclo menstrual irregular. Encontra-se em BEG, eupneica, afebril, FC = 70 bpm, P.A = 120 x\n80mmHg. Seu abdome é doloroso à palpação profunda na FID, sem sinais de irritação peritoneal.\n\nHematócrito: 38%; hemoglobina: 12 g/dl e leucograma: 6.500, sem desvio à esquerda. BHCG\nnegativo. A USG evidencia massa sólida de\n15 cm em posição retrouterina. Assinale a alternativa\nCORRETA:","options":{"A":"A ausência de irritação peritoneal e febre afasta a possibilidade de tratamento cirúrgico\nurgente.","B":"A utilização do Doppler colorido à USG seria importante na definição do diagnóstico desta\npaciente.","C":"O padrão de dor contínua de início súbito confirma abdome agudo hemorrágico, estando\ncontraindicado o acesso laparoscópico no seu tratamento.","D":"A presença de leucorreia sugere o diagnóstico de doença inflamatória pélvica, estando indicada\na internação hospitalar para antibioticoterapia e\nobservação clínica por 48h."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-176006","number":"176006","sourceNumber":"176006","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente foi ao pronto-socorro referindo dor abdominal de moderada intensidade, que\nteve início há 6 horas. Refere náuseas e vômitos. Ao exame físico, o ginecologista palpou uma\nmassa em anexo direito. O ultrassom evidenciou imagem cística anecoica com áreas hipoecoicas\nmedindo aproximadamente 12 cm. Ao Doppler, não foi observado fluxo na artéria ovariana.\n\nAssinale a alternativa CORRETA:","options":{"A":"Diagnóstico: teratoma; conduta: cirurgia.","B":"Diagnóstico: endometrioma; conduta: goserelina.","C":"Diagnóstico: cisto ovariano funcional; conduta: anticoncepcional.","D":"Diagnóstico: torção ovariana; conduta: cirurgia."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-176010","number":"176010","sourceNumber":"176010","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente de 41 anos realizou mamografia de rotina que evidenciou assimetria focal.\nQual a classificação BI-RADS (5ª edição) e qual a conduta a ser adotada?","options":{"A":"BI-RADS 2; acompanhamento anual.","B":"BI-RADS 3; acompanhamento semestral.","C":"BI-RADS 4; biópsia.","D":"BI-RADS 5; tratamento."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-151876","number":"151876","sourceNumber":"151876","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente 34 anos assintomática, fez ultrassonografia de rotina, que diagnosticou:\nnódulo hipoecólico, sólido, ovoide paralelo a\npele, de contornos regulares, eixo horizontal maior que\no vertical. Qual a classificação BI-RADS:","options":{"A":"I.","B":"III.","C":"IV B.","D":"V."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-151908","number":"151908","sourceNumber":"151908","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente, 60 anos, menopausada há 9 anos, refere dor abdominal com perda de\napetite, emagrecimento de 8 kg em 6 meses. Ao exame\nfísico, observa-se distensão abdominal\nacentuada, com massa palpável fixa em topografia de hipogástrio. Sinal do piparote presente. Ao\nultrassom, evidenciou-se massa sólido cística ovariana, bilateral hipervascularizada, medindo 12\ncm e 18 cm. Baseado na hipótese diagnóstica, assinale a afirmativa CORRETA:","options":{"A":"O estadiamento dessa patologia é cirúrgico.","B":"Não se faz citorredução nos casos de suspeita de tumor de ovário.","C":"Pode se fazer como tratamento adjuvante a quimioterapia de kluster et al.","D":"Massa ovariana bilateral com ultrassonagrafia evidenciando massa complexa, mas com ca125\nnormal. Pode ser reavaliada em 6 meses."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-129772","number":"129772","sourceNumber":"129772","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Giovanna, 38 anos, parda, tabagista, etilista de 3 copos de cerveja/dia, sedentária,\nGesta zero Para zero. Menarca aos 11 anos, faz\nuso de anticoncepcional oral há 20 anos. Tem de\naltura 1,50 m e pesa 103 kg. Ao realizar o auto exame de mama, observou um nódulo de contorno\nirregular de aproximadamente 2 cm. Procurou o ginecologista que palpou um nódulo ao exame\nfísico e solicitou uma ultrassonografia mamária. A ultrassonografia diagnosticou nódulo sólido\nhipoecoico com eixo vertical maior que o horizontal, e o classificou como BI RADS 3. A conduta\nmais adequada é:","options":{"A":"Segmento anual.","B":"Biopsia (PAAF).","C":"Segmento semestral.","D":"Exérese do nódulo."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-103867","number":"103867","sourceNumber":"103867","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"A causa mais comum de descarga papilar espontânea, proveniente de ducto único da\nmama, caracteriza:","options":{"A":"Ectasia ductal retroalveolar.","B":"Galactorreia.","C":"Papiloma intraductal solitário.","D":"Doença de Paget."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-107902","number":"107902","sourceNumber":"107902","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paula, durante a aula de Muay Thai, sentiu uma forte dor abdominal com náuseas e\nvômitos. Imediatamente foi ao hospital. Ao exame físico tinha dor a palpação abdominal, dor à\ndescompressão nos quadrantes inferiores e uma massa palpável na fossa ilíaca esquerda. Foi\nsolicitada USG que evidenciou massa anexial unilocular hiperecóica de 6 x 5 cm. Assinale a\nalternativa CORRETA:","options":{"A":"A principal hipótese diagnóstica é torção anexial e o tratamento é expectante com\nhiperhidratação, antiespamódicos.","B":"A principal hipótese diagnóstica é leiomioma parido e o tratamento é cirúrgico.","C":"A principal hipótese diagnóstica é Leiomioma degenerado e o tratamento é expectante com\nhiperhidratação, antiespasmódicos.","D":"A principal hipótese diagnóstica é torção anexial e o tratamento é cirúrgico."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-107910","number":"107910","sourceNumber":"107910","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Assinale a alternativa CORRETA:","options":{"A":"O carcinoma inflamatório da mama é semelhante ao eczema. A erosão resulta de invasão de\npapila e aréola adjacente por células grandes e características com núcleos irregulares.","B":"A doença de Paget parece ser uma inflamação aguda com eritema e edema. Deve ser\ndiagnosticado quando há envolvimento de mais de um terço da mama com eritema e edema, e\nquando a biópsia dessa área mostra câncer metastático nos linfáticos subdérmicos.","C":"A maioria das mulheres com carcinoma lobular está na pós menopausa. O tumor é uma lesão\nmultifocal em uma ou ambas as mamas encontrada incidentalmente.","D":"Tanto o carcinoma lobular quanto o carcinoma ductal podem estar contidos pela membrana\nbasal dos ductos. Esses carcinomas não invadem\no tecido adjacente e teoricamente não são\ncapazes de se disseminar."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-4-107916","number":"107916","sourceNumber":"107916","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Adriana, 30 anos, foi ao ginecologista com queixa de aumento de volume abdominal.\nAo exame físico, o abdome estava distendido\ncom sinal de Piparote positivo e havia massa\npalpável em região abdominal. Foi solicitado uma ultrassonografia que evidenciou imagem cística\ncom septações grosseiras, com vascularização e vegetações. O Rx evidenciou nódulos pulmonares\ne derrame pleural. A tomografia de crânio observou nódulos cerebrais. A ressonância detectou\ntumoração volumosa bilateral com metástases hepáticas. De acordo com o estadiamento da FIGO,\nem qual estágio podemos classificar essa paciente:","options":{"A":"IIIa","B":"IIIb","C":"IIIc","D":"IV"},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-103877","number":"103877","sourceNumber":"103877","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"O câncer de mama é o mais incidente em mulheres, representando 23% do total de\ncasos de câncer no mundo, em 2008, com\naproximadamente 1,4 milhão de casos novos naquele\nano. A taxa de mortalidade por câncer de mama, ajustada pela população mundial, apresenta uma\ncurva ascendente e representa a primeira causa de morte por câncer na população feminina\nbrasileira. Sobre o câncer de mama, marque a alternativa CORRETA:","options":{"A":"A recomendação para as mulheres de 50 a 69 anos é a realização de mamografia a cada dois\nanos e do exame clínico das mamas anual.","B":"Nas mulheres com 35 anos ou mais com risco elevado para câncer de mama, o exame clínico\ndas mamas deve ser anual e a mamografia\nbianual.","C":"Os principais fatores de risco conhecidos para o câncer de mama estão ligados à idade, aos\nfatores genéticos e aos endócrinos, como idade,\nmenarca tardia, menopausa precoce e obesidade.","D":"Os principais sítios de metástases do câncer de mama são cérebro, ovário e pele, e com menor\nfrequência ossos, pulmões e pleura, fígado."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-87417","number":"87417","sourceNumber":"87417","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Jorgeana 26 anos foi ao mastologista pois tinha história familiar de câncer de mama.\nFoi solicitado uma ultrassonografia cujo diagnóstico foi: BI RADS 3. Na classificação BI RADS, a\ncategoria 3 corresponde à lesão:","options":{"A":"maligna.","B":"benigna.","C":"Provavelmente benigna.","D":"Suspeita de malignidade.","E":"Não existe classificação BI RADS no ultrassom, apenas na mamografia."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-87477","number":"87477","sourceNumber":"87477","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Mulher de 52 anos, assintomática, foi submetida à mamografia de rastreamento.\nProcura seu Médico de Família e Comunidade\nlevando o referido exame, com resultado BI-RADS\ncategoria 2. A recomendação de conduta é:","options":{"A":"Exame clínico das mamas anual e nova mamografia em 6 meses.","B":"Ultrassonografia complementar.","C":"Biópsia percutânea.","D":"Exame clínico das mamas anual e nova mamografia em 2 anos.","E":"Ressonância magnética."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-60940","number":"60940","sourceNumber":"60940","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma mulher de 30 anos vai ao consultório médico relatando que a avó de 68 anos\nmorreu devido a câncer de ovário. Temendo\nadquirir a doença, ela solicita informações sobre os\nfatores de risco e prevenção para o carcinoma de ovário. Assinale a alternativa que apresenta um\nfator que pode diminuir o risco para esse câncer.","options":{"A":"Nuliparidade.","B":"Menopausa após 55 anos de idade.","C":"Medicamentos indutores de ovulação.","D":"Uso de anti-inflamatórios não esteroides.","E":"Uso de anticoncepcionais hormonais orais."},"answer":"E","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-46714","number":"46714","sourceNumber":"46714","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Com relação ao câncer de mama podemos afirmar:","options":{"A":"o carcinoma coloide representa aproximadamente 20% de todos os cânceres de mama.","B":"o carcinoma tubular, bem diferenciado apresenta-se com pior prognóstico em relação aos\ndemais por produzir frequentemente metástases para linfonodos axilares.","C":"A diferença entre a mastectomia radical modificada é que nesta não se preserva o músculo\npeitoral maior, como se faz na primeira técnica.","D":"O carcinoma ductal invasivo verdadeiro representa mais da metade de todos os tumores\ninvasivos da mama.","E":"Nenhuma das alternativas anteriores."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-46657","number":"46657","sourceNumber":"46657","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Na mama, o papiloma intraductal solitário é uma lesão de ductos proximais, que\nclinicamente tem como sintoma mais comum:","options":{"A":"Ulceração no mamilo","B":"Dor, com irradiação axilar","C":"Pele em \"casca de laranja\"","D":"Edema como ulceração periareolar","E":"Derrame papilar seroso ou sanguíneo"},"answer":"E","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-34155","number":"34155","sourceNumber":"34155","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Qual o tumor ovariano que mais frequentemente está associado à ruptura, dor pélvica\naguda, hemoperitôneo e sinais de hipovolemia?","options":{"A":"Cisto de Gardner.","B":"Cisto do Corpo Lúteo.","C":"Cisto endometrioide.","D":"Cisto dermoide.","E":"Teratoma cístico."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-26501","number":"26501","sourceNumber":"26501","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente 54 anos fez mamografia que evidenciou uma imagem nodular. Assinale das\nrespostas abaixo qual a conduta mais adequada:","options":{"A":"Exérese da lesão","B":"Solicitar marcadores tumorais como BRCA 1","C":"Conduta expectante","D":"Solicitar ultrassonografia","E":"Solicitar ressonância magnética da mama"},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-26510","number":"26510","sourceNumber":"26510","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Ca de ovário Unilateral com lavado peritoneal positivo para células malignas é\nconsiderado:","options":{"A":"Estadio Ic","B":"Estádio IIa","C":"Estádio IIb","D":"Estádio IIIa","E":"Estádio IIIb"},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-13247","number":"13247","sourceNumber":"13247","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"No acervo de peças do Departamento de Patologia da UFAM, a peça da coleção de\novários de número 09.29 é um tumor ovariano que apresenta as seguintes características: tumor\ngloboso, cístico, contendo em seu inferior pelos, sebo e fragmento que simula dente. Algumas\nvezes podemos encontrar ainda nestes tumores esboços organoides. Podemos dizer que se trata\nde:","options":{"A":"cistadenoma seroso.","B":"carcinoma embrionário.","C":"teratoma maduro ou cisto dermoide.","D":"cistadenoma mucinoso.","E":"disgerminoma."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-7455","number":"7455","sourceNumber":"7455","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Mulher 38 anos, apresentando nos últimos seis meses lesão eczematoide no mamilo de\nmama esquerda que se estende à aréola. Fez\ntratamento dermatológico sem resultado - a lesão\ncontinua com pele avermelhada, espessada e crostas úmidas descamativas. A biópsia é\nmandatória na possibilidade de tratar-se de:","options":{"A":"Comedocarcinoma.","B":"Doença de Paget da mama.","C":"Carcinoma medular.","D":"Carcinoma papilífero infiltrativo.","E":"Mastite pós-traumática."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-49456","number":"49456","sourceNumber":"49456","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Em relação ao câncer de mama, é correto afirmar:","options":{"A":"Tem-se observado um aumento na incidência em alguns países desenvolvidos, como Canadá e\nEUA, acompanhado pela diminuição da mortalidade.","B":"No Brasil, o aumento da incidência tem sido acompanhado por redução da mortalidade por esse\ntumor.","C":"A quimioprofilaxia deve ser recomendada a todas as mulheres assintomáticas.","D":"Existem evidências conclusivas que justificam a recomendação das estratégias de prevenção\ntradicionalmente realizadas nos programas de saúde de massa.","E":"Ainda não foram descritos fatores ambientais ou comportamentais associados a um risco\naumentado de desenvolver câncer de mama."},"answer":"E","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-49405","number":"49405","sourceNumber":"49405","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Mulher, 37 anos de idade, assintomática, apresenta história familiar positiva para\ncâncer de mama - mãe e irmã. O exame de imagem\nmais indicado para triagem do câncer de\nmama é","options":{"A":"ressonância magnética.","B":"mamografia.","C":"ultrassonografia mamária.","D":"tomografia computadorizada.","E":"radiografia de tórax."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-49277","number":"49277","sourceNumber":"49277","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente, 32 anos de idade, em uso de método contraceptivo de barreira, encontra-se\nno 24º dia do ciclo menstrual. Realizou\nultrassonografia transvaginal, que evidenciou ovário direito\ncontendo formação anecoica com debris, contornos irregulares, medindo 20 x 30 mm. A conduta\npara essa paciente é:","options":{"A":"fazer controle ecográfico em fase proliferativa do ciclo menstrual.","B":"realizar cirurgia imediata.","C":"introduzir contracepção hormonal.","D":"realizar ressonância magnética de pelve.","E":"fazer dosagem de marcadores tumorais."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-35008","number":"35008","sourceNumber":"35008","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Sobre o câncer de colo uterino, é incorreto afirmar:","options":{"A":"Corresponde à maior causa de óbito por neoplasia ginecológica no mundo.","B":"Ao contrário do carcinoma espinocelular, o adenocarcinoma de colo uterino não está relacionado\nà infecção pelo HPV.","C":"O carcinoma epidermoide é o tipo mais incidente.","D":"As cepas de HPV de maior risco são 16, 18, 31, 33 e 51.","E":"A incidência em países em desenvolvimento supera a dos países desenvolvidos."},"answer":"E","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-34981","number":"34981","sourceNumber":"34981","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Mulher, 60 anos de idade, apresenta nódulo mamário palpável, endurecido, associado\nà área de retração à inspeção dinâmica. O\nexame complementar inicial mais indicado é:","options":{"A":"ultrassonografia mamária.","B":"mamografia.","C":"ressonância magnética da mama.","D":"punção aspirativa por agulha fina (PAAF).","E":"rastreamento dos genes BRCA 1 e 2."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-34925","number":"34925","sourceNumber":"34925","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente, 25 anos de idade, em uso de condom, assintomática, vai ao consultório de\nginecologia com achado ecográfico evidenciando formação anecoica, anexial, sem septações,\nmedindo 19 mm x 21 mm. Exame físico sem alterações. A melhor conduta, nesse quadro, é:","options":{"A":"iniciar tratamento com contraceptivo oral, por 3 meses.","B":"realizar ooforectomia e biópsia da peça cirúrgica.","C":"tranquilizá-Ia por se tratar de folículo pré-ovulatório.","D":"realizar ultrassom com Doppler e dosagem de marcadores tumorais.","E":"realizar punção guiada por ultrassom transvaginal."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-27448","number":"27448","sourceNumber":"27448","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente, sexo feminino, realizou mamografia de rotina anual, que mostrou\nmicrocalcificação suspeita em quadrante superior\nesquerdo da mama direita. Submetida à exérese\nda área afetada, o exame anatomopatológico e imuno-histoquímico revelaram carcinoma ductal in\nsitu (CDIS) grau I, medindo 1,3 centímetros e margens cirúrgicas livres à congelação e na parafina,\nreceptores hormonais positivos. A conduta mais adequada para o caso em questão é indicar:","options":{"A":"mastectomia radical modificada à Madden à direita.","B":"mastectomia radical modificada à Pattey à direita.","C":"lumpectomia e Iinfadenectomia axilar direita","D":"lumpectomia e pesquisa do linfono sentinela.","E":"radioterapia e administração de tamoxifeno oral."},"answer":"E","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-27464","number":"27464","sourceNumber":"27464","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente, 50 anos de idade, nunca foi ao ginecologista. Na primeira consulta,\ncomparece sem queixas. Relatou mãe e irmã\nfalecidas por câncer de mama. Foi realizado exame\nfísico completo, sem constatação de qualquer alteração clínica. Levando em consideração esse\ncaso, o exame inicial indicado para rastreamento de câncer de mama nessa paciente, com histórico\nfamiliar de câncer de mama em parente de 1º grau, é:","options":{"A":"ultrassonografia mamária.","B":"mamografia.","C":"PAAF.","D":"core-biopsy.","E":"tomografia."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-11160","number":"11160","sourceNumber":"11160","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente, 40 anos de idade, apresentou secreção sero-hemática à expressão mamária,\nuniductal, unilateral. O exame palpatório das mamas foi normal. Não faz uso de fármacos. A\nmamografia e a ultrassonografia das mamas também não revela anormalidades. A conduta inicial é:","options":{"A":"realizar ressonância magnética das mamas.","B":"indicar ductografia.","C":"fazer reavaliação em seis meses.","D":"realizar setorectomia com retirada do ducto envolvido.","E":"realizar punção aspirativa."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-11146","number":"11146","sourceNumber":"11146","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"A punção de macrocisto, recidivado em paciente de 42 anos de idade, aspirou 18 ml de\nlíquido hemorrágico. A conduta adequada para o caso apresentado é:","options":{"A":"reavaliar pela mamografia e/ou ultrassonografia semestrais.","B":"medicar com tamoxífeno 10 mg/dia.","C":"ressecar a lesão para estudo histopatológico.","D":"controlar anualmente, se a citologia for negativa.","E":"repetir a punção com três meses."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-11150","number":"11150","sourceNumber":"11150","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente, 18 anos de idade, nuligesta, submetida à laparotomia para a retirada de\ntumor anexial com cápsula íntegra. O exame histopatológico de congelação revelou teratoma\nimaturo. A conduta, para esse caso, é realizar:","options":{"A":"anexectomia unilateral, coleta de lavado peritoneal, omentectomia infracólica e amostragem\nlinfonodal homolateral.","B":"pan-histerectomia, coleta de lavado peritoneal, omentectomia infracólica e amostragem\nlinfonodal.","C":"anexectomia bilateral, coleta de lavado peritoneal, omentectomia infracólica e amostragem\nlinfonodal.","D":"cirurgia de Wertheim-Meigs e radioterapia.","E":"anexectomia bilateral e quimioterapia."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-281891","number":"281891","sourceNumber":"281891","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente comparece ao ginecologista com resultado de mamografia que evidenciou\nnódulo sólido de 4 cm, espiculado, em quadrante supero-externo de mama esquerda. A\nclassificação BI-RADS, nesse caso, é:","options":{"A":"0","B":"3","C":"4","D":"5"},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-249718","number":"249718","sourceNumber":"249718","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Em se tratando de mastites, é correto afirmar que","options":{"A":"a mastite puerperal acomete a mulher no período da amamentação, normalmente, mulheres\nmultíparas e com mamilos protrusos.","B":"as mastites crônicas se caracterizam por duração acima de 30 dias ou recorrentes e acometem\npredominantemente, mulheres na pós-menopausa.","C":"a mastite causada por sífilis costuma acometer o complexo aréolo mamilar devido à inoculação\ndo treponema e o tratamento é feito com penicilina\nbenzatina.","D":"o abscesso subareolar recidivante crônico consiste em infecção recorrente subareolar,\nassociado a tabagismo, diabetes e obesidade,\nacometendo mais comumente as duas mamas.","E":"as mastites ocasionadas por micobactérias estão associadas, normalmente, a pacientes\nimunocompetentes e o diagnóstico definitivo é feito após biópsia da lesão com presença do\ngranuloma caseoso."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-249725","number":"249725","sourceNumber":"249725","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"São lesões que elevam o risco para câncer de mama:","options":{"A":"Adenose apócrina e cicatriz radiada.","B":"Cisto mamário e hiperplasia ductal atípica.","C":"Papiloma intraductal e adenose esclerosante.","D":"Adenoma lactante e lesão esclerosante complexa.","E":"Hiperplasia estromal pseudoangiomatosa e hamartoma."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-250004","number":"250004","sourceNumber":"250004","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Situação que não tem relação com o uso do tamoxifeno:","options":{"A":"hiperplasia endometrial.","B":"pólipo endometrial.","C":"miomatose uterina.","D":"câncer de endométrio."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-218169","number":"218169","sourceNumber":"218169","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Maria aparecida, negra, 36 anos, bem-humorada, compareceu à Unidade Básica de\nSaúde onde tem como equipe: a agente de\nsaúde Filomena, a técnica de enfermagem Carla, o\nenfermeiro Mário e a médica Daiane. Maria Aparecida tem uma história de realização de\nCitopatológico (CP) de colo de útero com uma certa regularidade. Seu último exame foi há 3 anos,\nquando era casada com Paulo, uma relação que durou 7 anos. O resultado fora normal. Na mesma\nocasião, em uma campanha de educação em saúde promovida pelo Ministério da Saúde e\nSecretarias do Estado e do Município, Maria fez a mamografia também com resultados normais.\n\nMaria Aparecida teve menarca ao 13 anos, sexarca aos 16 anos. Teve uma filha, Lelê, e um filho,\nCarlinhos, com Paulo. Duas gestações com dois partos vaginais. Maria Aparecida menstrua\nregularmente. Sem casos conhecidos de câncer de mama na família. Divorciou-se de Paulo há 2\nanos: me libertei doutora - sempre dizia à Daiane. Recentemente, conheceu um homem de 30\nanos, Valdomiro, com quem está namorando e já está pensando em se \"juntar\". Maria é hipertensa\nem uso de enalapril 10 mg de 12/12 horas. Na consulta, observou-se PA 140/90 mmHg, pesa 78\nkg, mede 1,60 m de altura (IMC 30,5). Considerando o caso clínico acima e as diretrizes nacionais\ndo Ministério da Saúde sobre o rastreamento de câncer de mama, a(s) orientação(ções) mais\nadequada(s) para Maria Aparecida é(são):","options":{"A":"A usuária não está dentro da faixa etária e de qualquer outro critério que se recomende o\nrastreamento do câncer de mama, portanto, se assintomática e ECM normal, não deve ser\nsolicitada nem ecografia e nem mamografia.","B":"Se assintomática e ECM normal, orientar o autoexame das mamas, pois as evidências têm\nmostrado que este é o melhor método de rastreamento para a prevenção do câncer de mama.","C":"Se assintomática e ECM normal, solicitar ecografia mamária por maior probabilidade de mamas\ndensas pela faixa etária da usuária.","D":"Solicitar nova mamografia, uma vez que já se passaram mais de dois anos desde a última, e\npassar a solicitar a cada dois anos.","E":"Se assintomática e exame clínico de mamas (ECM) normal, solicitar mamografia e ecografia\n\nmamária."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-215579","number":"215579","sourceNumber":"215579","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Assinale a alternativa INCORRETA com relação aos nódulos pulmonares solitários\n(NPS):","options":{"A":"São definidos radiologicamente como lesões intrapulmonares menores do que 3 cm no maior\ndiâmetro, não associadas a outras anormalidades.","B":"Embora lesões benignas contribuam para um grande número de NPS, somente a tomografia\npode diagnosticar definitivamente essas lesões.","C":"Em geral, apresentam-se como achado incidental de exames rotineiros e raramente dão algum\ntipo de sintoma.","D":"Entre os diagnósticos diferenciais, podem ser incluídas lesões neoplásicas, infecciosas,\ninflamatórias, vasculares e traumáticas."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-215605","number":"215605","sourceNumber":"215605","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Os hamartomas pulmonares são os tumores benignos mais comuns do pulmão.\nAssinale a alternativa INCORRETA.","options":{"A":"Representam aproximadamente 75% dos tumores pulmonares benignos.","B":"Podem ocorrer em qualquer faixa etária, embora sejam mais frequentes da terceira a sexta\ndécadas de vida, acometendo duas a três vezes mais homens que mulheres.","C":"A maioria dos hamartomas é assintomática.","D":"Apresentam rápido crescimento e podem ocorrer em qualquer lobo pulmonar."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-215577","number":"215577","sourceNumber":"215577","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma mamografia evidenciando mamas com boa lipossubstituição, com linfonodos\naxilares identificáveis bilateralmente, recebe a classificação de:","options":{"A":"BI-RADS 0.","B":"BI-RADS 1.","C":"BI-RADS 2.","D":"BI-RADS 3."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-215573","number":"215573","sourceNumber":"215573","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"A presença de mamilo acessório sem glândula mamária adjacente caracteriza:","options":{"A":"Polimastia.","B":"Politelia.","C":"Amastia.","D":"Amazia."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-215587","number":"215587","sourceNumber":"215587","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"O principal marcador sérico para tumores epiteliais ovarianos é:","options":{"A":"CEA.","B":"CA 125.","C":"CA 24-4.","D":"Bhcg."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-215607","number":"215607","sourceNumber":"215607","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"A associação da ultrassonografia à mamografia no rastreamento de doenças mamárias\napresenta os seguintes benefícios, EXCETO:","options":{"A":"Em mulheres com mamas densas a adição do ultrassom aumenta o número de diagnósticos em\nmulheres com alto risco para câncer.","B":"Apresenta a desvantagem de aumentar também o número de falsos-positivos.","C":"O ultrassom mamário também pode ser útil na determinação da extensão local do câncer de\nmama, auxiliando no planejamento pré-operatório.","D":"O ultrassom Doppler pode avaliar o padrão hipo ou avascular nos casos de tumores malignos."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-157663","number":"157663","sourceNumber":"157663","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Ao receber um laudo de mamografia BI-RADS 2, é necessário dizer para a paciente\nque:","options":{"A":"Ela pode ficar tranquila, pois o risco de câncer é praticamente zero.","B":"Vai ser solicitado um exame complementar para confirmar o diagnóstico.","C":"Ela vai necessitar de uma biópsia dirigida com agulha fina.","D":"Ela vai ter que repetir esse exame em 4 a 6 meses."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-134751","number":"134751","sourceNumber":"134751","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Qual artéria deve ser preservada na reconstrução mamária, utilizando retalho do\nmúsculo reto abdominal?","options":{"A":"Torácica lateral.","B":"Tóraco-dorsal.","C":"Epigástrica superior profunda.","D":"Circunflexa superior profunda."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-134718","number":"134718","sourceNumber":"134718","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente de 60 anos vem para consulta com exame de mamografia em mãos. O\nMédico observa microcalcificações pleomórficas e agrupadas (10 por cm quadrado) no exame.\nQual é a MELHOR conduta para esse caso?","options":{"A":"Biópsia guiada por agulhamento.","B":"Ultrassonografia.","C":"Repetir mamografia em 1 ano.","D":"Tomografia computadorizada."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-134752","number":"134752","sourceNumber":"134752","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente de 55 anos vem para consulta de rotina e para avaliação e exames. Na\nconsulta, deveremos estar atentos para qual sinal físico, que seria o MAIS comum de câncer\nmamário?","options":{"A":"Nódulo indolor.","B":"Dor mamária.","C":"Descarga mamilar amarelada.","D":"Ulceração de mamilo."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-134766","number":"134766","sourceNumber":"134766","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Ao avaliarmos uma paciente com alterações fibrocísticas benignas das mamas,\npodemos correlacionar com as afirmações abaixo, EXCETO uma delas. Aponte-a.","options":{"A":"Pode produzir dor cíclica.","B":"Os espessamentos glandulares geralmente são bilaterais.","C":"Os quadrantes superiores externos são os mais acometidos.","D":"Aumenta o risco de câncer de mama."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-111917","number":"111917","sourceNumber":"111917","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"O adenocarcinoma do endométrio pode ser descrito por todas as seguintes afirmativas,\nEXCETO uma. Indique-a:","options":{"A":"É, principalmente, uma doença de mulheres na pós-menopausa.","B":"A média de idade das mulheres afetadas é superior à média de idade das mulheres portadoras\nde carcinoma cervical.","C":"Possui um prognóstico mais favorável que o do câncer cervical, com uma taxa de sobrevida em\ncinco anos próxima de 75%.","D":"Sua incidência está relacionada ao número de parceiros sexuais."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-111932","number":"111932","sourceNumber":"111932","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente de 46 anos, antecedente familiar de câncer de mama na família (avó materna\naos 52 anos) comparece à UBS para fazer\nexames de rotina, nega queixas, nega uso de\nmedicações e ACO. Qual exame tem que fazer parte da rotina anual?","options":{"A":"Citologia de secreção mamilar.","B":"Ultrassonografia mamária.","C":"Pesquisa de marcadores tumorais (CA 125, alfafetoproteína).","D":"Mamografia."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-350828","number":"350828","sourceNumber":"350828","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Mulher, 42 anos, refere desconforto pélvico associado à fadiga. Realizou\nultrassonografia pélvica que observou nódulo\nmisto, com áreas hiperecogênicas difusas, sombra\nacústica posterior e presença de pontos hiperecogênicos dentro da massa. Qual diagnóstico mais\nprovável?","options":{"A":"Fibroma.","B":"Endometrioma.","C":"Cisto dermoide.","D":"Cisto hemorrágico."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-350901","number":"350901","sourceNumber":"350901","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente 19 anos, durante consulta ginecológica, queixa-se de percepção de nódulo em\nmama direita, que, ao exame físico, revela-se\nfirme, bem delimitado e móvel, com\naproximadamente 2 cm de tamanho. O diagnóstico mais provável da lesão acima é:","options":{"A":"Carcinoma invasor.","B":"Ectasia ductal.","C":"Tumor filoides.","D":"Fibroadenoma."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-292888","number":"292888","sourceNumber":"292888","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente, 35 anos, realizou biopsia mamária de nódulo compatível com hiperplasia\nductal atípica. Não sabe referir história\nfamiliar pois foi adotada na infância. Procura ginecologista\npara realizar exames para prevenção do câncer de mama. Assinale a assertiva correta quanto à\nclassificação de risco da paciente e adequada estratégia de rastreamento com as recomendações\ndo Colégio Brasileiro de Radiologia e da Federação Brasileira de Ginecologia e Obstetrícia\n(Febrasgo).","options":{"A":"Risco intermediário: realizar mamografia anual + Ultrassonografia (USG) pode ser solicitada de\nmaneira individualizada.","B":"Risco intermediário: realizar mamografia anual + Ultrassonografia e ressonância magnética\ncomplementares.","C":"Alto Risco: realizar mamografia anual + Ultrassonografia e ressonância magnética\ncomplementares.","D":"Alto Risco: Mamografia e ressonância magnética anuais a partir dos 30 anos."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-259773","number":"259773","sourceNumber":"259773","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Mulher de 25 anos, assintomática, apresenta-se ao ambulatório de ginecologia\npreocupada, pois realizou uma ultrassonografia\ntransvaginal que foi compatível com os seguintes\nachados: massa anexial ovariana direita de maior diâmetro de 4 cm, contornos regulares, com\nconteúdo heterogêneo com reforço acústico posterior, sem septações, ou áreas sólidas. À\ndopplervelocimetria, apresentava fluxo periférico de alta resistência. Qual a melhor conduta para\nela?","options":{"A":"Uso de anticoncepcional combinado oral para redução da massa devido ao aspecto funcional.","B":"Acompanhamento ultrassonográfico após seis meses devido ao aspecto benigno.","C":"Ooforectomia laparoscópica com congelação devido ao risco de malignidade.","D":"Ooforoplastia laparoscópica devido ao risco de torção ou ruptura."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-259775","number":"259775","sourceNumber":"259775","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Mulher de 30 anos, nuligesta, apresenta nódulo de mama direita, palpável, indolor e\nque persiste após 1 ciclo menstrual. Relata\nque uma tia teve câncer de mama aos 60 anos. O\nultrassom de mamas evidenciou nódulo sólido de 1,8 cm, BI-RADS-3. Qual seria a melhor conduta,\nde acordo com as diretrizes de conduta para diagnóstico e terapêutica?","options":{"A":"Em mulheres com nódulos palpáveis BI-RADS-3, deve ser indicada exérese da lesão,\nindependentemente dos sintomas.","B":"As lesões BI-RADS-3 podem ter seguimento semestral por até três anos, não sendo indicada a\nbiópsia para esta conduta.","C":"A exérese cirúrgica de lesões mamárias BI-RADS-3 deve ser priorizada aos casos\nassintomáticos e com história familiar, pois apresentam maior risco para câncer de mama.","D":"Até a terceira década de vida, a maioria dos nódulos sólidos da mama não necessita de\ninvestigação; no entanto, quando o nódulo é\npalpável, recomenda-se mamografia de rastreamento."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-234068","number":"234068","sourceNumber":"234068","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma mulher de 57 anos, assintomática, comparece para consulta na atenção primária.\nTrouxe consigo uma mamografia, a primeira que realizou na vida. Após avaliação, o médico decide\nsolicitar retorno e uma nova mamografia com intervalo de seis meses. A paciente não possui\nhistórico familiar e pessoal relevante. Segundo as diretrizes do Ministério da Saúde / Instituto\nNacional de Câncer, o que o médico deve ter evidenciado nos resultados dessa mamografia?","options":{"A":"BI-RADS 0","B":"BI-RADS 1","C":"BI-RADS 3","D":"BI-RADS 5"},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-199798","number":"199798","sourceNumber":"199798","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Mulher de 41 anos realizou mamografia e ultrassonografia mamária de rotina que\nevidenciaram imagem nodular sólida de 10 mm de diâmetro, orientação não paralela à pele,\nmargens anguladas e sombra posterior. Tem histórico de tia materna com câncer de mama e de\nintestino aos 65 anos. Qual a orientação para essa paciente, de acordo com o Ministério da Saúde?","options":{"A":"Realizar quadrantectomia para exérese da lesão apresentada, diante do tamanho e do aspecto\ndescritos.","B":"Fazer seguimento da lesão a cada 6 meses por um período de 2 ou 3 anos devido à imagem do\nnódulo apresentada.","C":"Solicitar ressonância magnética das mamas como parte do rastreamento devido ao elevado\nrisco de câncer de mama hereditário.","D":"Indicar biópsia de fragmento para esclarecimento diagnóstico devido às características BIRADS\n4 (suspeito de malignidade) do nódulo descrito."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-199650","number":"199650","sourceNumber":"199650","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Mulher, 38 anos, assintomática, nuligesta, com desejo reprodutivo, traz à consulta um\nexame ultrassonográfico com imagem de massa cística\ne sólida em anexo direito de 10 cm de\ndiâmetro, com aumento da vascularização no componente sólido de 5 cm e na septação de 2 cm.\nAs dosagens de marcadores são: Alfa-Fetoproteína (AFP) = 8?g/ml (VR = até 7,0 ?g/L); CA 125 =\n46,8 U/ml (VR = até 35 U/ml); CA 19.9 = 5,2 U/ml (VR = até 37 U/ml); antígeno carcinoembrionário\n(CEA) = 0,8 ?g/L (VR = até 3,0 ?g/L). Legenda: VR = Valor de Referência. Qual melhor conduta\ndiante desse caso?","options":{"A":"Ooforoplastia laparoscópica sem necessidade de congelação, devido à idade e ao baixo risco de\nmalignidade.","B":"Salpingooforectomia bilateral com histerectomia e linfadenectomia laparotômica com\nestadiamento\n\npara câncer de ovário.","C":"Salpingooforectomia unilateral laparoscópica com congelação, prosseguindo com\nlinfadenectomia,\n\nhisterectomia e anexectomia contralateral se malignidade.","D":"Repetição da ultrassonografia em 6 meses, pois as caraterísticas de malignidade são baixas de\nacordo\n\ncom os critérios de IOTA (International Ovarian Tumor Analysis)."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-173015","number":"173015","sourceNumber":"173015","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Mulher de 32 anos de idade, com história familiar fortemente positiva de câncer de\nmama (mãe e irmã em idade pré-menopausa).\nQual estratégia de prevenção secundária deve ser\nrecomendada?","options":{"A":"Orientar avaliação pré-operatória para cirurgia de mastectomia profilática/redutora de risco.","B":"Orientar uso oral de Tamoxifeno (modulador seletivo de receptores de estrogênio) por 5 anos.","C":"Orientar acompanhamento assíduo (exame clínico e exames de imagem) início 10 anos antes\nda menor idade de diagnóstico de câncer de\nmama na família.","D":"Orientar exame clínico a cada seis meses e ultrassonografia mamária e, após os 40 anos,\nindicar mamografia e Ressonância Magnética das Mamas."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-150888","number":"150888","sourceNumber":"150888","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Mulher de 32 anos, G0 P0 A0, IMC de 30 Kg/m2 e mãe com diagnóstico de câncer de\nmama aos 40 anos. Qual a melhor recomendação\na essa paciente quanto à prevenção secundária\ndo câncer de mama?","options":{"A":"O acompanhamento regular com exame clínico das mamas, alternando mamografia com\nressonância ou ultrassonografia, pode ser recomendado devido à história familiar.","B":"A mudança de estilo de vida e hábitos alimentares devem ser recomendados, pois a obesidade\nem mulheres pré-menopausadas é um fator de risco\npara câncer de mama.","C":"O uso do tamoxifeno como quimioprevenção está indicado por tratar-se de paciente de risco,\nestando associado à uma redução significativa na incidência do câncer de mama.","D":"A ultrassonografia mamária é o exame considerado padrão para o rastreamento e a mamografia\nindicada a partir dos 40 anos, pois mulheres abaixo dessa faixa etária apresentam mamas densas."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-126981","number":"126981","sourceNumber":"126981","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Mulher de 25 anos, nuligesta, totalmente assintomática, após consulta ginecológica\nrealizou Ultrassonografia (USG) pélvica transvaginal\nque evidenciou imagem ultrassonográfica em\novário direito de 4 cm de diâmetro; superfície lisa; contornos regulares; hipoecoico; sem septações;\nsem excrescências ou imagens sólidas. Qual a melhor conduta nesse caso?","options":{"A":"Laparoscopia, com aspiração do cisto.","B":"Laparoscopia, com ooforectomia unilateral.","C":"Expectante, com dosagem sérica de CA-125.","D":"Expectante, desnecessário qualquer tratamento adicional."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-102138","number":"102138","sourceNumber":"102138","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Mulher de 54 anos de idade vem ao consultório para uma consulta de rotina,\nassintomática. Exame físico: normal. Exames\ncomplementares: citologia oncótica e mamografia -\nnormais. O exame ultrassonográfico transvaginal, entretanto, mostrou a imagem. (VER IMAGEM) O\nDoppler mostrou índice de resistência: baixa. A conduta mais adequada para esse caso é:","options":{"A":"Indicar uma laparotomia exploradora e informá-la da possibilidade de pan-histerectomia.","B":"Informá-la que os aspectos do exame ultrassonográfico são de suspeita de neoplasia do ovário\nou tuba.","C":"Solicitar exames complementares outros mais esclarecedores, como CA-125, inibina e\nalfa-fetoproteína.","D":"Indicar laparoscopia exploradora tendo discutido com ela antes a possibilidade de\nsalpingo-ooforectomia unilateral."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":["question_bank/media/medcurso/medcurso-gineco-gin-4/102138.png"],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-102154","number":"102154","sourceNumber":"102154","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Mulher de 48 anos vem à Unidade Básica de Saúde para prevenção de câncer de\nmama. Última avaliação, há mais de dois anos. Descobriu recentemente que sua tia, irmã mais\nnova de sua mãe, teve um câncer de mama avançado com 38 anos. O exame físico foi normal,\nincluindo o exame das mamas. Qual (is) exame (s) o médico deve solicitar para seguir com a\ninvestigação, de acordo com o Ministério da Saúde do Brasil?","options":{"A":"Mamografia rotineira.","B":"Ultrassonografia, desde que o exame físico foi normal.","C":"Mamografia e ultrassonografia, aumentando a eficácia diagnóstica.","D":"Ressonância magnética e ultrassonografia, alto risco de câncer da paciente."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-4-81257","number":"81257","sourceNumber":"81257","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Mulher, 53 anos de idade, nulípara, amenorreia há 2 anos, procura assistência médica\npor sangramento uterino anormal. Durante o exame\nfísico, encontraram-se os seguintes achados\npositivos: Pressão arterial de 150 x 100 mmHg, peso de 82 kg e altura de 1,61 m, a vagina é\nrosada e úmida, sem outros comemorativos. Foi submetida à curetagem uterina fracionada, cuja\nimagem do achado histopatológico se encontra na figura abaixo (VER IMAGEM). Qual a opção\ncondizente com a melhor conduta terapêutica?","options":{"A":"Agentes progestacionais por via oral.","B":"Anticoncepcionais orais combinados.","C":"Histerectomia total por via abdominal.","D":"Ablação histeroscópica do endométrio."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":["question_bank/media/medcurso/medcurso-gineco-gin-4/81257.png"],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-81296","number":"81296","sourceNumber":"81296","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Mulher, 48 anos de idade, apresentando ciclos menstruais irregulares com intervalos de\n60 a 90 dias no último ano, refere que\napresentou sangramento transvaginal volumoso por mais\nde 15 dias, sendo submetida a uma curetagem uterina semiótica, cujo resultado histopatológico foi\ncompatível com hiperplasia endometrial adenomatosa sem atipias. Qual a melhor conduta a seguir,\ndentre as opções abaixo?","options":{"A":"Histerectomia abdominal total.","B":"Ablação histeroscópica do endométrio.","C":"Tratamento estroprogestacional combinado.","D":"Tratamento com progestogênios por via oral."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-81307","number":"81307","sourceNumber":"81307","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma mulher de 30 anos de idade procura assistência médica para orientação sobre\nprevenção de câncer de mama. Encontra-se\nansiosa e temerosa, pois sua mãe foi submetida\na uma quadrantectomia recentemente (com 47 anos de idade) por neoplasia lobular in situ. No\nmomento, não apresenta sintomas mamários, é nulípara e tem diagnóstico de ovários policísticos\ndesde vinte anos de idade, fazendo uso de contraceptivos hormonais combinados. Que orientação\ndeve ser dada a essa mulher, baseada no programa de prevenção de câncer do Ministério da\nSaúde do Brasil/INCA?","options":{"A":"Realizar a mamografia anualmente a partir dos 40 anos.","B":"Iniciar sua prevenção aos 35 anos, com exame clínico das mamas e mamografias anuais.","C":"Realizar a autopalpação das mamas regularmente, e procurar o médico sempre que houver\nachados.","D":"Realizar a mamografia a cada dois anos, entre a idade de 50 a 69 anos, e o exame clínico das\nmamas anualmente."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-65683","number":"65683","sourceNumber":"65683","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Mulher de 52 anos de idade, menopausada há dois anos, assintomática, com exame\nfísico normal, apresenta, em exame de rotina, o\nachado ultrassonográfico, reproduzido abaixo. Tem\nCA-125 de 60 U/ml. Qual a melhor conduta a seguir? (VER IMAGEM)","options":{"A":"Repetir os exames em 3 meses.","B":"Repetir os exames após uso de contraceptivo hormonal.","C":"Indicar laparotomia exploradora com biópsia de congelação.","D":"Indicar histerectomia total e anexectomia bilateral.","E":"Indicar ooforectomia unilateral."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":["question_bank/media/medcurso/medcurso-gineco-gin-4/65683.png"],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-51119","number":"51119","sourceNumber":"51119","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Mulher de 55 anos, que está na menopausa há cinco anos, apresenta, ao exame\nultrassonográfico transvaginal, um cisto simples\nde parede fina, menor que 5 cm na topografia do\novário esquerdo. Não aumentou desde o último exame, há seis meses. Foi solicitada a dosagem de\nCA-125, que foi normal. Qual a conduta recomendada?","options":{"A":"Expectante.","B":"Laparatomia exploradora.","C":"Administração de anticoncepcional oral combinado.","D":"Administração de análogo ao GnRH."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-51301","number":"51301","sourceNumber":"51301","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Mulher de 27 anos vem ao consultório com quadro de dor pélvica desde a última\nmenstruação, há quase 1 mês, de intensidade\nleve à moderada, intermitente, sendo mais evidente\nem fossa ilíaca esquerda. Não tem vida sexual ativa há 4 meses. Realizou ultrassonografia ontem,\ncom evidência de cisto simples em ovário esquerdo medindo 4 x 2 x 2 cm. Qual a conduta mais\nacertada?","options":{"A":"Solicitar uma tomografia computadorizada, CA-125 sérico e exames pré-operatórios.","B":"Indicar laparotomia exploradora imediatamente pelo risco de complicação por torção.","C":"Prescrever analgésicos ou anti-inflamatórios e solicitar a repetição do ultrassom pós-menstrual.","D":"Prescrever anticoncepcional oral combinado enquanto se aguarda a videolaparoscopia\ndiagnóstica."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-45359","number":"45359","sourceNumber":"45359","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Qual é a causa mais comum de descarga papilar em mulheres não lactantes?","options":{"A":"Carcinoma.","B":"Fibroadenoma.","C":"Tumor filoide.","D":"Ectasia ductal.","E":"Papiloma intraductal."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-37614","number":"37614","sourceNumber":"37614","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Vanda, 34 anos, G8P7A1, procurou Dr. Diogo com queixa de nódulo em mama direita.\nAo examiná-la, Dr. Diogo palpou um nódulo indolor,\nbem circunscrito, móvel e de consistência\nelástica. Solicitou ultrassom de mamas que teve como resultado lesão sólida de 20 mm diâmetro\ncom características de benignidade. Qual a hipótese diagnóstica mais provável?","options":{"A":"Papiloma intraductal único.","B":"Lipoma.","C":"Fibroadenoma.","D":"Alteração funcional benigna da mama."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-30854","number":"30854","sourceNumber":"30854","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Mulher 48 anos queixa-se de derrame papilar sanguinolento por um ducto na mama\nesquerda há um mês. Exame físico: sem retrações ou nódulos. Citologia: grande celularidade;\npresença de agrupamentos de células ductais com núcleos hipercromáticos; algumas células\nexibem binucleação. Mamografia: calcificações arredondadas grosseiras bilateralmente. O\ndiagnóstico mais provável é:","options":{"A":"Alteração fibrocística.","B":"Carcinoma intraductal.","C":"Doença de Paget.","D":"Papiloma intraductal.","E":"Ectasia ductal."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-32542","number":"32542","sourceNumber":"32542","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Na terminologia BI- RADS (American College of Radiology Breast Imaging, Reporting\nand Data System), a classificação zero quer\ndizer:","options":{"A":"lesão benigna.","B":"suspeita de malignidade.","C":"lesão provavelmente benigna.","D":"mamografia normal.","E":"necessita de avaliação adicional: inconclusivo."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-4-36993","number":"36993","sourceNumber":"36993","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma mulher de 51 anos de idade comparece ao consultório para consulta ginecológica.\nO exame físico das mamas foi normal. No\nretorno, a mamografia mostrou alteração com área\nespiculada do tipo fibroesclerótica (cicatriz radial) de 1,5 cm, classificada como categoria BI-RADS\nIV (suspeita de malignidade). Qual a conduta mais adequada?","options":{"A":"Punção aspirativa com agulha fina orientada\npor estereotaxia.","B":"Biópsia percutânea com agulha grossa\norientada por estereotaxia.","C":"Biópsia percutânea por mamotomia orientada\npor estereotaxia.","D":"Biópsia excisional precedida por\nagulhamento."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-4-29476","number":"29476","sourceNumber":"29476","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Dona Graça, 48 anos, negra, obesa, sedentária, procurou o médico de família referindo\nque chegou do interior há poucos meses, após a\nmorte do marido ? ?problema de coração\ncrescido? e ?doença do sexo?. Dona Graça casou-se duas vezes, sendo G10P9A1. O primeiro\nfilho nasceu quando tinha 14 anos. Desde o nascimento de seu filho mais jovem (hoje com 20\nanos), não consultou nenhum profissional de saúde. Tabagista (10 cigarros/dia), relatou\nirregularidade menstrual durante alguns meses e amenorreia há 6 meses. Queixou-se de episódios\nde ?calorão?. Baseando-se no caso acima e em seus conhecimentos sobre a saúde da mulher,\nresponda a questão. O médico de família e comunidade durante a consulta com Dona Graça,\nadotou algumas atitudes. Assinale alternativa INCORRETA:","options":{"A":"O médico de família orientou Dona Graça quanto aos riscos do tabagismo e à necessidade de\ninterrupção do tabaco. Uma intervenção breve como essa é o mínimo que se pode esperar de\nqualquer profissional da saúde, pois esse alerta ao fumante produz taxas de cessação de 5 a 10%\npor ano.","B":"O médico de família agendou o exame de prevenção de câncer de colo uterino de Dona Graça,\npois, considerando o rastreamento populacional, de\nacordo com normas do Ministério da Saúde,\ndeve ser colhida anualmente, em mulheres de 25 a 60 anos, e de três em três anos, após dois\nexames consecutivos anuais negativos","C":"Multiparidade e parceiro de alto risco são fatores de risco para neoplasia intraepitelial e\ncarcinoma epidermoide de colo uterino.","D":"A multiparidade e a cor negra são fatores de proteção para o câncer de corpo uterino em Dona\nGraça."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-22934","number":"22934","sourceNumber":"22934","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Principal causa de massa pélvica na adolescência.","options":{"A":"anovulação","B":"gravidez","C":"cisto funcional","D":"tumor de células germinativas","E":"tumor ovariano epitelial"},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-24342","number":"24342","sourceNumber":"24342","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"O folículo maduro contém o óvulo envolvido por células da camada granulosa, onde se\npodem encontrar formações vacuolares\ndenominadas:","options":{"A":"Folículos de Graaf;","B":"Ilhotas de Walthard;","C":"Cordões de Pflüger;","D":"Corpúsculos de Call-Exner."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-24349","number":"24349","sourceNumber":"24349","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"No arsenal terapêutico da dor mamária, as drogas a seguir não são mais utilizadas,\nEXCETO:","options":{"A":"Progesterona;","B":"Bromocriptina;","C":"Tamoxifeno;","D":"Vitamina E."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-27728","number":"27728","sourceNumber":"27728","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente de 24 anos apresenta-se com dor pélvica aguda, intermitente, de severa\nintensidade em FIE, de início há 3 dias. Refere ainda náuseas, vômitos e piora da dor com\natividade física e mudança de posição. Ao exame: T 37°C, Leucócitos 12.000/mm³, volumosa\nmassa pélvica em FIE e Blumberg ausente. Qual o diagnóstico mais provável?","options":{"A":"Doença inflamatória pélvica.","B":"Torção de cisto de ovário.","C":"Apendicite.","D":"Endometriose.","E":"Adenomiose."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-6905","number":"6905","sourceNumber":"6905","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"A queixa mamária mais comum em ambulatório de Mastologia é:","options":{"A":"Nódulo mamário.","B":"Achado em exame de imagem mamográfica.","C":"Descarga papilar.","D":"Ferida na mama.","E":"Nódulo axilar."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-7260","number":"7260","sourceNumber":"7260","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"No câncer de mama, o linfonodo sentinela é o primeiro linfonodo na axila ipsilateral ou\nmamária interna a receber a drenagem do tumor. Em qual das situações abaixo a técnica de\npesquisa deste linfonodo é indicada?","options":{"A":"Doença localmente avançada.","B":"Operação axilar prévia.","C":"Mulheres grávidas ou em amamentação.","D":"Linfonodos clinicamente negativos em axila.","E":"Doença metastática."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-13467","number":"13467","sourceNumber":"13467","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente 18 anos, assintomática, com cisto anexial simples unilateral,\n\nidentificado por ultrassonografia no 24º dia do ciclo, medindo 3 cm de diâmetro. Qual a melhor cond\nuta a ser indicada?","options":{"A":"Laparoscopia.","B":"Dosagem de CA-125.","C":"Punção guiada por ultrassonografia.","D":"Expectante.","E":"Contraceptivo hormonal contínuo."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-9154","number":"9154","sourceNumber":"9154","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Denomina-se doença de Mondor:","options":{"A":"Tromboflebite das veias da mama, que se apresenta como sulco raso na superfície do órgão, em\ndireção à axila.","B":"Processo inflamatório das mamas, que surge na fase de aleitamento, por conta de infecção, cuja\nporta de entrada seria uma pequena solução de continuidade do tegumento da aréola e papila.","C":"Quadro doloroso das mamas, de caráter permanente ou transitório, que ocorre no pré-mênstruo.","D":"Lesão eczematosa na aréola e papila mamária, quase sempre unilateral, sem outras\nmanifestações semelhantes a distância."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-17877","number":"17877","sourceNumber":"17877","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Na terminologia BI-RADS (American College of Radiology Breast Imaging Reporting\nand Data System), a designação 0 (zero) quer\ndizer:","options":{"A":"mamografia normal","B":"lesão benigna","C":"suspeita de malignidade","D":"lesão provavelmente benigna","E":"necessita de avaliação adicional"},"answer":"E","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-349689","number":"349689","sourceNumber":"349689","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Mulher de 64 anos leva para seu médico o resultado de exames de rotina, incluindo a\nmamografia. No laudo, veio descrito área de assimetria focal localizada no quadrante superior\nmedial da mama direita classificada como BI-RADS 0. Diante desse caso, qual é a melhor conduta?","options":{"A":"Indicar Core-biopsy.","B":"Solicitar ultrassonografia mamária.","C":"Punção por agulha fina.","D":"Solicitar ressonância magnética das mamas.","E":"Repetir mamografia em 3 meses."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-349678","number":"349678","sourceNumber":"349678","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Diversos fatores de risco genéticos, ambientais e reprodutivos foram associados ao\ndesenvolvimento do câncer de ovário, sendo que cerca de 5 a 10% das pacientes apresentam\npredisposição genética. Nas outras 90 a 95% sem qualquer conexão genética identificável para o\ndesenvolvimento do câncer, a maioria dos fatores de risco está relacionada com o padrão de ciclos\novulatórios durante os anos reprodutivos. Sobre esse tema, assinale a alternativa INCORRETA.","options":{"A":"Os carcinomas epiteliais ovarianos representam entre 90 e 95% dos casos, incluindo os tumores\nmais indolentes com baixo potencial de\nmalignidade.","B":"O uso em longo prazo de contraceptivos orais combinados reduz o risco de câncer de ovário. A\nduração de tal proteção chega a 25 anos após a última dose.","C":"As pacientes sem filhos apresentam risco dobrado de câncer de ovário. Entre as nulíparas,\naquelas com história de infertilidade apresentam risco mais baixo de desenvolver o câncer.","D":"Em geral, o risco é reduzido a cada nascido vivo, atingindo um platô nas mulheres que tenham\ndado à luz cinco vezes.","E":"A incidência geral de câncer de ovário aumenta com a idade, até em torno dos 75 anos, antes\nde declinar levemente entre mulheres com mais\nde 80 anos."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-322188","number":"322188","sourceNumber":"322188","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Dentre as alternativas a seguir, qual delas apresenta os achados que seriam mais\nsugestivos de câncer de mama?","options":{"A":"Cisto único no quadrante inferior interno da mama esquerda.","B":"Cistos múltiplos em ambas as mamas.","C":"Nódulos difusos, simétricos em ambas as mamas.","D":"Consolidação na mama direita que aparece logo antes da menstruação.","E":"Nódulo sólido único no quadrante superior externo da mama esquerda."},"answer":"E","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-322191","number":"322191","sourceNumber":"322191","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"A presença de células \"em anel de sinete\", no exame de anatomopatológico, é um\nachado de qual dos seguintes tumores\novarianos?","options":{"A":"Tumor de Brenner.","B":"Tumor de Krukenberg.","C":"Teratoma imaturo do ovário.","D":"Tumor seroso.","E":"Disgerminoma."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-274413","number":"274413","sourceNumber":"274413","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"A mastalgia é uma queixa muito comum nos consultórios médicos devido ao medo de\ncâncer. O ginecologista deve saber lidar com as patologias benignas da mama devido a sua\nfrequência e impacto na vida da mulher. Considerando esses casos, assinale a alternativa\nINCORRETA.","options":{"A":"Bursite, dor muscular e refluxo podem ser causas de dor extramamária.","B":"Clomifeno e alguns antidepressivos, como a sertralina, podem causar mastalgia.","C":"Faz parte do tratamento não farmacológico: uso de sutiã esportivo e exercício físico.","D":"Nos casos refratários, pode ser realizado bloqueio hormonal.","E":"Vitamina E, comprovadamente, pode tratar a patologia."},"answer":"E","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-274415","number":"274415","sourceNumber":"274415","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"As ações de vigilância do câncer constituem um componente estratégico para o\nplanejamento eficiente e efetivo dos programas de prevenção e controle de câncer. No Brasil, o\ncâncer com maior incidência em mulheres (conforme localização primária do tumor) é o de","options":{"A":"ovário.","B":"mama.","C":"corpo do útero.","D":"cólon e reto.","E":"colo do útero."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-284348","number":"284348","sourceNumber":"284348","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"As neoplasias ovarianas dos tipos endometrioide e de células claras têm sido\nrelacionadas à endometriose pélvica,\ndemonstrando uma associação entre endometriose e câncer.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-261282","number":"261282","sourceNumber":"261282","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma paciente de 56 anos de idade comparece à consulta com o ginecologista para\nrevisão. Refere realizar exames ginecológicos\nde rastreamento, conforme orientação do médico\nclínico geral que a atendia até então. Informa que faz uso de cálcio, vitamina D e sinvastatina, por\nhistórico de osteoporose identificada em densitometria óssea (DMO) prévia, e dislipidemia.\n\nRecentemente recebeu diagnóstico de nefrolitíase após crise de dor renal. Relata ser tabagista e\netilista desde os 23 anos de idade, e o peso atual dela é 54 Kg. Teve dois partos vaginais prévios,\nmenarca aos 12 anos e menopausa aos 38 anos de idade. Nega ter realizado terapia de reposição\nhormonal. Considerando esse caso clínico e com base nas recomendações do Ministério da Saúde\npara exames de rastreamento e nos conhecimentos médicos correlatos, julgue o item a seguir. A\npaciente deve realizar a mamografia anualmente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-284351","number":"284351","sourceNumber":"284351","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Atualmente, o BI-RADS atribui sete categorias para os resultados e a interpretação da\nmamografia. Os achados classificados como BI-RADS 3 em uma mamografia possuem uma\nprobabilidade maior ou igual a 98% de se tratarem de patologias benignas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-265556","number":"265556","sourceNumber":"265556","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma paciente de 36 anos de idade procurou auxílio médico com lesão complexa em\novário esquerdo e ascite moderada à\nultrassonografia, além de elevação da dosagem sérica do\nmarcador CA-125. Foi levada a uma laparoscopia diagnóstica, sendo evidenciada a presença de\ncarcinomatose peritoneal, ?omental cake?, volumosa lesão sólido-cística ovariana à esquerda,\npouco móvel e aderida ao retossigmoide e ovário contralateral de aspecto normal. Essa paciente foi\nsubmetida a uma ooforectomia esquerda e a uma biópsia de algumas das lesões peritoneais,\nsendo o achado consistente com um carcinoma seroso de ovário moderadamente diferenciado. Foi\nsubmetida a estadiamento radiológico, que não demonstrava focos de metástases a distância. Com\nbase nesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. O câncer\nde ovário é uma neoplasia muito frequente, sendo, em 2020, de acordo com o Instituto Nacional de\nCâncer, a terceira neoplasia mais comum em pacientes do sexo feminino, excetuando-se os\ntumores de pele do tipo não melanoma.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-265557","number":"265557","sourceNumber":"265557","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma paciente de 36 anos de idade procurou auxílio médico com lesão complexa em\novário esquerdo e ascite moderada à\nultrassonografia, além de elevação da dosagem sérica do\nmarcador CA-125. Foi levada a uma laparoscopia diagnóstica, sendo evidenciada a presença de\ncarcinomatose peritoneal, ?omental cake?, volumosa lesão sólido-cística ovariana à esquerda,\npouco móvel e aderida ao retossigmoide e ovário contralateral de aspecto normal. Essa paciente foi\nsubmetida a uma ooforectomia esquerda e a uma biópsia de algumas das lesões peritoneais,\nsendo o achado consistente com um carcinoma seroso de ovário moderadamente diferenciado. Foi\nsubmetida a estadiamento radiológico, que não demonstrava focos de metástases a distância. Com\nbase nesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. O próximo\npasso para essa paciente deve ser o início do tratamento com quimioterapia com alguma\nmedicação da classe das platinas e outra dos taxanos e a reavaliação com vistas à realização de\ncitorredução cirúrgica completa.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-265558","number":"265558","sourceNumber":"265558","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma paciente de 36 anos de idade procurou auxílio médico com lesão complexa em\novário esquerdo e ascite moderada à\nultrassonografia, além de elevação da dosagem sérica do\nmarcador CA-125. Foi levada a uma laparoscopia diagnóstica, sendo evidenciada a presença de\ncarcinomatose peritoneal, ?omental cake?, volumosa lesão sólido-cística ovariana à esquerda,\npouco móvel e aderida ao retossigmoide e ovário contralateral de aspecto normal. Essa paciente foi\nsubmetida a uma ooforectomia esquerda e a uma biópsia de algumas das lesões peritoneais,\nsendo o achado consistente com um carcinoma seroso de ovário moderadamente diferenciado. Foi\nsubmetida a estadiamento radiológico, que não demonstrava focos de metástases a distância. Com\nbase nesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Na faixa\netária dessa paciente (acima dos 30 anos de idade), é esperada uma incidência maior de tumores\nda linhagem germinativa em vez de tumores da linhagem epitelial.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-265559","number":"265559","sourceNumber":"265559","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma paciente de 36 anos de idade procurou auxílio médico com lesão complexa em\novário esquerdo e ascite moderada à\nultrassonografia, além de elevação da dosagem sérica do\nmarcador CA-125. Foi levada a uma laparoscopia diagnóstica, sendo evidenciada a presença de\ncarcinomatose peritoneal, ?omental cake?, volumosa lesão sólido-cística ovariana à esquerda,\npouco móvel e aderida ao retossigmoide e ovário contralateral de aspecto normal. Essa paciente foi\nsubmetida a uma ooforectomia esquerda e a uma biópsia de algumas das lesões peritoneais,\nsendo o achado consistente com um carcinoma seroso de ovário moderadamente diferenciado. Foi\nsubmetida a estadiamento radiológico, que não demonstrava focos de metástases a distância. Com\nbase nesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Como a\npaciente é jovem e o ovário contralateral estava normal na ocasião da laparoscopia diagnóstica,\npode-se pensar em cirurgia com preservação de fertilidade para essa paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-265560","number":"265560","sourceNumber":"265560","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma paciente de 36 anos de idade procurou auxílio médico com lesão complexa em\novário esquerdo e ascite moderada à\nultrassonografia, além de elevação da dosagem sérica do\nmarcador CA-125. Foi levada a uma laparoscopia diagnóstica, sendo evidenciada a presença de\ncarcinomatose peritoneal, ?omental cake?, volumosa lesão sólido-cística ovariana à esquerda,\npouco móvel e aderida ao retossigmoide e ovário contralateral de aspecto normal. Essa paciente foi\nsubmetida a uma ooforectomia esquerda e a uma biópsia de algumas das lesões peritoneais,\nsendo o achado consistente com um carcinoma seroso de ovário moderadamente diferenciado. Foi\nsubmetida a estadiamento radiológico, que não demonstrava focos de metástases a distância. Com\nbase nesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Essa\npaciente deve passar por consulta com médico geneticista, especialmente para avaliação dos\ngenes BRCA-1 e BRCA-2, que representam fator de risco para neoplasias de mama e de ovário.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-265571","number":"265571","sourceNumber":"265571","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma paciente de 43 anos de idade apresenta histórico de nodulação mamária\nesquerda de crescimento rápido nos últimos\nquatro meses, associado a vermelhidão da pele mais\nretração areolar, além de um edema cutâneo com linfadenopatia axilar semifixa ipsilateral. Foi\ntratada com antibióticos anteriormente, sem nenhuma resposta clínica significativa. Quanto a esse\ncaso clínico, considerando a hipótese diagnóstica de carcinoma inflamatório da mama e com base\nnos conhecimentos médicos correlatos, julgue o item a seguir. Para obtenção do diagnóstico,\n\ndeve-se tentar uma core biopsy da mama afetada, além de uma biópsia excisional de um fragmento\nda pele acometida pela doença, para tentar\nobter evidências de invasão linfática da pele pela\nneoplasia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-265573","number":"265573","sourceNumber":"265573","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma paciente de 43 anos de idade apresenta histórico de nodulação mamária\nesquerda de crescimento rápido nos últimos\nquatro meses, associado a vermelhidão da pele mais\nretração areolar, além de um edema cutâneo com linfadenopatia axilar semifixa ipsilateral. Foi\ntratada com antibióticos anteriormente, sem nenhuma resposta clínica significativa. Quanto a esse\ncaso clínico, considerando a hipótese diagnóstica de carcinoma inflamatório da mama e com base\nnos conhecimentos médicos correlatos, julgue o item a seguir. Como o estádio dessas pacientes é\npelo menos IIIB e cerca de um terço delas já se apresenta com doença metastática, trata-se de\numa doença com um prognóstico bem ruim.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-265574","number":"265574","sourceNumber":"265574","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma paciente de 43 anos de idade apresenta histórico de nodulação mamária\nesquerda de crescimento rápido nos últimos\nquatro meses, associado a vermelhidão da pele mais\nretração areolar, além de um edema cutâneo com linfadenopatia axilar semifixa ipsilateral. Foi\ntratada com antibióticos anteriormente, sem nenhuma resposta clínica significativa. Quanto a esse\ncaso clínico, considerando a hipótese diagnóstica de carcinoma inflamatório da mama e com base\nnos conhecimentos médicos correlatos, julgue o item a seguir. Quando não há evidência de doença\nmetastática, o tratamento deve ser iniciado por meio de cirurgia (mastectomia radical), seguido por\nquimioterapia, radioterapia, hormônio e imunoterapia (essas duas últimas, quando aplicáveis).","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-261315","number":"261315","sourceNumber":"261315","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"O rastreio e o diagnóstico precoce de neoplasias fazem parte do atendimento na Rede\nde Atenção Primária. Considerando isso,\nsuponha que uma mulher de 53 anos de idade procure\numa unidade básica de saúde para realização de exames de rotina, e o médico da Atenção\nPrimária perceba, na face dela, uma pequena lesão papulosa, de cor rósea, aspecto \"perolado\",\ncom finos vasos em sua superfície. Ao ser questionada, a paciente informa que essa lesão\napresentou crescimento lento e progressivo. Com base nesse caso clínico e nos conhecimentos\nmédicos correlatos, julgue o item a seguir. Na faixa etária dessa paciente, segundo o Ministério da\nSaúde, está indicada a realização de mamografia a cada dois anos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-250142","number":"250142","sourceNumber":"250142","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma paciente de 32 anos de idade refere, na consulta ginecológica de rotina, que\napresenta secreção mamária espontânea à\nesquerda. Com base nesse caso hipotético, julgue o\nitem a seguir. Descargas espontâneas são consideradas como fisiológicas e não exigem avaliação\nadicional.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-250143","number":"250143","sourceNumber":"250143","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma paciente de 32 anos de idade refere, na consulta ginecológica de rotina, que\napresenta secreção mamária espontânea à\nesquerda. Com base nesse caso hipotético, julgue o\nitem a seguir. A descarga papilar uniductal, espontânea e serosa é considerada como patológica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-250144","number":"250144","sourceNumber":"250144","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma paciente de 32 anos de idade refere, na consulta ginecológica de rotina, que\napresenta secreção mamária espontânea à esquerda.\nCom base nesse caso hipotético, julgue o\nitem a seguir. A maioria das descargas patológicas do mamilo é causada por papilomas intraductais\nmalignos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-239323","number":"239323","sourceNumber":"239323","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma paciente de 50 anos de idade vai a consulta em UBS com queixa de corrimento\nvaginal acinzentado e com odor fétido na última\nsemana. Refere também que gostaria de realizar\ncheck-up, pois não se consulta com médico há mais de 10 anos e está preocupada, pois a própria\nmãe foi diagnosticada com câncer de mama quando tinha 68 anos de idade. História médica\npregressa: G6P6A0, diagnóstico prévio de sífilis tratada recentemente e coitarca aos 14 anos de\nidade. Tabagista de um maço de cigarro ao dia desde os 15 anos de idade. Considerando esse\ncaso clínico e os conhecimentos médicos relacionados à saúde da mulher, julgue o item a seguir.\nDeverá ser solicitada mamografia de rastreamento para a paciente. A história descrita de câncer na\nmãe, aos 68 anos de idade, não indicaria o rastreamento da paciente em idade mais precoce que a\npopulação de baixo risco.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-239326","number":"239326","sourceNumber":"239326","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma paciente de 50 anos de idade vai a consulta em UBS com queixa de corrimento\nvaginal acinzentado e com odor fétido na última\nsemana. Refere também que gostaria de realizar\ncheck-up, pois não se consulta com médico há mais de 10 anos e está preocupada, pois a própria\nmãe foi diagnosticada com câncer de mama quando tinha 68 anos de idade. História médica\npregressa: G6P6A0, diagnóstico prévio de sífilis tratada recentemente e coitarca aos 14 anos de\nidade. Tabagista de um maço de cigarro ao dia desde os 15 anos de idade. Considerando esse\ncaso clínico e os conhecimentos médicos relacionados à saúde da mulher, julgue o item a seguir.\nPacientes multíparas, como a descrita no caso clínico, apresentam risco menor de desenvolverem\ncâncer de mama, quando comparadas às nulíparas. Entretanto, ainda não há consenso quanto à\nrelação entre câncer de mama e tabagismo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-255760","number":"255760","sourceNumber":"255760","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma paciente de 54 anos de idade, sem histórico familiar de neoplasia mamária,\ncomparece à consulta queixando-se de nódulo\nendurecido em mamilo esquerdo, que percebera no\nbanho. Essa paciente nunca realizou mamografia. Com base nesse caso clínico e nos\nconhecimentos médicos correlatos, tendo em vista o que estabelece o Ministério da Saúde do\nBrasil, julgue o item a seguir. Essa paciente deveria ter feito mamografia anualmente, a partir dos\n50 anos de idade.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-255761","number":"255761","sourceNumber":"255761","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma paciente de 54 anos de idade, sem histórico familiar de neoplasia mamária,\ncomparece à consulta queixando-se de nódulo\nendurecido em mamilo esquerdo, que percebera no\nbanho. Essa paciente nunca realizou mamografia. Com base nesse caso clínico e nos\nconhecimentos médicos correlatos, tendo em vista o que estabelece o Ministério da Saúde do\nBrasil, julgue o item a seguir. Essa paciente também deve realizar o rastreio de câncer de ovário.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-255762","number":"255762","sourceNumber":"255762","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma paciente de 54 anos de idade, sem histórico familiar de neoplasia mamária,\ncomparece à consulta queixando-se de nódulo\nendurecido em mamilo esquerdo, que percebera no\nbanho. Essa paciente nunca realizou mamografia. Com base nesse caso clínico e nos\nconhecimentos médicos correlatos, tendo em vista o que estabelece o Ministério da Saúde do\nBrasil, julgue o item a seguir. Mulheres de alto risco, com história familiar, podem realizar\nrastreio\nantes dos 50 anos de idade, de acordo com o risco individual.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-255764","number":"255764","sourceNumber":"255764","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma paciente de 44 anos de idade procura a equipe da Estratégia Saúde da Família\npara solicitar exames de rastreamento, pois\nestá preocupada com o fato de que vai iniciar atividade\nfísica (corrida). Ela afirmou que não tem doenças prévias e não usa medicamentos contínuos. Nega\nhistória de neoplasias na família e também tabagismo. Gesta 2 para 2, cesáreas 0 e aborto 0. PA =\n120 mmHg x 80 mmHg; FC = 70 bpm; FR = 14 irpm; SpO2 = 98%; peso = 64 kg; estatura = 1,68; e\nIMC = 22,7. Com base nesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a\nseguir. Segundo as recomendações atuais do Ministério da Saúde, deverá ser realizado exame\nclínico das mamas e solicitada mamografia dessa paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-214456","number":"214456","sourceNumber":"214456","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Determinada paciente teve um único filho, em uma gestação que transcorreu sem\nintercorrências até 36 semanas, mas culminou em um parto cesáreo de emergência. Essa criança\nfoi amamentada pela mãe até os 2 anos de idade e cresceu saudável. A paciente sempre se\npreocupou com a realização dos exames ginecológicos preventivos, e atualmente, ela está com 45\nanos de idade e ainda se encontra na menacme. Durante avaliação anual com o ginecologista\nparticular dela, essa paciente foi submetida a mamografia bilateral, com achado de alterações tipo\nBIRADS III, citopatológico do esfregaço cervical, com achados normais e ultrassonografia\ntransvaginal. No ano anterior, a mamografia havia apresentado alterações tipo BIRADS II e\ncitopatológico do esfregaço cervical também normal. Considerando esse caso clínico e a respeito\ndessas estratégias de prevenção, da frequência recomendada e das respectivas doenças alvo,\njulgue o item a seguir. De acordo com a American Cancer Society, essa paciente deve ser\norientada a realizar o autoexame de mamas a cada ciclo menstrual.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-214459","number":"214459","sourceNumber":"214459","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Determinada paciente teve um único filho, em uma gestação que transcorreu sem\nintercorrências até 36 semanas, mas culminou em um parto cesáreo de emergência. Essa criança\nfoi amamentada pela mãe até os 2 anos de idade e cresceu saudável. A paciente sempre se\npreocupou com a realização dos exames ginecológicos preventivos e, atualmente, ela está com 45\nanos de idade e ainda se encontra na menacme. Durante avaliação anual com o ginecologista\nparticular dela, essa paciente foi submetida à mamografia bilateral, com achado de alterações tipo\nBIRADS III, citopatológico do esfregaço cervical, com achados normais e ultrassonografia\ntransvaginal. No ano anterior, a mamografia havia apresentado alterações tipo BIRADS II e\ncitopatológico do esfregaço cervical também normal. Considerando esse caso clínico e a respeito\ndessas estratégias de prevenção, da frequência recomendada e das respectivas doenças alvo,\njulgue o item a seguir. A ultrassonografia pélvica transvaginal deve ser repetida em cinco anos,\ncomo parte do rastreio de neoplasia de ovário.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-196668","number":"196668","sourceNumber":"196668","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Determinada paciente de 55 anos de idade apresenta, em exame físico, nódulo\nmamário em quadrante superior externo de\nmama esquerda, redondo, de margem circunscrita, de\naproximadamente 1 cm x 1 cm, sem outros sintomas associados. A pressão arterial na consulta era\nde 120 mmHg x 80 mmHg, FC de 75 bpm e 18 irpm, saturando 99% em ar ambiente. Ela então\ncomparece ao exame levando o resultado da mamografia que foi solicitada em última consulta.\n\nNega mamografias prévias. Em laudo, consta classificação de BI-RADS 0 (zero). A respeito desse\ncaso clínico e com base nos conhecimentos\nmédicos correlatos, julgue o item a seguir. É\nimportante solicitar ecografia mamária para complementar investigação.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-214464","number":"214464","sourceNumber":"214464","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Determinada paciente teve um único filho, em uma gestação que transcorreu sem\nintercorrências até 36 semanas, mas culminou em um parto cesáreo de emergência. Essa criança\nfoi amamentada pela mãe até os 2 anos de idade e cresceu saudável. A paciente sempre se\npreocupou com a realização dos exames ginecológicos preventivos, e atualmente, ela está com 45\nanos de idade e ainda se encontra na menacme. Durante avaliação anual com o ginecologista\nparticular dela, essa paciente foi submetida a mamografia bilateral, com achado de alterações tipo\nBIRADS III, citopatológico do esfregaço cervical, com achados normais e ultrassonografia\ntransvaginal. No ano anterior, a mamografia havia apresentado alterações tipo BIRADS II e\ncitopatológico do esfregaço cervical também normal. Considerando esse caso clínico e a respeito\ndessas estratégias de prevenção, da frequência recomendada e das respectivas doenças alvo,\njulgue o item a seguir. Na análise da mamografia, a presença de alterações tipo BIRADS III não\ngera mudança na conduta.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-196675","number":"196675","sourceNumber":"196675","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Determinada paciente de 55 anos de idade apresenta, em exame físico, nódulo\nmamário em quadrante superior externo de\nmama esquerda, redondo, de margem circunscrita, de\naproximadamente 1 cm x 1 cm, sem outros sintomas associados. A pressão arterial na consulta era\nde 120 mmHg x 80 mmHg, FC de 75 bpm e 18 irpm, saturando 99% em ar ambiente. Ela então\ncomparece ao exame levando o resultado da mamografia que foi solicitada em última consulta.\n\nNega mamografias prévias. Em laudo, consta classificação de BI-RADS 0 (zero). A respeito desse\ncaso clínico e com base nos conhecimentos\nmédicos correlatos, julgue o item a seguir. BI-RADS 0\né um achado de bom prognóstico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-214468","number":"214468","sourceNumber":"214468","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Determinada paciente teve um único filho, em uma gestação que transcorreu sem\nintercorrências até 36 semanas, mas culminou em um parto cesáreo de emergência. Essa criança\nfoi amamentada pela mãe até os 2 anos de idade e cresceu saudável. A paciente sempre se\npreocupou com a realização dos exames ginecológicos preventivos, e atualmente, ela está com 45\nanos de idade e ainda se encontra na menacme. Durante avaliação anual com o ginecologista\nparticular dela, essa paciente foi submetida a mamografia bilateral, com achado de alterações tipo\nBIRADS III, citopatológico do esfregaço cervical, com achados normais e ultrassonografia\ntransvaginal. No ano anterior, a mamografia havia apresentado alterações tipo BIRADS II e\ncitopatológico do esfregaço cervical também normal. Considerando esse caso clínico e a respeito\ndessas estratégias de prevenção, da frequência recomendada e das respectivas doenças alvo,\njulgue o item a seguir. Segundo o Ministério da Saúde, a próxima citopatologia do esfregaço\ncervical para rastreamento da neoplasia de colo uterino deve ser realizada em dois anos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-214476","number":"214476","sourceNumber":"214476","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma paciente de 52 anos de idade, durante investigação por perda ponderal de 10 kg\nem seis meses, foi diagnosticada com\nneoplasia de ovário. Nos exames necessários para o\nestadiamento, observaram-se massa tumoral em ambos os ovários, com diâmetro de 10 cm e 7 cm\nem seus maiores eixos, implantes peritoneais maiores que 2 cm na cápsula do fígado, implantes\nparenquimatosos em baço, fígado e pulmões e presença de células neoplásicas em derrame\npleural localizado à direita. Quanto a esse caso clínico, julgue o item a seguir. O estadiamento\ndesse tumor é IIIc.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-214376","number":"214376","sourceNumber":"214376","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma paciente de 52 anos de idade, durante investigação por perda ponderal de 10 kg\nem seis meses, foi diagnosticada com\nneoplasia de ovário. Nos exames necessários para o\nestadiamento, observaram-se massa tumoral em ambos os ovários, com diâmetro de 10 cm e 7 cm\nem seus maiores eixos, implantes peritoneais maiores que 2 cm na cápsula do fígado, implantes\nparenquimatosos em baço, fígado e pulmões e presença de células neoplásicas em derrame\npleural localizado à direita. Quanto a esse caso clínico, julgue o item a seguir. Pode-se optar pelo\ntratamento quimioterápico exclusivo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-214434","number":"214434","sourceNumber":"214434","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Qualquer sistema de saúde, público ou privado, deve organizar estratégias de\npromoção de saúde e prevenção de doenças,\nvisando a diminuir a morbimortalidade da respectiva\npopulação assistida e reduzir os custos associados a determinadas doenças. Com base no\nexposto, considere que o gestor responsável por determinada Secretaria Estadual de Saúde\nprecise realizar o planejamento de objetivos e custos do próximo ano, incluindo todos os diferentes\nníveis de atenção à saúde, estratégias de promoção à saúde e prevenção de doenças. Acerca\ndesse caso clínico e com base nos conhecimentos médicos correlatos, julgue o item a seguir. A\nrealização do rastreamento da neoplasia de mama é uma estratégia de prevenção secundária.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-179164","number":"179164","sourceNumber":"179164","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Assinale a alternativa que apresenta a neoplasia maligna mais letal em mulheres.","options":{"A":"Adenocarcinoma de mama.","B":"Carcinoma de colo uterino.","C":"Carcinoma de ovário.","D":"Câncer de tireoide.","E":"Câncer de endométrio."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-179169","number":"179169","sourceNumber":"179169","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"A respeito do câncer de mama feminino, é correto afirmar que","options":{"A":"as estratégias para diagnóstico precoce sejam o exame clínico anual das mamas a partir dos\nquarenta anos de idade e a mamografia bilateral anual dos cinquenta aos 69 anos de idade.","B":"a idade seja seu principal fator de risco, uma vez que a incidência aumenta rapidamente até os\ncinquenta anos de idade, sendo mais lenta após.","C":"o prognóstico seja bom, mesmo quando diagnosticado em estágios avançados, devido aos\navanços terapêuticos.","D":"os melhores resultados de sobrevida estejam relacionados principalmente ao diagnóstico\nprecoce por ecografia mamária, que é pouco\ninvasivo.","E":"as características de malignidade ao exame clínico sejam nódulos mamários geralmente\nmúltiplos, de consistências císticas e pouco aderidos ao tecido adjacente."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-177679","number":"177679","sourceNumber":"177679","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente de 45 anos de idade comparece a uma Unidade Básica de Saúde (UBS) para\nfazer exames da mama, pois está preocupada, uma vez que sua mãe teve diagnóstico de câncer\nmamário aos 60 anos de idade. Considerando essa situação e os conhecimentos médicos a ela\nrelacionados, julgue o item a seguir. Há risco aumentado em mulheres com casos da doença em\nparentes de primeiro grau, sendo o risco maior quando o câncer de mama ocorreu antes da\nmenopausa.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-177689","number":"177689","sourceNumber":"177689","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente de 45 anos de idade comparece a uma Unidade Básica de Saúde (UBS) para\nfazer exames da mama, pois está preocupada, uma vez que sua mãe teve diagnóstico de câncer\nmamário aos 60 anos de idade. Considerando essa situação e os conhecimentos médicos a ela\nrelacionados, julgue o item a seguir. A mamografia é o único método de rastreamento\ncomprovadamente eficaz para reduzir a mortalidade por câncer de mama.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-177694","number":"177694","sourceNumber":"177694","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente de 45 anos de idade comparece a uma Unidade Básica de Saúde (UBS) para\nfazer exames da mama, pois está preocupada, uma vez que sua mãe teve diagnóstico de câncer\nmamário aos 60 anos de idade. Considerando essa situação e os conhecimentos médicos a ela\nrelacionados, julgue o item a seguir. Mamas densas são um fator de risco para câncer de mama e\nestão associadas à redução da sensibilidade da mamografia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-154324","number":"154324","sourceNumber":"154324","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente, 33 anos de idade, compareceu ao consultório ginecológico, pois, há dois\nmeses, notou nódulo na mama direita, móvel e\nindolor, com cerca de 2 cm de diâmetro. Está\npreocupada porque a irmã faleceu há um ano em decorrência de câncer de mama. Foi realizada\nultrassonografia mamária, que evidenciou nódulo ovalado, com maior diâmetro paralelo a pele,\nmedindo 2,0 cm x 1,0 cm a 1,5 cm com contornos bem definidos e margens regulares. Nesse caso\nclínico, é indicada(o)","options":{"A":"Quadrantectomia com marcação de linfonodo sentinela.","B":"Controle ultrassonográfico em seis meses.","C":"PAAF.","D":"Mamotomia.","E":"Mastectomia direita com reconstrução mamária."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-135031","number":"135031","sourceNumber":"135031","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Com relação ao tratamento do paciente com câncer, julgue o próximo item. Nos\npacientes portadores de câncer de mama nos\nestágios I e II, a realização de quadrantectomia\nassociada à dissecção ganglionar axilar seguida de radioterapia é tão efetiva quanto a mastectomia\nradical modificada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-4-140730","number":"140730","sourceNumber":"140730","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"O termo câncer de mama abrange uma diversidade de neoplasias malignas do tecido\nmamário que divergem entre si no que tange ao comportamento biológico celular. Acerca da\nprevenção, diagnóstico, classificação e tratamento das doenças da mama, julgue o item\nsubsecutivo. O subtipo intrínseco luminal A tem evolução natural desfavorável, origina-se em\ncélulas epiteliais ricas em receptores de estrogênio e progesterona, com índice de KI-67 < 14% e\nsuperexpressão de HER-2.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-135008","number":"135008","sourceNumber":"135008","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Julgue o próximo item, com relação aos distúrbios pré-malignos e malignos do trato\ngenital feminino e da mama. Situação hipotética: Uma paciente de dezenove anos de idade, com\nhistória de menarca aos onze anos, comparece ao hospital, apresentando sangramento uterino\nanormal havia três meses, além de dor pélvica aguda, massa abdominal palpável em flanco\nesquerdo com crescimento rápido e distensão abdominal. Assertiva: Nesse caso, ela apresenta\nfortes evidências de ser portadora de disgerminoma ovariano.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-4-135014","number":"135014","sourceNumber":"135014","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Julgue o próximo item, com relação aos distúrbios pré-malignos e malignos do trato\ngenital feminino e da mama. Mulheres na menacme\nque apresentam mastalgia, principalmente no\nperíodo pré-menstrual, e alterações fibróticas no estroma, com formação cística dentro da mama,\nque variam de acordo com o ciclo menstrual são portadoras de doença fibrocística da mama. Esta é\numa doença benigna e, por consequência, não apresenta risco aumentado de desenvolvimento de\ncâncer de mama.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-4-135058","number":"135058","sourceNumber":"135058","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"No que diz respeito à bioética e aos cuidados paliativos, julgue o item a seguir.\nSituação hipotética: Uma paciente de oitenta e\nquatro anos de idade, lúcida e ativa, procurou\natendimento médico, por apresentar um nódulo na mama direita. Após a realização de exames, o\ncorpo clínico detectou presença de câncer de mama avançado com metástase para o ovário. O\nfilho dessa idosa solicitou ao médico que não informasse o diagnóstico à paciente, para não\napressar a morte dela. Assetiva: Nessa situação, para preservar a autonomia da paciente, o médico\ndeve comunicá-la do diagnóstico em momento oportuno.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-4-105571","number":"105571","sourceNumber":"105571","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma paciente de 54 anos de idade compareceu à consulta de rotina com o\nginecologista. Referiu perda de urina a médios\nesforços e sangramento vaginal há duas semanas.\nAntecedentes ginecológicos: menarca aos doze anos, menopausa aos 51 anos de idade,\nG1PN1A0, sem antecedentes familiares de câncer ginecológico. Foram solicitados exames com os\nseguintes resultados: Ecografia transvaginal: útero em AVF com volume de 80 cm³, endométrio de\n10 mm, ovários atróficos; Mamografia: BIRADS 2; Estudo urodinâmico: incontinência urinária de\nesforço com defeito esfincteriano. Acerca da classificação da mamografia, pode(m)-se citar como\nexemplo:","options":{"A":"microcalcificações pleomórficas agrupadas.","B":"nódulo espiculado.","C":"assimetria de densidade que se acentua à compressão.","D":"calcificações vasculares.","E":"nódulos de limites irregulares não visualizados em exames anteriores."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-108195","number":"108195","sourceNumber":"108195","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Com referência a oncologia ginecológica e mamária, julgue o item a seguir. No exame\nde mamografia de mulheres com idade superior a\ntrinta e cindo anos de idade, a observação de\nnódulos com contornos lobulados mal definidos ou atenuados no quadrante superior externo\nconstitui forte evidência de câncer de mama.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-4-88654","number":"88654","sourceNumber":"88654","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"A propósito das doenças oncológicas, julgue o próximo item. O combate à obesidade e\na redução da ingestão de bebidas alcóolicas\najudam a prevenir o câncer de mama em mulheres.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-82091","number":"82091","sourceNumber":"82091","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"O médico é frequentemente procurado para consultas de avaliação do estado de saúde\nde pacientes assintomáticos. Nessas ocasiões, é\nde grande importância adotar medidas\npreventivas de saúde. Acerca desse assunto, julgue o item seguinte. Os principais fatores que\ndevem ser considerados ao planejar o rastreamento de risco de câncer de mama em mulheres são:\nidade acima dos cinquenta anos, histórico pessoal - faixa etária em que a mulher teve o primeiro\nfilho - e histórico familiar.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-88674","number":"88674","sourceNumber":"88674","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"No que se refere à oncologia, julgue o próximo item. Entre os principais fatores de risco\nresponsáveis pelo câncer de mama incluem-se menarca precoce, parente masculino de primeiro\ngrau com câncer de mama, hiperplasia ductal atípica em biopsia mamária e primeira gestação a\ntermo após trinta e cinco anos de idade.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-4-45736","number":"45736","sourceNumber":"45736","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente de 56 anos de idade, com rotinas mamográficas atualizadas para a idade,\ntabagista, menarca aos 10 anos, G4P4 (N4C0) A0,\nprimeira gestação aos 17 anos, menopausa aos\n48 anos e com irmã com câncer de mama diagnosticado aos 63 anos de idade, leva à consulta\nmamografia recente, classificação BI-RADS 3. Em relação ao caso descrito no texto, assinale a\nalternativa correta:","options":{"A":"O sexo feminino é um importante fator de risco na incidência do câncer de mama em uma\nproporção de cinquenta casos na mulher para cada caso no homem.","B":"Para a paciente em questão, são fatores de risco importantes para neoplasia maligna da mama:\nsexo, idade, tabagismo e história familiar.","C":"Considerando a história familiar, a chance de essa paciente ter câncer de mama é aumentada\nde cinco a dez vezes em relação à população cuja\nhistória familiar seja negativa para câncer de\nmama.","D":"Multiparidade, primeira gestação precoce, menarca e menopausa tardias podem ser\nconsideradas fatores protetores para desenvolvimento de câncer de mama nessa paciente.","E":"Considerando a idade dessa paciente, é acertado afirmar que ela se enquadra no grupo de\nmaior risco para incidência de câncer de mama."},"answer":"E","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-45739","number":"45739","sourceNumber":"45739","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente de 56 anos de idade, com rotinas mamográficas atualizadas para a idade,\ntabagista, menarca aos 10 anos, G4P4 (N4C0) A0,\nprimeira gestação aos 17 anos, menopausa aos\n48 anos e com irmã com câncer de mama diagnosticado aos 63 anos de idade, leva à consulta\nmamografia recente, classificação BI-RADS 3. A classificação BI-RADS da mamografia dessa\npaciente enquadra-se em achados:","options":{"A":"inconclusivos.","B":"negativos.","C":"benignos.","D":"provavelmente benignos.","E":"suspeitos."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-52633","number":"52633","sourceNumber":"52633","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Acerca das anatomias feminina e fetal, julgue o item subsequente. A irrigação arterial\nda mama se dá principalmente por meio das\nartérias mamária interna, toracoacromial, torácica\nlateral e intercostais posteriores.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-52634","number":"52634","sourceNumber":"52634","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Acerca das anatomias feminina e fetal, julgue o item subsequente. A artéria ovariana\nesquerda é ramo da artéria renal esquerda, ao passo que a direita, na maioria das mulheres, é\nramo da artéria ilíaca comum.","options":{"A":"Certo.","B":"Errado."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-52608","number":"52608","sourceNumber":"52608","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Julgue o item a seguir, acerca das recomendações constantes nas Diretrizes Brasileiras\npara o Rastreamento do Câncer do Colo do\nÚtero para mulheres sem história prévia de lesões\nprecursoras do câncer do colo uterino. Para mulheres sem história de atividade sexual, não há\nindicação de rastreamento do câncer do colo do útero e seus precursores.","options":{"A":"Certo","B":"Errado"},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-4-52613","number":"52613","sourceNumber":"52613","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Julgue o item a seguir, acerca das recomendações constantes nas Diretrizes Brasileiras\npara o Rastreamento do Câncer do Colo do\nÚtero para mulheres sem história prévia de lesões\nprecursoras do câncer do colo uterino. A coleta de material para o exame citopatológico deverá\niniciar-se aos vinte e cinco anos de idade para as mulheres que já tiveram atividade sexual.","options":{"A":"Certo","B":"Errado"},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-4-52620","number":"52620","sourceNumber":"52620","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Julgue o item a seguir, acerca das recomendações constantes nas Diretrizes Brasileiras\npara o Rastreamento do Câncer do Colo do\nÚtero para mulheres sem história prévia de lesões\nprecursoras do câncer do colo uterino. Os exames citopatológicos devem seguir até os sessenta e\nquatro anos de idade e serem interrompidos quando, após essa idade, as mulheres tiverem pelo\nmenos dois exames consecutivos negativos nos últimos cinco anos.","options":{"A":"Certo","B":"Errado"},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-32144","number":"32144","sourceNumber":"32144","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Quanto à patologia ovariana, assinale a alternativa correta.","options":{"A":"Um dos fatores de risco para a neoplasia de ovário é a multiparidade.","B":"O disgerminoma tem crescimento lento e atinge grandes volumes, causando compressão\nabdominal.","C":"O tumor do seio endodérmico tem crescimento rápido e dissemina-se por via hematogência,\ntendo recorrência pós-cirúrgica; a quimioterapia\nadjuvante é usada após cirurgia.","D":"O teratoma imaturo costuma ser produtor de hCG, sendo este um bom marcador tumoral para\nrastreio.","E":"A biópsia do ovário contralateral em pacientes jovens com tumor de seio endodérmico deve ser\nrealizada para investigação de disgenesia gonadal."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-27554","number":"27554","sourceNumber":"27554","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"O triplo teste diagnóstico utilizado na busca de lesões da mama é composto por:","options":{"A":"anamnese, palpação, mamografia.","B":"palpação, mamografia, ultrassonografia.","C":"palpação, mamografia, punção-biópsia por aspiração com agulha fina.","D":"palpação, mamografia, core biópsia.","E":"palpação, mamografia, biópsia por incisão."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-13846","number":"13846","sourceNumber":"13846","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Acerca das patologias benignas do trato reprodutivo feminino, assinale a opção correta.","options":{"A":"Com o início da menopausa, os leiomiomas uterinos tendem a aumentar de volume.","B":"Estudos das menstruações em adolescentes mostram que quanto menor a idade da menarca\nmais tarde se estabelece a ovulação regular.","C":"A causa mais frequente de sangramento uterino anormal na menacme é polipose endometrial.","D":"Os cistos ovarianos funcionais incluem cistos foliculares, cistos do corpo lúteo e\nteca-luteinicos.\n\nO cisto funcional mais comum é do corpo lúteo.","E":"O tratamento com contraceptivos orais combinados reduz o risco de cistos ovarianos funcionais."},"answer":"E","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-7552","number":"7552","sourceNumber":"7552","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Jovem de 23 anos de idade, virgem, queixa-se de um rápido aumento de volume\nabdominal. Na ultrassonografia pélvica mostra uma imagem sólida em topografia de ovário\nesquerdo. Foram solicitados marcadores tumorais, que demonstraram positividade de\nalfafetoproteína e negatividade para a gonadotrofina coriônica, CEA e Ca-125. Assinale a\nalternativa que contém diagnóstico e a opção terapêutica.","options":{"A":"Disgeminoma por ser o mais frequente nessa idade e indicar quimioterapia.","B":"Teratoma maduro por ser unilateral e indica rooforectomia unilateral com biópsia do ovário\ncontralateral pela possibilidade de bilateralidade.","C":"Tumor do seio endodérmico devido ao marcador tumoral ter sido positivo e indicar ooforectomia\nunilateral.","D":"Disgerminoma por ser o mais frequente nessa idade e indicar remoção do ovário e realização do\ncariótipo devido a ocorrência de ovários disgenéticos nessas mulheres.","E":"Tumor de Brenner por ser sólido ao ultrassom e indica rooforectomia unilateral."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-7571","number":"7571","sourceNumber":"7571","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente de sessenta anos de idade, com mãe falecida de câncer de mama, apresenta\ntumor mamário com descarga papilar serosa\nespontânea. Qual a melhor orientação para o\ndiagnóstico?","options":{"A":"Mamografia bilateral e biópsia da papila.","B":"Ductografia e mamografia bilateral.","C":"Ultrassonografia mamária e punção aspirativa do tumor.","D":"Biópsia do tumor e citologia da descarga papilar.","E":"Exame físico das mamas e citologia da descarga papilar."},"answer":"E","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-334901","number":"334901","sourceNumber":"334901","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Um dos sintomas mais comuns associados às pacientes na idade fértil relaciona-se à\ndor cíclica das mamas. Acerca das patologias mamárias, assinale a alternativa correta.","options":{"A":"A mastodinia cíclica é um dos sintomas mais comuns relacionados ao período fértil da paciente\ne, quase na totalidade dos casos, possui\ncaracterísticas de benignidade, sendo raramente\nencontrada alguma alteração no exame físico ou nos exames complementares.","B":"O câncer de mama possui como fatores de risco a presença de dor mamária, associada a\nnodulações móveis, regulares, de consistência fibroelástica, que devem ser biopsiadas sempre que\npossível.","C":"A presença de cistos mamários medindo acima de 2 cm raramente associa-se com a dor\nmamária, sendo possível o tratamento\nmedicamentoso com uso de antagonistas dopaminérgicos\ncomo a cabergolina.","D":"A descarga papilar escurecida relaciona-se com aumento da secreção de prolactina, permitindo\numa secreção láctea acumulada que adquire\ncoloração amarronzada ao se exteriorizar.","E":"O exame de rastreio do câncer de mama inclui a ultrassonografia mamária com possibilidade de\nrastreio precoce de microcalcificações, que são lesões precursoras de carcinomas intraductais."},"answer":"E","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-343446","number":"343446","sourceNumber":"343446","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"A principal alteração mamária sugestiva de diagnóstico positivo para câncer de mama\né:","options":{"A":"Cistos densos.","B":"Microcalcificações.","C":"Nódulo sólido.","D":"Mastalgia."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-343447","number":"343447","sourceNumber":"343447","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Com relação ao câncer de ovário, é CORRETO afirmar:","options":{"A":"Entre os fatores de risco para o câncer de ovário, destacam-se nuliparidade, utilização de\ncontraceptivos orais por tempo prolongado, história familiar e disgenesia gonadal.","B":"A ultrassonografia transvaginal não é útil na diferenciação de tumores benignos e malignos\niniciais.","C":"Mutações em genes, como BRCA1 e BRCA2, não estão relacionadas ao risco elevado de\ncâncer de ovário.","D":"Os tumores mais frequentes do ovário originam-se do epitélio celômico, que possui capacidade\nde diferenciação para epitélios dos tipos tubário,\nendocervival ou endometrial."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-343457","number":"343457","sourceNumber":"343457","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma das funções do ovário é:","options":{"A":"Fixação do embrião.","B":"Liberação de gametas.","C":"Produção de prolactina.","D":"Produção de tiroxina 4."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-307121","number":"307121","sourceNumber":"307121","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"No que se refere às afecções da mama, assinale a alternativa correta. Alternativas:","options":{"A":"O fibroadenoma é o tumor epitelial mais comum em paciente jovem e pode invariavelmente\ncursar com mastodinia cíclica.","B":"O tumor filoide possui grande correlação com câncer de mama, devendo ser diagnosticado\nprecocemente e tratado com mastectomia radical.","C":"A quadrantectomia da mama, ou cirurgia conservadora, pode ser realizada nos tumores\nmenores de 5 cm, sem necessidade de radioterapia.","D":"A classificação molecular dos cânceres de mama inclui o luminal A, que possui índice de\nproliferação celular (ki67>14%) e receptor de progesterona sempre positivo.","E":"A presença do HER2 não entra na classificação molecular dos cânceres de mama, sendo assim\nesse tipo de câncer pode ser luminal A, B ou triplo negativo."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-301311","number":"301311","sourceNumber":"301311","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Acerca da anatomia pélvica feminina e das respectivas eventuais variações, julgue os\nitens 68 e 69. A drenagem venosa ovariana se dá por meio de um plexo bem desenvolvido,\ndrenando através das veias ovarianas para a veia renal (à direita) e para a veia ilíaca comum (à\nesquerda).","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-301322","number":"301322","sourceNumber":"301322","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma paciente de 49 anos de idade, com nódulo endurecido na mama direita e\nmamografia BI-RADS 5, teve diagnóstico de câncer\nde mama. Antecedentes pessoais e familiares:\nG3PN3, ciclos menstruais irregulares, DUM há quatro meses e mãe com diagnóstico de câncer de\nmama unilateral aos 66 anos de idade. Ao exame físico, constatam-se mamas de médio volume,\nretração no quadrante inferior lateral direito com desvio do mamilo ipsilateral, nódulo palpável na\nregião retroareolar direita de 4,5 cm X 3 cm e axila clinicamente negativa. O estudo\nanatomopatológico da lesão evidenciou carcinoma ductal invasivo, grau histológico 1 de\nNottingham e imuno-histoquímica com receptores hormonais (estrogênio e progesterona)\nnegativos, HER-2 positivo e índice de Ki-67 de 12%. Com base no caso clínico apresentado, julgue\no item a seguir. O tratamento cirúrgico recomendado é mastectomia simples à direita, com biópsia\nde linfonodo sentinela com congelação (em caso de sentinela positivo, realizar a linfadenectomia\naxilar direita no ato operatório), e reconstrução mamária.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-301323","number":"301323","sourceNumber":"301323","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma paciente de 49 anos de idade, com nódulo endurecido na mama direita e\nmamografia BI-RADS 5, teve diagnóstico de câncer\nde mama. Antecedentes pessoais e familiares:\nG3PN3, ciclos menstruais irregulares, DUM há quatro meses e mãe com diagnóstico de câncer de\nmama unilateral aos 66 anos de idade. Ao exame físico, constatam-se mamas de médio volume,\nretração no quadrante inferior lateral direito com desvio do mamilo ipsilateral, nódulo palpável na\nregião retroareolar direita de 4,5 cm X 3 cm e axila clinicamente negativa. O estudo\nanatomopatológico da lesão evidenciou carcinoma ductal invasivo, grau histológico 1 de\nNottingham e imuno-histoquímica com receptores hormonais (estrogênio e progesterona)\nnegativos, HER-2 positivo e índice de Ki-67 de 12%. Com base no caso clínico apresentado, julgue\no item a seguir. No tratamento adjuvante, a quimioterapia é dispensável para o caso em tela.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-268917","number":"268917","sourceNumber":"268917","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma paciente de 32 anos de idade compareceu ao ginecologista com queixa de\nnodulação unilateral em mama esquerda, de início há um mês, associado a derrame papilar\nunilateral amarelado, sem mastodínia associada. Negou antecedentes familiares de neoplasias e\nperda ponderal no período. Ao exame físico, encontra-se em BEG, corada, hidratada, acianótica,\nanictérica e afebril. Verificam-se as mamas com volume normal, sem abaulamentos ou retrações,\nmamilos centrados e proeminentes, parênquima heterogêneo com predomínio fibroglandular e\nnodulação palpável em quadrante superior lateral da mama esquerda de aproximadamente 3 cm,\nde consistência fibroelástica, móvel e indolor. Com base nesse caso clínico e nos conhecimentos\nmédicos correlatos, assinale a alternativa correta.","options":{"A":"Segundo o Ministério da Saúde, o rastreio das patologias mamárias deve iniciar com mamografia\na partir dos 50 anos de idade e\nultrassonografia mamária nas pacientes com idade inferior aos 50\nanos.","B":"Os sinais de suspeita de malignidade desse caso são derrame papilar amarelado e nodulação\nunilateral de volume aumentado.","C":"A investigação de nódulos mamários inclui punção biópsia aspirativa com agulha fina (PBAAF),\npara diferenciação de nódulo e de cisto, e core\nbiópsia nos casos de nódulos para\nanatomopatológico.","D":"Nesse caso, se confirmado tumor de mama por core biópsia, o estadiamento seria T3 e seria\nindicado quadrantectomia com esvaziamento axilar e avaliação de linfonodo sentinela.","E":"O diagnóstico mais provável nas pacientes jovens seria o tumor filoide, com crescimento lento."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-263381","number":"263381","sourceNumber":"263381","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma mulher com 44 anos de idade é encaminhada para avaliação de nódulos\nmamários múltiplos, inicialmente atribuídos a\npossível doença fibrocística benigna da mama. A\nrazão do encaminhamento ao especialista é a preocupação da paciente com o fato de uma tia\npaterna, com 68 anos de idade, ter sido recentemente diagnosticada com câncer de mama\n(adenocarcinoma ductal infiltrante). A paciente é multípara (G4P5), tendo sua primeira gestação\nocorrido aos 36 anos de idade. Amamentou todos os filhos por pelo menos 1 ano. Sua menarca foi\ntardia, ocorrendo aos 16 anos de idade. Relata que seus ciclos menstruais são indolores e\nregulares, a cada 28 dias (3 dias de duração), com fluxo em volume normal. Mantém relações\nsexuais regulares, com parceiro único e sem uso de preservativo. Ela nega possuir comorbidades e\nalergias. No exame das mamas, são palpados múltiplos nódulos de consistência fibroelástica\nbilaterais, no meio dos quais é palpado um nódulo sólido, indolor e pouco móvel, de 2,0 cm de\ndiâmetro, localizado no quadrante superior externo da mama esquerda; não há alterações cutâneas\nlocais nem linfonodomegalias satélites, axilares, supraclaviculares ou cervicais. No exame físico\ngeral, a paciente se encontra em bom estado, corada, com IMC = 23,5 kg/m². Além do nódulo\nsólido palpável, qual é o outro fator de risco para câncer de mama que a paciente apresenta?","options":{"A":"Multiparidade.","B":"Menarca tardia.","C":"Primeira gestação em idade avançada.","D":"Tia paterna com câncer de mama pós-menopausa."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-273354","number":"273354","sourceNumber":"273354","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Você é indicado para um comitê consultivo da OMS com a tarefa de fazer\nrecomendações sobre o rastreamento e prevenção do\ncâncer de mama. Com relação ao\nrastreamento e prevenção do câncer de mama em mulheres, qual das seguintes recomendações\npotenciais do seu comitê seria válida?","options":{"A":"Qualquer câncer de mama detectado por mamografia de rastreamento e tratado adequadamente\nrepresenta uma redução na mortalidade por\ncâncer de mama.","B":"O rastreamento é mais eficaz quando aplicado a doenças relativamente comuns. O câncer de\nmama, com risco ao longo da vida de 10% nas mulheres, atende a esse critério.","C":"A presença de um estágio latente (assintomático) de câncer de mama o torna um candidato a\ndoença menos ideal para rastreamento em nível\npopulacional.","D":"Ao estudar a eficácia do rastreamento do câncer de mama com mamografia em uma população,\no tempo de sobrevida da doença é o resultado\nmais importante a se considerar."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-274643","number":"274643","sourceNumber":"274643","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"A cirurgia é a principal modalidade de tratamento dos tumores sólidos. Quanto à biópsia\nque permite a avaliação histológica do tumor, é CORRETO afirmar:","options":{"A":"A biópsia incisional retira a lesão inteira e permite a avaliação histológica do tumor.","B":"A biópsia excisional retira apenas parte da lesão e permite a avaliação histológica do tumor.","C":"A biópsia por punção com agulha grossa permite a avaliação histológica do tumor.","D":"A punção aspirativa por agulha fina permite a avaliação histológica do tumor."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-263400","number":"263400","sourceNumber":"263400","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma mulher com 25 anos de idade vai ao ambulatório de ginecologia com queixa de\ndor pélvica há 24 horas. Possui ciclos\nregulares de 28 dias (3 a 4 dias) e a sua última menstruação\nocorreu há 3 semanas. No exame clínico, observou-se PA = 110 x 70 mmHg e pulso = 84 bpm.\n\nNotou-se dor à palpação profunda em fossa ilíaca esquerda e em região hipogástrica, Blumberg\nnegativo. Sem outras anormalidades durante o\nexame físico. Foi realizada ultrassonografia\ntransvaginal que revelou estrutura cística no ovário esquerdo, medindo 7,0 x 6,5 cm, sem fluxo ao\nestudo Doppler, conforme indica imagem a seguir. Considerando o caso clínico apresentado e a\nhipótese diagnóstica mais provável, qual deve ser a conduta médica?","options":{"A":"Solicitar ressonância magnética da pelve.","B":"Encaminhar para laparoscopia exploradora.","C":"Orientar a repetição da ultrassonografia após a menstruação.","D":"Solicitar marcadores tumorais, como o antígeno carcino-embrionário e o CA-125."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":["question_bank/media/medcurso/medcurso-gineco-gin-4/263400.png"],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-291524","number":"291524","sourceNumber":"291524","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma paciente de 53 anos de idade comparece ao ambulatório de Clínica Médica onde\nfaz acompanhamento regular de suas doenças crônicas\nnão transmissíveis (DCNTS - hipertensão\narterial sistêmica, diabetes mellitus e obesidade). Durante a consulta de seguimento, a paciente\nmanifesta preocupação com um \"caroço\" que detectou há cerca de 1 mês em sua mama esquerda.\nEla nega emagrecimento, dor local ou descarga mamilar. Além das medicações que faz uso em\nrazão de suas DCNTs, a paciente vem em uso de terapia de reposição hormonal (TRH) desde que\nentrou na menopausa, há 12 anos. Ela tem 5 filhos, tendo sua menarca ocorrida de forma tardia\n(aos 15 anos). A paciente não fuma, nem consome álcool. Ao exame físico dirigido à queixa atual, o\nmédico detecta a presença de lesão nodular de cerca de 2,5 cm, endurecida, não aderida a planos\nprofundos e sem alterações cutâneas adjacentes, localizada no quadrante superior externo da\nmama esquerda; não são detectadas linfonodomegalias axilares ou supraclaviculares ipsilaterais.\n\nConsiderando a hipótese diagnóstica principal de neoplasia maligna de mama, seus fatores de risco\nrelacionados e sua rotina de investigação diagnóstica, assinale a alternativa correta.","options":{"A":"O histórico de menarca tardia, menopausa precoce e gestações múltiplas são fatores de risco\nreconhecidos.","B":"Diferentemente da terapia de contracepção conjugada (estrógeno e progestágeno), a TRH não é\nfator de risco para a doença.","C":"Na idade da paciente, a realização de ressonância magnética local não aumenta a\nespecificidade das informações obtidas com a mamografia.","D":"A chance de a paciente apresentar mutação hereditária no gene BRCA1 é alta, particularmente\nse seu tumor coexpressar receptores de\nestrogênio, progestágeno e HER2."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-291525","number":"291525","sourceNumber":"291525","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Em uma equipe de Saúde da Família, foi levantada a necessidade de realizar ações de\npromoção da saúde para o controle do câncer de mama. Segundo o Instituto Nacional do Câncer\n(INCA), que ações intersetoriais e práticas preventivas seriam mais eficazes para esse fim?","options":{"A":"Manutenção do peso corporal e a prática regular de atividade física.","B":"Controle de pressão arterial e diabetes.","C":"Incentivo a realizar autoexame de mamas.","D":"Incentivo à coleta de citologia oncótica periodicamente."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-263405","number":"263405","sourceNumber":"263405","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma mulher com 42 anos de idade, com ciclos menstruais regulares, comparece ao\nambulatório de ginecologia por apresentar um laudo de exame de ultrassonografia transvaginal\nevidenciando cisto ovariano de paredes finas, com contornos regulares, conteúdo anecóico,\nmedindo 4 cm em seu maior diâmetro. A paciente nega sintomas. Diante desse quadro, a principal\nhipótese diagnóstica e o exame complementar que auxiliaria no esclarecimento dessa hipótese são,\nrespectivamente,","options":{"A":"cisto hemorrágico, com dosagem de antígeno carcino-embrionário.","B":"cisto folicular, sem necessidade de exame adicional.","C":"teratoma, com dosagem de alfa-feto proteína.","D":"endometrioma, com dosagem de CA-125."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-274668","number":"274668","sourceNumber":"274668","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente, 53 anos, com massa mamária palpada de 1,5 cm, sem qualquer alteração\ncutânea associada nem presença de adenopatia, apresentando exames de mamografia e\nultrassonografia normais. Quanto à biópsia do nódulo, no caso apresentado:","options":{"A":"Sempre deve ser realizada por aspiração por agulha fina, por ser capaz de diferenciar o\ncarcinoma ductal in situ do invasor.","B":"Se sugerir câncer, diante de resultado negativo do exame clínico e de imagem, não será\nnecessária a excisão do nódulo para avaliar malignidade.","C":"Será dispensada, pois a imagem normal da massa mamária palpável exclui câncer.","D":"A abordagem comum é biópsia central por agulha com base na palpação."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-263420","number":"263420","sourceNumber":"263420","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma mulher com 25 anos de idade é atendida na Unidade Básica de Saúde após\npalpar um nódulo em sua mama direita. Na\navaliação médica, identifica-se um nódulo de 1 cm, no\nmaior diâmetro, móvel, com consistência fibroelástica, regular e indolor. Nesse caso, qual deve ser\na conduta médica inicial?","options":{"A":"Punção e citologia.","B":"Exérese do nódulo.","C":"Seguimento ecográfico.","D":"Encaminhamento ao Centro de Oncologia."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-230595","number":"230595","sourceNumber":"230595","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"O câncer de mama resulta do crescimento desordenado de células com potencial\ninvasivo, que se dá a partir de alterações\ngenéticas (hereditárias ou adquiridas). Sobre o câncer de\nmama, assinale a CORRETA:","options":{"A":"o tipo mais prevalente é o sarcoma lobular, que tem origem nos lóbulos mamários.","B":"o tipo mais prevalente é o carcinoma ductal, que tem origem nos ductos mamários e\ncorresponde a cerca de 80% dos casos.","C":"o tipo mais frequente é o carcinoma lobular, que tem origem nos lóbulos mamários e\ncorresponde a cerca de 80% dos casos.","D":"o tipo mais frequente é o carcinoma lobular, que tem origem na transição ducto-lobular, e\ncorresponde a mais de 95% dos casos."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-230606","number":"230606","sourceNumber":"230606","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"O método com MAIOR sensibilidade para diagnóstico de neoplasia mamária é:","options":{"A":"Tomossíntese.","B":"Mamografia.","C":"Ressonância Magnética.","D":"Ultrassom de mamas."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-206091","number":"206091","sourceNumber":"206091","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Em relação ao abscesso periareolar recidivante, marque a alternativa INCORRETA.","options":{"A":"Tem relação com o tabagismo.","B":"A inversão mamilar pode ser causa.","C":"Está relacionado com a obstrução dos ductos lactíferos.","D":"O tratamento definitivo é clínico, com antibióticos e anti-inflamatórios."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-212022","number":"212022","sourceNumber":"212022","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Julgue o item, relativo à oncologia ginecológica. O objetivo do sistema BIRADS (Breast\nImaging Reporting and Data System) é padronizar os laudos mamográficos - incluindo\nultrassonografia mamária e ressonância magnética das mamas -, levando-se em conta a evolução\ndiagnóstica, a recomendação da conduta, a história clínica e o exame físico das pacientes.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-212091","number":"212091","sourceNumber":"212091","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"A respeito do rastreio do câncer de mama, julgue o item que se segue, conforme as\norientações do Ministério da Saúde. Recomenda-se o rastreamento mamográfico a cada dois anos,\npara todas as mulheres, a partir dos quarenta anos de idade.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-212055","number":"212055","sourceNumber":"212055","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"A respeito do rastreio do câncer de mama, julgue o item que se segue, conforme as\norientações do Ministério da Saúde. As mulheres com risco elevado de câncer de mama devem\nrealizar mamografia anual a partir dos trinta e cinco anos de idade.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-183863","number":"183863","sourceNumber":"183863","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Com relação às afecções oncológicas, julgue o item subsecutivo. Em mulheres, o\ncâncer de mama se localiza com maior frequência no quadrante superointerno.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-183922","number":"183922","sourceNumber":"183922","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Os fatores de risco familiares/genéticos/hereditários para o desenvolvimento de câncer\nde mama em uma mulher de cinquenta e cinco\nanos de idade incluem a presença de parentes com\ndiagnóstico de síndrome de câncer de ovário e de mama, com mutação nos genes BRCA1 e\nBRCA2.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-183857","number":"183857","sourceNumber":"183857","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Os fatores de risco familiares/genéticos/hereditários para o desenvolvimento de câncer\nde mama em uma mulher de cinquenta e cinco\nanos de idade incluem a presença de duas ou mais\nparentes consaguíneas de primeiro grau com câncer de mama.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-183917","number":"183917","sourceNumber":"183917","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Julgue o item subsecutivo, acerca das doenças oncológicas. Além de ofeecer uma\nalimentação saudável para o bebê, o aleitamento materno protege a mãe contra o câncer de\nmama.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-168521","number":"168521","sourceNumber":"168521","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma mulher de 45 anos de idade comparece ao ambulatório de Ginecologia com\nqueixas de aumento do volume abdominal e\nirregularidade menstrual. Realiza ultrassonografia\ntransvaginal que evidencia, no ovário direito, imagem anecoica, arredondada, com paredes finas,\ncontornos regulares, limites bem definidos e com septações grosseiras em seu interior, medindo 14\nx 12 cm em seus maiores diâmetros. Nesse caso, a conduta adequada é","options":{"A":"iniciar tratamento clínico com anticoncepcional combinado e controle trimestral com\nultrassonografia.","B":"realizar marcadores tumorais e proceder a laparotomia com exame de congelação no\nintraoperatório.","C":"acompanhar de forma expectante e reavaliar resultado de ultrassonografia após 2 meses.","D":"realizar punção e drenagem do cisto, guiadas por ultrassonografia."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-157994","number":"157994","sourceNumber":"157994","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente de 45 anos de idade realizou mamografia bilateral com a seguinte conclusão\ndo laudo: \"birads 0\". Não possui antecedentes de\ncâncer na família. Nega nódulos palpáveis ou\noutras queixas. Refere ciclos menstruais regulares. Utiliza como método anticoncepcional DIU de\ncobre há oito anos. Nega uso de medicações e cirurgias prévias. Exame físico sem alterações.\n\nCom base no caso clínico apresentado, em relação ao seguimento dessa paciente, assinale a\nalternativa CORRETA.","options":{"A":"A mamografia deve ser repetida em seis meses.","B":"A avaliação deve ser complementada com outro método de imagem, como a ultrassonografia\nmamária.","C":"Não há necessidade de novos exames nesse momento. Deve-se seguir rotina para baixo risco.","D":"Repetir a mamografia com magnificação da imagem.","E":"Deve-se fazer PAAF de amostragem."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-154508","number":"154508","sourceNumber":"154508","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Mulher de 53 anos, menopausada, vem à consulta queixando-se de aumento do\nvolume abdominal. Ao exame: tumor palpável em hipocôndrio direito. CA-125 elevado.\n\nUltrassonografia pélvica revela cisto ovariano com paredes espessadas medindo 95 mm. Acerca do\ncâncer de ovário é CORRETO afirmar que:","options":{"A":"No caso acima é indicada a realização de biópsia e tomografia computadorizada para\nestadiamento da lesão, permitindo definição da melhor abordagem terapêutica.","B":"É provável que o tumor deste caso tenha se originado de células estromais.","C":"Nuliparidade, obesidade, terapia de reposição hormonal, uso de contraceptivos orais e história\nfamiliar constituem fatores de risco para câncer de ovário.","D":"O tumor maligno de células germinativas de ovário mais comum em crianças e adolescentes é o\ndisgerminoma.","E":"O Struma Ovarii é um tumor ovariano que frequentemente sofre transformação maligna."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-159501","number":"159501","sourceNumber":"159501","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Acerca da assistência às neoplasias ginecológicas, julgue o item a seguir. Em pacientes\ncom tumores recidivantes de ovário que já\npassaram por quimioterapia, a realização de radioterapia\npromove melhora na qualidade de vida, embora não exerça influência na sobrevida.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-159509","number":"159509","sourceNumber":"159509","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Acerca da assistência às neoplasias ginecológicas, julgue o item a seguir. A biópsia do\nlinfonodo sentinela reduz significativamente a morbidade cirúrgica da linfadenectomia, já que reduz\no linfedema, que consiste na principal complicação da cirurgia axilar em pacientes com câncer de\nmama.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-168482","number":"168482","sourceNumber":"168482","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma mulher com 52 anos de idade, Gesta 3 Para 2 Aborto 1, foi encaminhada ao\nambulatório de mastologia para avaliação. A paciente não apresentava queixas mamárias e não\npossuia história familiar de câncer. Ao exame físico, não foram encontradas alterações na mama\ndireita da paciente e, na mama esquerda, foi identificado espessamento sem nódulos palpáveis. O\nresultado da mamografia de rotina, realizada recentemente pela paciente, é de BIRADS 3. Diante\ndesse quadro clínico, a conduta indicada é","options":{"A":"informar que o resultado do exame é provavelmente benigno e que o acompanhamento pode\ncontinuar a ser feito no serviço de atenção primária, com repetição da mamografia em 6 meses.","B":"informar que o resultado do exame é normal e que o atendimento pode continuar a ser feito no\nserviço de atenção primária, com avaliação clínica anual e repetição da mamografia em 2 anos.","C":"informar que o resultado do exame é inconclusivo e solicitar a realização de ultrassonogradia\nmamária complementar, mantendo o acompanhamento no serviço\nde atenção secundária.","D":"informar que o resultado do exame é sugestivo de malignidade e indicar biópsia mamária\nimediata no serviço de atenção secundária."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-133997","number":"133997","sourceNumber":"133997","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Com relação à anatomia do aparelho reprodutor feminino é correto afirmar que a artéria\novariana é um ramo direto da","options":{"A":"Artéria ilíaca interna.","B":"Aorta.","C":"Artéria uterina.","D":"Artéria mesentérica inferior.","E":"Artéria ilíaca externa."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-129031","number":"129031","sourceNumber":"129031","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"O câncer de mama é provavelmente o mais temido pelas mulheres devido à alta\nfrequência e, sobretudo, aos efeitos psicológicos, que afetam a percepção da sexualidade e a\nimagem pessoal. Além da hereditariedade, é(são) considerado(s) como fator(es) de risco a","options":{"A":"Menopausa e a menarca precoce.","B":"Presença de fibroadenomas no exame de mamografia.","C":"Ocorrência da primeira gravidez após os 35 anos de idade.","D":"Multiparidade.","E":"Presença de múltiplas calcificações secretórias ou lesões que contenham gordura (cistos\noleosos, lipomas, galactoceles, densidade mista e hamartoma) no exame de mamografia."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-104769","number":"104769","sourceNumber":"104769","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma paciente de 72 anos de idade foi submetida à mastectomia radical modificada\npara tratamento de câncer de mama e o\ndiagnóstico anatomopatológico foi de um carcinoma ductal\ninvasivo grau 1 medindo 0,8 cm no maior eixo microscópico, imuno-histoquímica com receptores de\nestrogênio e progesterona positivos (100% e 95% respectivamente), HER-2 negativo, pele e\ncomplexo aréolo-papilar livres de neoplasia, 21 linfonodos axilares examinados e nenhum\ncomprometido. Estádio patológico pT1pN0. Exames complementares descartaram doença a\ndistância. Com relação a esse caso hipotético, na adjuvância, indica(m) -se:","options":{"A":"Apenas hormonioterapia.","B":"Apenas quimioterapia","C":"Apenas radioterapia.","D":"Hormônio e quimioterapia.","E":"Hormônio e radioterapia."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-111305","number":"111305","sourceNumber":"111305","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Do ponto de vista de saúde pública, a realização de mutirões de mamografia significa:","options":{"A":"Uma ação desnecessária, pois a maioria dos exames realizados seguramente será normal.","B":"Supre uma falha do modelo de assistência à saúde no município, que deveria incluir este\nexame, junto com ações educativas, como rotinas.","C":"É imprescindível, pois tem ótima relação custo-benefício e aprimora a estatística e a avaliação\nda Saúde da Mulher no município.","D":"É interessante pela mobilização e conscientização,\n\nmas não tem eficácia por ser específico a casos avançados.","E":"Uma ação importante pela especificidade do exame, permitindo o controle da doença."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-75510","number":"75510","sourceNumber":"75510","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Mulher com 25 anos de idade, nuligesta, procura o Ambulatório de Mastologia relatando\nter notado a presença de nódulo na mama\nesquerda há dois meses. Faz uso de anticoncepcional\ncombinado oral. Nega história familiar de câncer de mama. Ao exame, palpa-se nódulo de\nconsistência fibroelástica, de contornos regulares, móvel, indolor, medindo cerca de 3,0 cm, em\nquadrante superoexterno da mama esquerda. A conduta imediata indicada é:","options":{"A":"Solicitar mamografia.","B":"Realizar exérese do nódulo.","C":"Realizar controle clínico a cada seis meses.","D":"Solicitar mamografia e ultrassonografia mamária.","E":"Realizar Punção Aspirativa com Agulha Fina (PAAF)."},"answer":"E","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-137546","number":"137546","sourceNumber":"137546","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma mulher de 30 anos de idade, secundípara, procura atendimento médico na\nUnidade de Saúde da Família, referindo que,\nhá mais ou menos três meses, notou a presença de\num nódulo na mama direita. Nega aumento do volume do nódulo, alterações na cor e textura da\npele das mamas ou descarga mamilar. Está em uso de anticoncepcional hormonal oral combinado\nhá 6 anos. A avó materna teve câncer de mama aos 60 anos de idade. Ao exame, observa-se\nnódulo indolor, com 2,0 cm de diâmetro, bem delimitado, consistência fibroelástica, móvel, no\nquadrante superior externo da mama direita. Nota-se a ausência de linfonodos palpáveis em axilas\ne expressão mamária negativa bilateralmente. Diante desse quadro, qual a conduta mais\nadequada a ser adotada pelo médico?","options":{"A":"Solicitar mamografia.","B":"Solicitar mamografia e ultrassonografia de mamas.","C":"Referenciar a paciente ao serviço de saúde especializado.","D":"Orientar a paciente a retornar em 6 meses para repetir o\nexame clínico das mamas.","E":"Orientar a paciente a retornar em 12 meses para repetir o\nexame clínico das mamas."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-138396","number":"138396","sourceNumber":"138396","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Ao atender uma mulher, com 24 anos de idade, você observa grande resistência dela\npara continuar o aleitamento materno de seu filho de dois meses. Além dos inquestionáveis\nbenefícios para a criança, você orienta a paciente sobre os benefícios que o aleitamento materno\ntraz para a mulher que amamenta, entre os quais figuram, a proteção contra o câncer de mama e\ncontra","options":{"A":"o câncer de colo uterino.","B":"o câncer de endométrio.","C":"os tumores da vulva.","D":"o desenvolvimento de miomas.","E":"o câncer de ovário."},"answer":"E","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-138397","number":"138397","sourceNumber":"138397","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Mulher com 45 anos de idade, cor branca, multípara, proveniente de zona rural, procura\nconsulta ginecológica com queixa de peso na região pélvica há cerca de 60 dias, perda de peso\ncorporal e distensão abdominal. A paciente não faz uso de método contraceptivo oral e não\napresenta dismenorreia. A paciente tem antecedente de neoplasia maligna de mama e a mãe,\nhistória de câncer de ovário. Ao exame, observou-se massa palpável em anexo esquerdo. De\nacordo com o exame clínico e com os antecedentes pessoais e familiares informados pela paciente,\nqual a principal hipótese diagnóstica?","options":{"A":"Cisto benigno de ovário.","B":"Neoplasia maligna de ovário.","C":"Endometrioma.","D":"Tuberculose genital (ovário e trompa).","E":"Abscesso ovariano."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-31025","number":"31025","sourceNumber":"31025","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Com referência a doenças benignas e malignas do trato genital feminino e mamário,\njulgue o item a seguir. Considere a\nseguinte situação hipotética. Uma paciente gestante, no\nprimeiro trimestre de gestação, foi submetida à laparotomia explorada por dor abdominal intensa.\nEncontrou-se tumoração anexial direita de 10 cm de diâmetro com cápsula bosselada e\nconsistência esponjosa. Histologicamente observou-se proliferação anormal das células\ngerminativas básicas. Nesse caso clínico, o diagnóstico histopatológico mais provável é\ndisgerminoma.","options":{"A":"Certo.","B":"Errado."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-4-138728","number":"138728","sourceNumber":"138728","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente, com 35 anos de idade, nuligesta, procura médico para realizar exames de\nmama. Relata ter muito medo, pois sua mãe teve câncer de mama bilateral, diagnosticado aos 49\nanos. O exame clínico das mamas é normal, bem como o restante do exame físico da paciente.\n\nQual a conduta a ser adotada pelo médico no rastreamento do câncer de mama para esta\npaciente?","options":{"A":"Autoexame de mamas mensal e exame clínico anual.","B":"Exame clínico e mamografia anuais.","C":"Exame clínico, mamografia e ultrassonografia\nmamária anuais.","D":"Exame clínico e mamografia a cada dois anos.","E":"Exame clínico anual e ressonância magnética de\nmamas a cada dois anos."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-346843","number":"346843","sourceNumber":"346843","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Em relação ao fibroadenoma da mama, assinale a afirmativa INCORRETA:","options":{"A":"É o tumor benigno mais frequente da mama da mulher.","B":"É rara sua associação com malignidade.","C":"É um tumor exclusivamente glandular.","D":"É mais comum no menacme."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-335088","number":"335088","sourceNumber":"335088","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"O câncer de mama é o que mais acomete mulheres em todo o mundo, constituindo a\nmaior causa de morte por câncer nos países em desenvolvimento. Com relação ao rastreamento do\ncâncer de colo de mama, segundo o Ministério da Saúde do Brasil (2016), assinale a alternativa\ncorreta.","options":{"A":"A estratégia preconizada para o rastreamento de câncer de mama é a mamografia a cada dois\nanos para mulheres entre 50 e 69 anos de idade.","B":"O autoexame tem grande benefício para a detecção precoce de tumores e traz segurança,\nreduzindo o excesso de exames invasivos.","C":"O exame clínico das mamas tem benefício bem estabelecido, como o rastreamento do câncer de\nmama.","D":"O modelo de rastreamento oportunístico apresenta melhores resultados e menores custos do\nque o modelo organizado."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-334743","number":"334743","sourceNumber":"334743","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Sobre o câncer de mama assinale a alternativa incorreta.","options":{"A":"Mulheres com uma mutação BRCA 1 têm um risco absoluto de quase 60% de desenvolver\ncâncer de mama até os 70 anos de idade.","B":"A mortalidade por câncer de mama caiu drasticamente desde a década de 1980, e tanto a\ndetecção precoce por meio de triagem quanto as\nmelhorias no tratamento do câncer de mama são\nresponsáveis por essa redução na mortalidade.","C":"A ressonância magnética, quando disponível, é preferível à mamografia no diagnóstico do\ncâncer de mama.","D":"A sensibilidade e especificidade da mamografia são dependentes da idade, sendo maior em\nmulheres mais velhas do que em mulheres mais jovens."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-337651","number":"337651","sourceNumber":"337651","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"A dor mamária é causa frequente de consulta ao mastologista, podendo interferir\ndiretamente na vida emocional, profissional e\nsocial da paciente. Essa entidade é classificada como\nmastalgia cíclica, mastalgia acíclica e mastalgia extramamária. São causas de mastalgia de origem\nextramamária, EXCETO:","options":{"A":"Trauma mamário local e hipertrofia gestacional.","B":"Radiculopatia cervical e bursite.","C":"Síndrome de Tietze e herpes-zoster.","D":"Úlcera péptica e pericardite."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-337652","number":"337652","sourceNumber":"337652","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Mulher com 41 anos, G4 P3C A0 (3 filhos vivos), casada, gravidez planejada, 28\nsemanas (DUM = 1o US), sem comorbidades,\npré-natal sem intercorrências até o momento.\nTabagista de 20 cigarros por dia. Na consulta de hoje, sem queixas e manifesta desejo em colocar\nDIU no pós-parto imediato ou fazer a salpingotripsia. Dentre as complicações da salpingectomia\nestá o desenvolvimento de irregularidade menstrual ou mesmo falência ovariana precoce. Uma\npossibilidade é a lesão inadvertida nas artérias que suprem os ovários. É CORRETO afirmar que as\nartérias responsáveis pelo suprimento sanguíneo arterial dos ovários são:","options":{"A":"Artérias tubovarianas bilateralmente.","B":"Artérias uterinas bilateralmente.","C":"Artérias ovarianas e ramos ovarianos das artérias uterinas bilateralmente.","D":"Artérias ovarianas bilateralmente."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-336297","number":"336297","sourceNumber":"336297","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Mulher, 27 anos, procura seu ginecologista preocupada pois sua avó materna morreu\nem decorrência de câncer de ovário. Devido essa\nsituação, qual seria o fator que poderia ser\nreferido a paciente como protetor para esse desfecho?","options":{"A":"Uso de preservativos.","B":"Uso de contraceptivos anovulatórios.","C":"Uso de drogas indutoras de ovulação.","D":"Uso de anti-inflamatórios não esteroides."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-291925","number":"291925","sourceNumber":"291925","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Em relação a anatomia e o desenvolvimento das mamas, é CORRETO afirmar que:","options":{"A":"Durante a 5ª semana de desenvolvimento fetal, o ectoderma primitivo desenvolve a ?linha\nláctea? que vai da axila até a região inguinal, bilateralmente.","B":"Durante o 3º trimestre de gestação, os hormônios sexuais placentários, induzem a formação dos\nácinos rudimentares.","C":"Entre a 28ª e 32ª semana de gravidez, inicia- se o processo de diferenciação parenquimatosa\ncom o desenvolvimento da estrutura\nlobuloalveolar que nesse momento já contêm colostro.","D":"A mais frequente anormalidade de desenvolvimento mamário observada em ambos os sexos é a\npresença de polimastia."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-291927","number":"291927","sourceNumber":"291927","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Em relação aos fibroadenomas, assinale a alternativa INCORRETA:","options":{"A":"Os fibroadenomas simples são tumores sólidos benignos contendo tecido glandular e fibroso.\n\nEm 20% dos casos, múltiplos fibroadenomas ocorrem na mesma mama ou bilateralmente.","B":"A etiologia dos fibroadenomas não é conhecida, mas uma relação hormonal é provável, uma vez\nque eles persistem durante os anos\nreprodutivos, podem aumentar de tamanho durante a gravidez\nou com a terapia estrogênica, e geralmente regridem após a menopausa.","C":"Os fibroadenomas são mais frequentes em mulheres na faixa etária entre 15 e 35 anos.\n\nNaqueles comprovados por biópsia a exérese é fundamental para avaliação do risco de\ntransformação malígna.","D":"O risco de câncer de mama subsequente é ligeiramente elevado apenas se o fibroadenoma for\ncomplexo, se houver doença proliferativa adjacente ou história familiar de câncer de mama."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-291932","number":"291932","sourceNumber":"291932","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Em relação ao desenvolvimento normal das mamas, assinale a alternativa CORRETA:","options":{"A":"A puberdade tem início entre os 10 e 12 anos como resultado da influência dos hormônios\nhipotalâmicos (prolactina e cortisol), secretados no portal hipotalâmico-pituitário.","B":"Na fase IV do desenvolvimento mamário pode-se observar o aumento da aréola e a sua\npigmentação.","C":"Na mulher adulta o limite superior, inferior, medial e lateral são respectivamente a borda medial\ndo esterno, 4ª costela, linha axilar média e\nborda inferior da clavícula.","D":"O principal suprimento arterial da mama é fornecido pelos ramos da artéria mamária lateral\n(ramos do 3º, 4º e 5º arcos costais)."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-305017","number":"305017","sourceNumber":"305017","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Considere que uma paciente de 56 anos de idade, G3 P3 A0 , comparece à consulta\ntrazendo resultado de mamografia categoria 3\nBI-RADS®, realizada há cerca de um mês. O exame\nclínico das mamas não apresentou alterações. Com relação à conduta a ser adotada,\n\nrecomenda-se:","options":{"A":"Correlacionar esse resultado a outros métodos de imagem, conforme recomendação do médico\nradiologista.","B":"Encaminhar essa paciente, imediatamente, para a unidade de referência secundária para\ninvestigação histopatológica.","C":"Realizar controle radiológico por três anos, com repetição do exame a cada seis meses no\nprimeiro ano e anual nos dois anos seguintes.\nConfirmando estabilidade da lesão, volta-se à rotina.","D":"Realizar biópsia, já que a maioria desses casos são malignos, além de avaliar risco genético\n(BRCA1 e BRCA2)."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-306724","number":"306724","sourceNumber":"306724","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"O câncer de mama é o segundo tipo de câncer que mais acomete brasileiras,\nrepresentando em torno de 25% de todos os\ncânceres que afetam o sexo feminino. Para o Brasil,\nforam estimados 59.700 casos novos de câncer de mama em 2019, com risco estimado de 56\ncasos a cada 100 mil mulheres (INCA, 2019). Segundo o Instituto Nacional de Câncer (INCA),\navalie as informações e assinale a alternativa correta: I- A terapia de reposição hormonal, quando\nindicada, deve ser feita com rigoroso controle médico e por no mínimo cinco anos. II- Está indicado\nrealizar os testes genéticos BRCA 1 e BRCA 2 em pessoas que tenham um parente de primeiro\ngrau com câncer de mama. III- O uso de contraceptivos orais combinados é considerado como um\nfator de risco pela Agência Internacional de Pesquisa em Câncer da Organização Mundial da\nSaúde, embora estudos sobre o tema tenham resultados controversos. IV- Alguns fatores\ncomportamentais ajudam a diminuir o risco de câncer de mama. Para câncer de mama na\n\npré-menopausa, somente a atividade física de intensidade vigorosa (nadar, correr, ciclismo etc.)\ndemonstrou um provável efeito protetor no risco da doença.","options":{"A":"As afirmações corretas são III e IV.","B":"As afirmações corretas são II e IV.","C":"As afirmações corretas são II, III e IV.","D":"As afirmações corretas são I e III."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-314065","number":"314065","sourceNumber":"314065","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Em relação às mastopatias, analisar os itens abaixo: I. A dor mamária não é uma\napresentação comum de câncer de mama. II. No\npapiloma intraductal, ocorre um crescimento\ntumoral benigno par ao interior de um ducto mamário. III. Uso de verapamil pode estar associado a\ndesenvolvimento de galactorreia. Está(ão) CORRETO(S):","options":{"A":"Somente o item I.","B":"Somente o item II.","C":"Somente os itens I e II.","D":"Somente os itens I e III.","E":"Todos os itens."},"answer":"E","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-260680","number":"260680","sourceNumber":"260680","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente de 51 anos comparece à unidade de saúde para realizar prevenção\nginecológica e a equipe de saúde solicita uma\nmamografia. Após 30 dias a paciente retorna à\nunidade com o resultado do exame: BI-RADS 0 (ZERO). Com esse resultado, a equipe de saúde\ndeve:","options":{"A":"solicitar que a paciente repita a mamografia em 6 meses.","B":"orientar a paciente a realizar nova mamografia em 1 ano.","C":"orientar a paciente a realizar nova mamografia em 2 anos.","D":"encaminhar a paciente para realizar investigação histológica do achado.","E":"solicitar complementação da mamografia com outro exame de imagem (Ultrassonografia das\nmamas por exemplo)."},"answer":"E","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-287342","number":"287342","sourceNumber":"287342","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente de 42 anos, feminina, procura a Unidade Básica de Saúde, queixando-se de\nsaída de secreção em mamilo. Afirma que não está grávida. Ao realizar o exame físico, qual\nalteração do fluxo papilar seria mais sugestiva de natureza neoplásica?","options":{"A":"Espontâneo, bilateral e acinzentado.","B":"Não espontâneo e unilateral.","C":"Espontâneo, unilateral e hemorrágico.","D":"Não espontâneo e bilateral."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-283917","number":"283917","sourceNumber":"283917","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Em relação aos cistos ovarianos benignos, analise as assertivas abaixo: I. Os cistos\nfuncionais do ovário são comuns no menacme e têm sua prevalência aumentada na paciente\nusuária de DIU hormonal. II. O cisto de corpo lúteo hemorrágico deve ser abordado cirurgicamente,\npois provoca peritonismo e dor. III. Teratomas maduros e endometriomas podem sofrer\ntransformação maligna. Quais estão corretas?","options":{"A":"Apenas I.","B":"Apenas II.","C":"Apenas III.","D":"Apenas I e III.","E":"I, II e III."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-287888","number":"287888","sourceNumber":"287888","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Conforme DUNCAN, et al., o câncer de ovário é a mais letal das doenças malignas\nginecológicas. Em relação a essa doença,\nanalisar os itens abaixo: I. O tipo epitelial, o mais\nfrequente, é assintomático nas fases iniciais, e dois terços dos casos são diagnosticados em\nestádio avançado. II. As neoplasias primárias de ovário são de três tipos: epitelial, do estroma e\nde\ncélulas germinativas. III. As neoplasias de células germinativas são importantes devido a sua pouca\nagressividade e às altas taxas de cura com cirurgia e quimioterapia sistêmica combinada. Está(ão)\nCORRETO(S):","options":{"A":"Somente o item I.","B":"Somente o item II.","C":"Somente os itens I e III.","D":"Somente os itens II e III.","E":"Todos os itens."},"answer":"E","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-287895","number":"287895","sourceNumber":"287895","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Assinalar a alternativa que preenche a lacuna abaixo CORRETAMENTE: Os cistos\n\nsão as massas anexiais císticas mais comuns.","options":{"A":"paraovarianos","B":"funcionais","C":"de inclusão peritoneal","D":"de inclusão mesotelial","E":"paramesonéfricos"},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-246722","number":"246722","sourceNumber":"246722","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Entre as mulheres brasileiras, dentre as neoplasias malignas abaixo, a mais comum é:","options":{"A":"Mama","B":"Colo de útero","C":"Ovário","D":"Intestino","E":"Estômago"},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-227086","number":"227086","sourceNumber":"227086","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"O rastreio do câncer de mama é estratégia eficaz na redução da mortalidade por essa\ndoença. São diretrizes atuais, segundo o Ministério da Saúde, para o rastreio de câncer de mama,\nEXCETO:","options":{"A":"Início do rastreio aos 50 anos para pacientes consideradas de risco habitual.","B":"Periodicidade de exames a cada 2 anos em pacientes sem resultados anteriores suspeitos.","C":"Complementação com ultrassonografia para pacientes que apresentam mamografia classificada\ncomo BI-RADS 3.","D":"Indicação de estudo histológico para pacientes com mamografia classificada como BI-RADS 4."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-234419","number":"234419","sourceNumber":"234419","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Em relação aos tumores benignos da mama, assinale a alternativa INCORRETA:","options":{"A":"Os cistossarcomas filoides são tumores raramente bilaterais, difíceis de distinção clínica com os\nfibroadenomas e apresentam crescimento rápido","B":"O tratamento cirúrgico do cistossarcoma filoide é a excisão local ampla porém, em mamas\npequenas poderá exigir a mastectomia simples com\nbiópsia do linfonodo sentinela.","C":"Os fibroadenomas ocorrem em mulheres jovens (20-35 anos), podendo ocorrer também em\nadolescentes.","D":"Os fibroadenomas podem ser únicos ou múltiplos, lisos ou lobulados, pequenos ou muito\ngrandes, quando são denominados fibroadenomas gigantes."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-227089","number":"227089","sourceNumber":"227089","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente de 32 anos comparece preocupada à consulta com ginecologista por ter\npalpado um nódulo não doloroso em sua mama\ndireita. Não apresenta outras queixas e\ndesconhece familiares com histórico de câncer de mama. Ao exame físico, pode-se palpar nódulo\nem quadrante súperolateral da mama direita, sem retrações ou abaulamentos e sem evidências de\nadesão à planos profundos. Em seu maior diâmetro, mede aproximadamente 2cm. Considerando o\ncaso descrito, assinale a alternativa que apresenta a MELHOR CONDUTA a ser adotada para essa\npaciente.","options":{"A":"A mamografia deve ser solicitada dada alta probabilidade de etiologia maligna considerando o\nquadrante em que se encontra a lesão.","B":"O estudo histológico deve ser realizado para exclusão de malignidade.","C":"A punção por agulha fina pode ser indicada para avaliação inicial da lesão e confirmação da\netiologia maligna.","D":"A paciente deve manter acompanhamento clínico e propedêutico, mas pode ser orientada, de\nque provavelmente, trata-se de uma lesão benigna."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-227262","number":"227262","sourceNumber":"227262","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente de 26 anos com exame ultrassonográfico da pelve mostrando tumor de 05 cm,\nsólido-cístico, com áreas de calcificação, comprometendo o ovário direito e que se encontra\nlocalizado anteriormente ao útero. A principal hipótese diagnóstica é:","options":{"A":"Disgerminoma.","B":"Coriocarcinoma.","C":"Fibroma.","D":"Teratoma."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-243007","number":"243007","sourceNumber":"243007","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma paciente de 35 anos de idade procurou o consultório médico, onde realizou\nultrassonografia de mama que mostrou nódulo\nem mama esquerda irregular, com orientação\nvertical, margens não circunscritas e presença de sombra acústica posterior com 35 x 55 x 40 mm.\nAssinale a alternativa CORRETA quanto à conduta a ser adotada.","options":{"A":"deve?se realizar biópsia por agulha grossa.","B":"deve?se repetir a ultrassonografia em três meses.","C":"deve?se repetir a ultrassonografia em um ano.","D":"deve?se acalmar a paciente, pois a imagem indica suspeita de fibroadenoma.","E":"devido ao tamanho do nódulo, a punção por agulha fina é a mais recomendada."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-243016","number":"243016","sourceNumber":"243016","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"O câncer de ovário geralmente não tem sintomas nos estágios iniciais. Devido a isso é\nimportante o conhecimento dos fatores de risco associados, são eles, EXCETO:","options":{"A":"Obesidade.","B":"História de câncer de ovário em familiar de 1° grau.","C":"Nuliparidade.","D":"Infertilidade.","E":"Contraceptivos orais."},"answer":"E","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-243020","number":"243020","sourceNumber":"243020","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"O câncer de mama é o tipo de câncer mais comum entre as mulheres no mundo e no\nBrasil. Em se tratando de câncer de mama e seu rastreio, a FEBRASGO, classifica algumas\ncaracterísticas dos nódulos, como suspeitas, devendo-se prosseguir com avaliação histológica.\n\nDentre as características malignas dos nódulos, qual a INCORRETA:","options":{"A":"nódulo sólido, irregular, mal definido.","B":"nódulo com margens indistintas.","C":"nódulo sólido, impalpável, totalmente circunscrito.","D":"nódulo espiculado, irregular.","E":"nódulo de alta densidade na mamografia"},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-246387","number":"246387","sourceNumber":"246387","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Quanto a dor mamária: I) Ocorre ao redor do órgão e irradia-se para a escápula pelos\nnervos intercostais. II) Pode irradiar-se para a face medial do braço, pelo nervo\nintercostobraquial.\n\nIII) Pode irradiar-se para o pescoço e escápila, através do nervo supraclavicular.","options":{"A":"Apenas I correta.","B":"I e III corretas.","C":"I e II corretas.","D":"I, II e II corretas."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-246765","number":"246765","sourceNumber":"246765","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Duas pacientes, mãe e filha, procuraram o serviço de ginecologia. Ambas com queixas\nmamárias. A filha de 22 anos, apresentando nódulo de 2,3 cm, cístico em ultrassonografia recente,\nno QSE da mama direita, móvel, sem descarga papilar, axilas livres, e ela refere mastalgia\nimportante. A mãe, com 40 anos, apresentando tumoração no QII da mama esquerda, de 3,5\ncentímetros, móvel, sólida em ultrassonografia recente. Qual a conduta na filha e na mãe?","options":{"A":"Punção aspirativa com agulha fina em ambas.","B":"Exérese da tumoração em ambas, com margem de segurança.","C":"Acompanhamento com mamografia em ambas as pacientes a cada 06 meses.","D":"Acompanhar com ultrassonografia mamária em ambas a cada 06 meses.","E":"Nenhuma das alternativas anteriores é correta."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-243058","number":"243058","sourceNumber":"243058","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Qual a melhor conduta diante de uma paciente portadora de câncer de mama, subtipo\nhistológico Ductal infiltrante, estádio clinico T4N1M0, padrão imunohistoquímico sem receptor\nhormonal para estrogênio e progesterona e sem expressão do marcador transmembrana HER2\n(tripo negativo):","options":{"A":"quimioterapia neoadjuvante seguido de cirurgia.","B":"tamoxifeno seguido de cirurgia.","C":"anastrozol seguido de cirurgia.","D":"radioterapia neoadjuvante seguido de cirurgia.","E":"cirurgia apenas."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-202771","number":"202771","sourceNumber":"202771","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente de 54 anos, comparece para atendimento médico trazendo resultado de\nmamografia BIRADS 5. A conduta subsequente a este resultado é:","options":{"A":"investigação histopatológica da lesão evidenciada.","B":"repetir mamografia em 6 meses.","C":"repetir mamografia em 1 ano.","D":"repetir mamografia em 2 anos.","E":"complementar a mamografia com ultrassonografia das mamas."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-196791","number":"196791","sourceNumber":"196791","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"O que caracteriza um tumor ?Boderline? de ovário:","options":{"A":"Alta agressividade.","B":"Infiltração até 3mm no estroma.","C":"Linhagem mulleriano do tumor.","D":"Não há invasão do estroma."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-196731","number":"196731","sourceNumber":"196731","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"É tumor de linhagem epitelial:","options":{"A":"Disgerminoma.","B":"Teratoma.","C":"Carcinóide.","D":"Brenner."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-196758","number":"196758","sourceNumber":"196758","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente com 65 anos, mastectonizada há ±5 anos, apresenta forte dor de coluna. A\ncintilografia evidencia em L?, lesão blastomatosa. Qual melhor conduta para aliviar a dor?","options":{"A":"Quimioterapia.","B":"Radioterapia.","C":"Injeção de samário.","D":"Hormonioterapia."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-199591","number":"199591","sourceNumber":"199591","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Os cistos ovarianos funcionais incluem cistos foliculares, cistos do corpo lúteo e cistos\ntecaluteínicos. Em relação aos cistos ovarianos foliculares, analise as assertivas abaixo e assinale\na alternativa CORRETA:\n\nI- São cistos benignos;\n\nII- São os mais comuns dos cistos funcionais;\n\nIII- É mais comum em mulheres menopausadas;\n\nIV- Na maioria das vezes necessitam de tratamento cirúrgico.","options":{"A":"Está correta apenas a assertiva I.","B":"Estão corretas as assertivas I e II.","C":"Estão corretas as assertivas III e IV.","D":"Estão corretas as assertivas I, II e III."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-215142","number":"215142","sourceNumber":"215142","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"O câncer de mama é a principal neoplasia maligna em incidência no sexo feminino.\nDentre as alternativas abaixo assinale qual o\ntipo histológico mais frequente de neoplasia maligna\nda mama.","options":{"A":"Carcinoma ductal infiltrante.","B":"Carcinoma lobular infiltrante.","C":"Carcinoma medular.","D":"Carcinoma neuroendócrino.","E":"Fibroadenoma."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-212961","number":"212961","sourceNumber":"212961","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"A etiologia mais frequente de secreção papilar unilateral, espontânea, sanguinolenta de\num único ducto é causada por:","options":{"A":"Fibroadenoma.","B":"Alteração funcional.","C":"Carcinoma de mama.","D":"Adenose mamária.","E":"Papiloma intraductal."},"answer":"E","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-212968","number":"212968","sourceNumber":"212968","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"O linfonodo sentinela é:","options":{"A":"Mais próximo do tumor.","B":"Do nível I de Berg.","C":"Maior da região axilar.","D":"Apical da axila.","E":"Primeiro a receber a drenagem linfática de área tumoral."},"answer":"E","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-215165","number":"215165","sourceNumber":"215165","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente de 43 anos com Mamografia BIRADS 2 com mamas densas! Segundo o\nestudo ACRIN 6666, qual exame eu devo associar para aumentar a Acurácia do método?","options":{"A":"Ultrassonografia de mamas.","B":"RNM das mamas.","C":"Ductografia.","D":"Mamografia semestral.","E":"Biópsia de tecido mamário."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-215168","number":"215168","sourceNumber":"215168","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Histologicamente como se define o Carcinoma Inflamatório da Mama?","options":{"A":"Células em fila indiana.","B":"Embolização metastática para linfáticos da pele.","C":"Rompimento da membrana basal.","D":"Necrose intraductal.","E":"E-Células neoplásicas infiltrando a epiderme."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-215172","number":"215172","sourceNumber":"215172","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"À respeito do Carcinoma Lobular é CORRETO afirmar:","options":{"A":"É o tipo mais agressivo.","B":"É o tipo mais comum.","C":"Possui tendência à bilateralidade, multifocalidade e multicentricidade.","D":"Grande parte são HER 2 positivo.","E":"O tipo pleomorfico é o menos agressivo."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-174399","number":"174399","sourceNumber":"174399","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Mamografias que apresentam achado de nódulo espiculado, irregular com alta\ndensidade são classificadas na categoria BI-RADS 5. Pacientes com esses achados devem:","options":{"A":"Realizar estudo histopatológico da lesão.","B":"Repetir a mamografia em 1 ano.","C":"Realizar ultrassonografia ou ressonância nuclear magnética das mamas para esclarecimento do\ndiagnóstico.","D":"Realizar mamografia e ultrassonografia das mamas a cada 6 meses.","E":"Realizar mastectomia com linfadenectomia axilar, seguida de radioterapia e quimioterapia."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-172779","number":"172779","sourceNumber":"172779","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"No rastreamento ultrassonográfico dos tumores ovarianos evidencia-se vários aspectos\nrelacionados às imagens, tais como: I- bilateralidade; II- massa sólida; III- septações espessas;\nIV-\npapilas intracísticas. Qual desses aspectos é sugestivo de malignidade?","options":{"A":"II e IV apenas.","B":"III e IV apenas.","C":"II, III, IV apenas.","D":"I, II, III e IV."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-172805","number":"172805","sourceNumber":"172805","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"As doenças das mamas são causas comuns de consulta médica devido ao grande\nmedo do câncer. Analise as patologias de\nmama abaixo: I- fibroadenoma; II- adenose; III- papiloma\nintraductal; IV- eclasia ductal. Qual(is) da(s) seguinte(s) é(são) considerada(s) patologia(s)\nbenigna(s)?","options":{"A":"I apenas.","B":"I e IV apenas.","C":"I, II, e IV apenas.","D":"I, II, III e IV."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-187442","number":"187442","sourceNumber":"187442","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente de 62 anos, assintomática, sem comorbidades, realizou mamografia de\nrastreamento que evidenciou um nódulo mamário no quadrante superior externo de mama direita\nsuspeito de neoplasia maligna (categoria BIRADS 4A). Assinale dentre as alternativas abaixo a\nconduta mais adequada:","options":{"A":"Indicar a realização de quadrantectomia de mama direita com esvaziamento axilar radical níveis\nI, II e III.","B":"Indicar a nodulectomia com pesquisa de linfonodo sentinela utilizando a técnica do azul patente","C":"Indicar a realização de core biópsia guiada por ultrassonografia ou mamografia.","D":"Nodulectomia mamárea com exame de congelação intra-operatório. Caso confirmado carcinoma\nmamário submeter a paciente durante o mesmo procedimento a ampliação das margens e\npesquisa de linfonodo sentinela com medicina nuclear.","E":"Radioquimioterapia neoadjuvante seguido de quadrantectomia de mama e pesquisa de linfonodo\nsentinela."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-187444","number":"187444","sourceNumber":"187444","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente de 55 anos, com história de aumento do volume abdominal há cerca de 4\nmeses e perda ponderal de cerca de 8 Kg.\nSem comorbidades. Ao exame físico: Bom estado geral,\ncom abdome globoso, massa palpável em andar inferior e ascite moderada. Ausculta pulmonar\ndiminuída em base de pulmão direito. Realizado ressonância magnética de abdome que evidenciou\nmassa ovariana sólidocística de cerca de 15x15cm de diâmetro, ascite leve e nódulos peritoneais\nde até 1x1cm. Assinale dentre as assertivas abaixo qual a conduta mais adequada diante do\nquadro clínico da paciente:","options":{"A":"Solicitar colonoscopia, endoscopia digestiva alta (EDA), marcadores tumorais (cea, ca125,\nAlfaFetoProteina-AFP). Submeter a paciente a laparotomia mediana com ooforectomia e\ncongelação intra- operatória.Se confirmado neoplasia maligna de ovário realizar se possível\ncitorredução completa que envolve histerectomia, ooforectomia, omentectomia e biópsias de\ngoteiras e cupulas diafragmáticas.","B":"Solicitar marcadores tumorais(cea, ca125, AFP). Submeter a paciente a laparotomia mediana\ncom inventario completo da cavidade, se possível com citorredução completa que envolve\nhisterectomia, ooforectomia, omentectomia e biópsias de goteiras e cupulas diafragmáticas.","C":"Submeter a paciente inicialmente a quimioterapia neoadjuvante, pois o exame de imagem\ndemonstra doença avançada, não sendo possível\nrealizar cirurgia de citorredução neste momento.","D":"Solicitar colonoscopia, EDA, marcadores tumorais(cea, ca125, AFP). Submeter a paciente a\nincisão de Pfannenstiel com inventario completo da cavidade, se possível com citorredução\ncompleta que envolve histerectomia, ooforectomia, omentectomia e biópsias de goteiras e cupulas\ndiafragmáticas.","E":"Submeter a paciente inicialmente a radioterapia neoadjuvante, pois o exame de imagem\ndemonstra doença avançada não, sendo possível\nrealizar cirurgia de citorredução neste momento."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-187468","number":"187468","sourceNumber":"187468","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"O câncer de mama é o tipo de câncer mais comum entre as mulheres no mundo e no\nBrasil, depois do de pele não melanoma, respondendo por cerca de 28% dos casos novos a cada\nano. O câncer de mama não tem uma causa única. Diversos fatores estão relacionados ao\naumento do risco de desenvolver a doença, como: idade, fatores endócrinos, história reprodutiva,\nfatores comportamentais/ambientais e fatores genéticos/hereditários. São fatores de risco\ncomportamentais/ ambientais conhecidos para o desenvolvimento de câncer de mama, EXCETO:","options":{"A":"Sedentarismo.","B":"Tabagismo.","C":"Radiação.","D":"Cafeína.","E":"Jornada de trabalho noturna."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-187466","number":"187466","sourceNumber":"187466","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Dentre todos os cânceres ginecológicos, os tumores malignos de ovário são os que\nrepresentam o maior desafio clínico quanto ao rastreamento e diagnóstico precoce. Sobre esses\ntumores, deve-se ressaltar o seguinte:","options":{"A":"A maioria dos cânceres de ovário hereditários está associada à mutação do gene BRCA 2:","B":"As mutações associadas ao câncer de ovário têm herança autossômica dominante e, portanto,\ndeve ser feita uma analise cuidadosa do\nheredrograma;","C":"Os tipos histológicos mais comuns de câncer de ovário são os mucinosos e células claras.","D":"Os teratomas maduros são malignos e extremamente agressivos;","E":"O diagnóstico precoce pode ser realizado através de exame ginecológico anual;"},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-187493","number":"187493","sourceNumber":"187493","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Sobre as neoplasias mamárias, podemos informar, EXCETO:","options":{"A":"O tumor filoide (Cystossarcoma phylloides) caracteriza-se pela hipocelularidade.)","B":"O fibroadenoma em mulheres com menos de 35 anos de idade poderá ter conduta expectante.","C":"A doença de Paget é uma neoplasia rara e pode se disseminar para pele e mamilo.","D":"O papiloma solitário é lesão pré-cancerosa.","E":"O angiossarcoma é um tipo raro de câncer de mama que começa nas células que revestem os\nvasos sanguíneos ou linfáticos."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-155402","number":"155402","sourceNumber":"155402","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Entre as alterações fibrocísticas benignas da mama podemos citar, EXCETO:","options":{"A":"Cistos mamários.","B":"Nodularidade.","C":"Mastalgia.","D":"Fluxo papilar.","E":"Retração."},"answer":"E","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-155365","number":"155365","sourceNumber":"155365","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Sobre as neoplasias de ovário, podemos afirmar que:","options":{"A":"Os tumores de Brenner, habitualmente, são encontrados na adolescência e no menacme.","B":"Os teratomas maduros são mais comuns em mulheres jovens no menacme.","C":"Os tecomas podem cursar com derrame pleural ? síndrome de Meigs.","D":"Os digerminomas apresentam tecidos derivados das 3 camadas germinativas, podendo ser\nencontrado cabelos, cartilagens, sebo e tecido nervoso durante a cirurgia.","E":"Os tumores do seio endodérmico apresentam como achado citológico característico as células\nem ?anel de sinete?."},"answer":"E","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-155372","number":"155372","sourceNumber":"155372","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"O tabagismo está fortemente associado a qual dessas patologias mamárias abaixo:","options":{"A":"Papiloma intraductal.","B":"Fibroadenoma.","C":"Mastite periareolar recidivante.","D":"Ectasia ductal.","E":"Carcinoma inflamatório."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-155359","number":"155359","sourceNumber":"155359","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"O câncer de ovário é o tumor ginecológico mais difícil de ser diagnosticado e o de maior\nchance de cura. Cerca de 3?4 dos cânceres deste órgão apresentam-se em estágio avançado no\nmomento do diagnóstico. A estimativa de novos casos para 2016 é de 6150 novos casos e um\nnúmero de mortes de 3283. (www.inca.gov.br). Assinale a alternativa CORRETA sobre o câncer de\novário:","options":{"A":"Dentre os fatores de risco temos a multiparidade, idade menor que 40 anos, menarca tardia e\nmenopausa precoce, parentes de primeiro grau com câncer de ovário e mulheres que nunca\namamentaram.","B":"Dentre os sinais e sintomas da doença temos que lembrar que essas pacientes geralmente são\nassintomáticas nas fases iniciais, seguido de dor e aumento do volume abdominal secundário a\nascite e constipação intestinal. O sangramento vaginal pode ocorrer, mesmo em pacientes pós\nmenopausa. Em casos mais avançados temos também o derrame pleural à direita que está\nassociado à síndrome de Meigs.","C":"Os marcadores tumorais para câncer de ovário são o Ca 15.3, DHL e Ca 19.9.","D":"Os tumores originários de células germinativas e tumores estromais são mais frequentes que os\nderivados de células epiteliais. Estes últimos representando menos de 10% dos casos.","E":"A cirurgia citorredutora consta de laparotomia com lavado peritoneal, histerectomia e\nsalpingoooforectomia bilateral. Não há indicação de ressecções mais alargadas incluindo\nlinfadenectomias, omentectomia e ressecções de órgãos contíguos mesmo que se consiga um\nvolume residual de doença menor que 1 cm, pois esses pacientes fatalmente irão evoluir com\nrecidivas e não se mostrou benefício neste tipo de abordagem cirúrgica mais agressiva."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-155369","number":"155369","sourceNumber":"155369","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Os carcinomas da mama são divididos em dois grandes grupos: carcinomas in situ e\ncarcinomas invasivos. Os carcinomas invasivos são aqueles onde as células tumorais invadem os\ntecidos adjacentes aos ductos mamáreos, e apresentam tendência a metastatizar para linfonodos\nregionais e sítios anatômicos distantes. Em relação à classificação histopatológica dos carcinomas\ninvasivos é INCORRETO afirmar:","options":{"A":"O carcinoma inflamatório é definido como um carcinoma de mama com apresentação clínica\npeculiar (pele com eritema, edema, calor, e\npeau d?orange) devido a importante obstrução linfática\ncausada pela disseminação do carcinoma acometendo a mama.","B":"O carcinoma ductal invasivo é o tipo histológico menos comum, perfazendo menos de 3% dos\ncasos de câncer de mama dependendo da série\navaliada.","C":"O carcinoma lobular invasivo representa 5-15% dos carcinomas mamáreos e é composto por\ncélulas tumorais não coesivas entre si,\ndispostas individualmente e infiltrando o estroma (padrão de\n\n?fila indiana?). Além disso, este tipo de carcinoma cursa com multicentricidade e bilateralidade.","D":"O carcinoma de mama é uma neoplasia heterogênea com achados morfológicos,\ncomportamento clínico e resposta variável a\nregimes terapêuticos. A imuno-histoquímica é utilizada\nna classificação molecular do câncer de mama, permitindo a avaliação de receptores de estrogênio,\nprogesterona, HER2 dentre outros.","E":"O carcinoma de mama com perfil imuno-histoquímico triplo negativo (ausência de receptores\npara estrogênio, progesterona e HER2 negativo)\napresenta maior tendência a metástases para o\nsistema nervoso central, conferindo um pior prognóstico."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-162569","number":"162569","sourceNumber":"162569","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente de 20 anos da entrada em um PS com quadro de abdome agudo de provável\ncausa ginecológica ? quadro avaliado por cirurgião geral que descartou apendicite. O clínico de\nplantão solicitou um Beta HCG, o qual mostrou resultado negativo. Na ausência de USG para\navaliar cavidade, fez uma paracentese, a qual se mostrou positiva para sangue incoagulável. Na\nanamnese, a paciente havia parado de tomar anticoncepcional oral há 20 dias para engravidar.A\nhipótese diagnostica provável seria:","options":{"A":"DIPA.","B":"Torção de anexo.","C":"Prenhez Tubária.","D":"Abortamento incompleto.","E":"Cisto Hemorrágico."},"answer":"E","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-162573","number":"162573","sourceNumber":"162573","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Importante fator etiológico da mastite periareolar recidivante:","options":{"A":"Amamentação.","B":"Tabagismo.","C":"Histórico Familiar.","D":"Estimulação Sexual dos mamilos.","E":"Adenocarcinoma ductal."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-127152","number":"127152","sourceNumber":"127152","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente com 32 anos apresenta no exame ultrassonográfico uma imagem cística\ncomplexa em ovário esquerdo, com conteúdo heterogêneo. Foi submetida a vídeo-laparoscopia\ncirúrgica com cistectomia com exérese da cápsula íntegra. O exame de congelação evidenciou\nCisto Dermoide (Teratoma Maduro). A conduta cirúrgica correta para essa paciente é:","options":{"A":"Salpingooforectomia esquerda complementar.","B":"Ooforectomia bilateral e preservação do útero para gravidez futura.","C":"Histerectomia total com anexectomia bilateral.","D":"A cistectomia com a cápsula íntegra e preservação do parênquima ovariano é suficiente.","E":"Anexectomia unilateral, coleta de lavado peritoneal, omentectomia infracólica e linfoadenectomia\nunilateral."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-137829","number":"137829","sourceNumber":"137829","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Com relação ao câncer de mama é correto afirmar:","options":{"A":"Dos tumores invasivos o lobular é o mais comum.","B":"A idade é o principal fator de risco.","C":"Os receptores hormonais não influenciam no tratamento do câncer de mama.","D":"Aproximadamente 40% dos tumores de mama são positivos para HER-2.","E":"Mutações germinativas de BRCA1 ou BRCA2 não aumentam risco de câncer de mama."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-127225","number":"127225","sourceNumber":"127225","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Lactante no 21º dia de puerpério é atendida com queixa de febre alta (40°C), mal estar\ne dor nas mamas, após 3 dias de\nantibioticoterapia. Ao exame físico: identifica-se a presença de\nedema pronunciado no sulco submamário, vermelhidão da pele e dor intensa à palpação da mama\nesquerda, com a sensação de que está flutuando. Qual é a principal hipótese diagnóstica?","options":{"A":"Ingurgitamento mamário.","B":"Fissuras mamária.","C":"Abscesso areolar.","D":"Flegmão retromamário.","E":"Mastite parenquimatosa."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-131685","number":"131685","sourceNumber":"131685","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Em relação ao câncer de mama, considere as assertivas abaixo: I - diâmetro tumoral\nacima de 2cm; II - impossibilidade de\nradioterapia complementar; III - linfonodos axilares positivos;\nContraindicão(ões) absoluta(s) para cirurgia conservadora:","options":{"A":"Assertiva I;","B":"Assertiva II;","C":"Assertiva III;","D":"Assertivas I e II;","E":"Assertiva II e III;"},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-131683","number":"131683","sourceNumber":"131683","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente comenta que seu ovário direito foi removido durante a cesariana porque\napresentava dentes e cabelos. Provavelmente trata-se de:","options":{"A":"Cisto dentoide;","B":"Teratoma imaturo;","C":"Teratoma maduro;","D":"Coriocarcinoma;","E":"Digerminoma;"},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-131667","number":"131667","sourceNumber":"131667","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"De acordo com as diretrizes operacionais do Pacto pela Saúde, em relação às\nmetas para o controle do câncer de mama se espera:","options":{"A":"Cobertura de 100% das mulheres com mamografia.","B":"Cobertura de 80% das mulheres com ultrassonografia de mama.","C":"Dosagem do Ca 15-3 em 100% dos casos suspeitos.","D":"Realização de punção diagnóstica em 100% dos casos necessários.","E":"Internação de 80% das mulheres com indicação de mastectomia radical."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-100959","number":"100959","sourceNumber":"100959","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Os cistos ovarianos são achados comuns nos exames ginecológicos e provocam\ngrande apreensão devido aos riscos de se tratar de\num câncer. Qual dos achados\nultrassonográficos no exame pélvico abaixo indicam maior risco de malignidade?","options":{"A":"Conteúdo anecóico.","B":"Conteúdo denso.","C":"Contornos irregulares.","D":"Septações finas.","E":"Projeções papilares."},"answer":"E","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-101013","number":"101013","sourceNumber":"101013","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Em uma paciente que apresenta o seguinte quadro clínico: história obstétrica sem\ncomplicações, último parto há 03 meses, com sangramento vaginal persistente, beta-hCG positivo,\ntosse persistente, associada à lesões pulmonares numulares à radiografia de tórax, e um episódio\nde crise convulsiva. Deve-se pensar em:","options":{"A":"Crise epiléptica.","B":"Coriocarcinoma.","C":"Mola invasora.","D":"Adenocarcinoma pulmonar.","E":"Neurocisticercose."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-102754","number":"102754","sourceNumber":"102754","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Em relação às doenças benignas da mama, assinale a alternativa INCORRETA.","options":{"A":"A incidência de fibroadenomas é mais comum em mulheres com menos de 25 anos, porém,\napós os 55 anos, volta a apresentar acréscimo\nsignificativo em sua incidência.","B":"A ultrassonografia é o exame de escolha na diferenciação entre tumores sólidos e císticos.","C":"A taxa de resultados falso-positivos da ultrassonografia é maior que a da mamografia.","D":"Os tumores filoides podem ocorrer em qualquer idade, porém são mais comuns nas mulheres\nentre 40 e 59 anos."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-106407","number":"106407","sourceNumber":"106407","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Sobre os tumores de ovário, marque a assertiva INCORRETA:","options":{"A":"Os tumores de seio endodérmico possuem como principal marcador tumoral a alfafetoproteína.","B":"Os disgerminomas são a neoplasia maligna mais comum em crianças, adolescentes e adultos\njovens.","C":"Os teratomas imaturos apresentam tecidos derivados dos três folhetos de células germinativas,\nsendo comum encontrar em seu interior glândulas\nsebáceas, cartilagem, tecido ósseo e cabelos.","D":"O tumor de Krukenberg tem como característica citológica a presença de células de anel de\nsinete.","E":"O tumor de células transicionais possui epitélio similar ao do revestimento da bexiga."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-106415","number":"106415","sourceNumber":"106415","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente com 27 anos, usuária de prótese de silicone mamária com fins estéticos,\nconsultou com ginecologista com queixa de\naparecimento de ?caroço na mama esquerda?. Levou\npara consulta um exame de ultrassom mamário, realizado havia seis meses, que evidenciava um\nnódulo em mama esquerda de menos de 1 cm, de aspecto cístico. Paciente extremamente ansiosa,\ncancerofóbica, pois sua mãe foi submetida à quadrantectomia há 8 anos devido a nódulo maligno\nde mama. No exame palpatório das mamas, ginecologista palpou nódulo periareolar, bem\ndelimitado e levemente móvel e solicitou que realizasse ultrassonografia mamária. A ultrassom de\nmama realizada evidenciou nódulo complexo, multibocelado, com 2.3 cm. Das assertivas abaixo,\nqual a mais CORRETA:","options":{"A":"core-biopsy;","B":"conduta expectante;","C":"repetir ultrassom em seis meses;","D":"quadrantectomia;","E":"novo ultrassom em 6 meses."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-88898","number":"88898","sourceNumber":"88898","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente feminina, 24 anos, procura posto de saúde para revisão ginecológica anual.\nAo exame físico, é detectado nódulo de\naproximadamente 3 cm, bem delimitado, móvel, sem dor à\npalpação, localizado em quadrante superior externo da mama esquerda, sem líquido à expressão\ndo mamilo, sem linfonodos axilares palpáveis. Mãe com história de câncer de mama. A conduta\nimediata mais adequada neste caso é:","options":{"A":"mamografia.","B":"excisar o nódulo.","C":"mastectomia esquerda.","D":"punção aspirativa do nódulo com agulha fina.","E":"cintilografia óssea."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-77328","number":"77328","sourceNumber":"77328","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Acerca da doença fibrocística da mama, marque a alternativa INCORRETA:","options":{"A":"É geralmente indolor e unilateral.","B":"Apresentam comumente grande flutuação de tamanho.","C":"O estrogênio é considerado um fator causal.","D":"Ocorre mais comumente em mulheres jovens.","E":"A ultrassonografia da mama pode ser usada para o diagnóstico."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-77334","number":"77334","sourceNumber":"77334","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"No câncer de mama, não é verdade:","options":{"A":"Ossos são sítios incomuns de metástases.","B":"Em uma grande parte das mulheres não se identifica os fatores de risco para o surgimento do\ncâncer.","C":"O autoexame da mama é útil, mas não substitui a necessidade de realização de mamografias\nperiódicas para a detecção precoce do câncer de mama.","D":"O carcinoma inflamatório da mama é uma forma extremamente agressiva de apresentação do\ncâncer de mama.","E":"O tratamento pode ser totalmente curativo dependendo do momento do diagnóstico."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-77507","number":"77507","sourceNumber":"77507","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Em relação ao Fibroadenoma é correto afirmar, exceto:","options":{"A":"É o tumor mamário mais comuns nas mulheres jovens, até 30 anos.","B":"Geralmente é nódulo pequeno (1 a 3 cm), bem delimitado, móvel, arredondado ou bocelado e de\ncrescimento lento.","C":"Na gravidez e lactação o crescimento pode ser mais rápido e produzir dor por infarto.","D":"A frequência de transformação maligna é rara: 1 a 3% dos casos.","E":"A bilateralidade é da ordem de 5 a 10% dos casos."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-59396","number":"59396","sourceNumber":"59396","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Acerca da doença fibrocística da mama, marque a alternativa INCORRETA:","options":{"A":"É geralmente dolorosa e bilateral.","B":"Apresentam comumente grande flutuação de tamanho.","C":"O estrogênio é considerado um fator causal.","D":"Ocorre mais comumente na menopausa.","E":"A ultrassonografia da mama pode ser usada para o diagnóstico quando a doença ocorrer em\nmulheres jovens."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-59407","number":"59407","sourceNumber":"59407","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"No câncer da mama, não é verdade:","options":{"A":"Ossos são sítios comuns de metástases.","B":"Em uma grande parte das mulheres não se identifica os fatores de risco para o surgimento do\ncâncer.","C":"O autoexame da mama tem maior eficácia do que as mamografias periódicas na detecção\nprecoce do câncer de mama.","D":"O carcinoma inflamatório da mama é uma forma extremamente agressiva de apresentação do\ncâncer de mama.","E":"O tratamento pode ser totalmente curativo dependendo do momento do diagnóstico."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-59015","number":"59015","sourceNumber":"59015","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"São considerados fatores de risco para câncer de mama, exceto:","options":{"A":"Ser mulher.","B":"Ingestão regular de bebida alcoólica.","C":"Tabagismo.","D":"Menarca precoce e menopausa tardia.","E":"Obesidade central."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-43304","number":"43304","sourceNumber":"43304","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Em relação ao adenocarcinoma de endométrio, marque a alternativa CORRETA:","options":{"A":"O exame de Papanicolau é geralmente negativo.","B":"Mesmo com diagnóstico precoce, sua taxa de mortalidade em 05 anos é superior a 50%.","C":"Com o controle de câncer de colo, hoje é o tumor mais frequente do trato genital feminino.","D":"A dor em região hipogástrica é um sintoma bastante comum.","E":"Nuliparidade, Ovários policísticos com anovulação prolongada e uso de tamoxifeno constituem\nfatores de risco para o seu desenvolvimento."},"answer":"E","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-43940","number":"43940","sourceNumber":"43940","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Em relação à infecção pelo papilomavírus humano (HPV) é incorreto afirmar:","options":{"A":"As variantes das sequências de nucleotídios já permitiram o encontro de mais de 100 tipos\ndiferentes de vírus.","B":"O período de incubação varia de 03 semanas a 08 meses, tendo como média de 2,8 meses.","C":"O grau de infecciosidade varia com a idade e com a resistência individual.","D":"As lesões progridem em índice maior que a regressão espontânea.","E":"Os exames vulvoscópico e/ou colposcópico denunciam as formas subclínicas."},"answer":"E","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-43947","number":"43947","sourceNumber":"43947","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"O fluxo papilar de natureza neoplásica geralmente tem como característica:","options":{"A":"Espontâneo, bilateral, uniductal, esverdeado ou acizentado.","B":"Não espontâneo, unilateral, poliductal, hemorrágico ou aquoso.","C":"Espontâneo, unilateral, uniductal, hemorrágico ou aquoso.","D":"Não espontâneo, bilateral, uniductal, hemorrágico ou aquoso.","E":"Espontâneo, unilateral, uniductal, esverdeado ou acizentado."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-27323","number":"27323","sourceNumber":"27323","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Qual sua conduta em paciente de 60 anos que apresenta no exame ultra-sonográfico\num cisto em ovário direito com diâmetro de 4 cm,\nunilocular, paredes finas?","options":{"A":"Pan histerectomia","B":"Ooforectomia unilateral","C":"Salpingooforectomia bilateral","D":"Ooforectomia bilateral","E":"Tratamento conservador sem cirurgia"},"answer":"E","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-27325","number":"27325","sourceNumber":"27325","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"A torção dos anexos com paciente jovem deve ser tratada:","options":{"A":"Expectante","B":"Cirurgia radical (retirado do anexo)","C":"Cirurgia com distorção e retirada apenas do cisto.","D":"Cirurgia com secção abaixo da torção sem desfazê-la","E":"Se necrose apenas observar"},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-23119","number":"23119","sourceNumber":"23119","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Dentre as urgências ginecológicas destaca-se o abdome agudo ginecológico. Não é\ncorreto afirmar que:","options":{"A":"O abdome agudo ginecológico hemorrágico é decorrente principalmente da gravidez ectópica,\nrotura de cistos ou de tumores pélvicos","B":"A prenhez ectópica é a causa mais comum de mortalidade materna durante o primeiro trimestre\nda gestação","C":"O tratamento da rotura de cisto folicular ou de corpo lúteo geralmente é feito pela laparoscopia\nginecológica","D":"Dentre os tumores ovarianos que causam abdome agudo ginecológico, destacam-se os\nendometriomas","E":"Torções totais ou parciais de órgãos pélvicos são causas menos frequentes de abdome agudo\nginecológico"},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-23110","number":"23110","sourceNumber":"23110","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"É o tumor ovariano mais comum em mulheres jovens, até os 40 anos:","options":{"A":"Cistoadenoma seroso.","B":"Cistoadenoma mucinoso.","C":"Tumor endometrioide.","D":"Teratoma maduro.","E":"Fibromas."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-23114","number":"23114","sourceNumber":"23114","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Quanto os aspectos epidemológicos do carcinoma ovariano, é incorreto afirmar:","options":{"A":"a raça branca é mais acometida.","B":"é amplamente difundida a importância do fator familiar.","C":"a ingestão excessiva de gordura animal, de leite e carnes vermelhas associa-se a maior risco.","D":"é mais comum em nulíparas.","E":"é mais comum em usuárias de contraceptivos hormonais por longo tempo."},"answer":"E","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-27353","number":"27353","sourceNumber":"27353","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"O Tumor maligno mucosecretor da cavidade peritoneal que surge após uma ruptura de\numa neoplasia maligna ovariana ou de um\nadenocarcinoma apendicular, é denominado de:","options":{"A":"Carcinomatose invasiva","B":"Adenocarcinoma invasivo","C":"Abdome congelado","D":"Pseudomixoma","E":"Carcinoma indiferenciado"},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-9400","number":"9400","sourceNumber":"9400","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Descarga papilar unilateral, espontânea, sanguinolenta, de ducto único, geralmente é:","options":{"A":"câncer.","B":"papiloma intraductal.","C":"fibroadenoma.","D":"mastopatia fibrocistica.","E":"adenose."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-8139","number":"8139","sourceNumber":"8139","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Pacientes de 54 anos fez mamografia há 15 dias, que mostrou nódulo neoformado de 5\nmm isodenso, fez ultrassom que mostrou tratar-se de nódulo cístico homogêneo de bordos\nregulares, história familiar de mãe com câncer de mama aos 84 anos. Qual a melhor conduta?","options":{"A":"Exerése do nódulo.","B":"Acompanhamento mamográfico anual.","C":"Encaminhar ao oncologista.","D":"Acompanhamento mamográfico trimenstral.","E":"Realização de PET scan."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-362608","number":"362608","sourceNumber":"362608","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente de 23 anos comparece ao ambulatório de ginecologia apresentando nódulo de\n6 cm em mama esquerda. Ao ultrassom fica\nevidente se tratar de cisto. A conduta inicial deve ser:","options":{"A":"exérese.","B":"quadrantectomia.","C":"observação por 4-6 meses e repetir ultrassom.","D":"punção aspirativa."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-346424","number":"346424","sourceNumber":"346424","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"O carcinoma ductal in situ representa entre 15% e 25% da incidência dos novos casos\nde câncer de mama. Assinale a alternativa\ncorreta em relação a essa doença:","options":{"A":"Por não ser carcinoma infiltrativo, a radioterapia não é utilizada após cirurgias conservadoras;","B":"Na maioria dos casos, é diagnosticado por tumor palpável;","C":"O tamoxifeno não é utilizado nas mulheres na pós-menopausa com receptores positivos;","D":"Entre 30% e 50% dos casos não irão evoluir para carcinoma infiltrativo."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-334151","number":"334151","sourceNumber":"334151","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"O câncer de mama resulta do crescimento desordenado de células com potencial\ninvasivo, que se dá a partir de alterações\ngenéticas (hereditárias ou adquiridas). Sobre o câncer de\nmama, assinale a correta:","options":{"A":"O tipo mais prevalente é o sarcoma lobular, que tem origem nos lóbulos mamários.","B":"O tipo mais prevalente é o carcinoma ductal, que tem origem nos ductos mamários e\ncorresponde a cerca de 80% dos casos.","C":"O tipo mais frequente é o carcinoma lobular, que tem origem nos lóbulos mamários e\ncorresponde a cerca de 80% dos casos.","D":"O tipo mais frequente é o carcinoma lobular, que tem origem na transição ducto-lobular, e\ncorresponde a mais de 95% dos casos."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-330119","number":"330119","sourceNumber":"330119","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Sobre o câncer de mama, é CORRETO afirmar:","options":{"A":"O tipo histológico mais comum de câncer de mama é o câncer lobular esquerdo, em que os\ntumores se originam dos gânglios linfáticos e logo vão a tecidos adjacentes.","B":"Mulheres com diagnóstico histopatológico de lesão mamária proliferativa com atipia ou neoplasia\nlobular in situ não se enquadram como fator de risco para o câncer de mama.","C":"A mamografia diagnóstica é para mulheres sem sinais ou sintomas de câncer de mama e\nconsiste em imagens bilaterais em duas incidências.","D":"A presença de nódulo ou espessamento na mama, próximo a ela, ou na axila, são sintomas\nimperceptíveis aos pacientes ou ao profissional de saúde."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-334824","number":"334824","sourceNumber":"334824","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"O carcinoma de mama é a segunda neoplasia maligna mais frequente na mulher,\nsuperado apenas pelo câncer de pele não\nmelanoma. No Brasil, aproximadamente 66 mil mulheres\nsão acometidas por câncer de mama anualmente, com taxa de mortalidade ao redor de 20%. Neste\ncontexto, sabe-se que:","options":{"A":"o carcinoma de mama é denominado in situ quando invade a membrana basal do epitélio; e\ninvasivo ou infiltrante quando não há comprometimento da membrana do estroma do parênquima\nmamário.","B":"o carcinoma pode ser graduado em lesões graus I, II ou III, de acordo com a formação tubular,\ncaracterísticas nucleares e índice mitótico, denominado sistema de Bloom e Richardson, sendo que\no grau III é o de melhor prognóstico.","C":"os carcinomas mamários, em sua maioria, é do tipo lobular (80%), seguido pelo carcinoma\nductal (8-15%). Outros tipos frequentes são:\nDoença de Paget, carcinoma inflamatório, adenóide\ncístico, ductal metaplásico, neuroendócrino, tubular, secretor, cribriforme apócrino, mucinoso ou\ncoloíde, medular, papilífero metastático, sarcoma e tumor filodes maligno.","D":"nos carcinomas de mama a proteína HER-2 está expressa em 15% deles. A proteína HER-2\nlocaliza-se na membrana celular e ativa a\ncascata de multiplicação celular. É um marcador preditivo\npara resposta terapêutica. O Ki-67 é um marcador nuclear de proliferação celular e a sua alta\nexpressão indica tumores de mau prognóstico (acima de 15% de expressão)."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-334825","number":"334825","sourceNumber":"334825","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Os laudos de imagem em mastologia foram padronizados em 1992 pelo Breast Imaging\nReporting and Data System (BI-RADS?) - American College of Radiology, e compreendem 7\ncategorias, variando de 0 a 6, dentre elas, sabe-se que:","options":{"A":"Categoria 0 - negativo - normal.","B":"Categoria 2 - achados benignos.","C":"Categoria 3 - achados provavelmente suspeitos.","D":"Categoria 4 - achados provavelmente benignos."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-334826","number":"334826","sourceNumber":"334826","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"A ultrassonografia tem especial importância devido à sua positiva relação\ncusto-benefício na investigação de anomalias anatômicas das mamas e outras anomalias\n\nsistêmicas que, por vezes acompanham o diagnóstico. Dentre as anomalias anatômicas das\nmamas e suas características, e que podem\nser detectadas por meio de ultrassonografia, tem-se.","options":{"A":"a politelia, que é a presença de mamilos supranumerários, é a anomalia menos frequente,\npodendo ocorrer em qualquer ponto da linha láctea\nprincipalmente no dorso.","B":"a Síndrome de Poland que é um defeito congênito raro, unilateral, associado à ausência parcial\nou completa da mama, com deformidades da parede\ntorácica, pele, subcutâneo ipisilateral e\nbranquissindactilia.","C":"o mamilo invertido que é decorrente de um sistema ductal hiperplásico, formando bandas\nfibrosas que causam sua retração o que facilita a amamentação.","D":"a telarca prematura que é o desenvolvimento mamário antes dos 14 anos de idade."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-330122","number":"330122","sourceNumber":"330122","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"São fatores de risco do câncer de ovário, EXCETO:","options":{"A":"Histórico familiar de câncer de ovário, câncer de mama, câncer de endométrio ou câncer de\ncólon.","B":"Mulheres com idade acima de 25 anos.","C":"Tratamento de fertilidade com fertilização in vitro.","D":"Uso de estrogênio isoladamente ou com progesterona após a menopausa."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-342658","number":"342658","sourceNumber":"342658","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"As imagens nodulares das mamas podem ter, à ultrassonografia, características de\ncistos, nódulos benignos ou malignos. São critérios ultrassonográficos que sugerem nódulo sólido\nbenigno, exceto:","options":{"A":"imagem hipoecoica com orientação do maior eixo vertical","B":"imagem hipoecoica com bordos estreitos","C":"imagem hipoecoica com maior eixo transversal","D":"imagem hipoecoica com ecos homogênicos"},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-334159","number":"334159","sourceNumber":"334159","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Entre as situações listadas, a que representa menor risco para câncer de mama é:","options":{"A":"Primeira gravidez após os 30 anos de idade.","B":"Menopausa precoce.","C":"Antecedente familiar de câncer de mama em familiares de primeiro grau.","D":"Histórico familiar de câncer de mama masculino."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-334829","number":"334829","sourceNumber":"334829","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Leia o relato do caso a seguir. CLS, 60 anos de idade, com rotinas mamográficas para\na idade, tabagista, menarca aos 11 anos de\nidade, G5P5nA0, primeira gestação aos 19 anos de\nidade, menopausa aos 49 anos e com irmã com câncer de mama diagnosticado aos 69 anos de\nidade, leva à consulta mamografia recente, classificação BI-RADS 5. Como se define o achado\nmamográfico e qual é a conduta recomendada neste caso?","options":{"A":"Lesão inconclusiva; comparar com ultrassonografia mamária e se possível pedir RNM.","B":"Lesão benigna; repetir a mamografia em um ano.","C":"Lesão provavelmente benigna; estudo citológico da lesão.","D":"Altamente sugestivo de malignidade; estudo histopatológico da lesão."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-342660","number":"342660","sourceNumber":"342660","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Ao ser examinada, uma paciente apresenta rash eczematoso focal do mamilo direito. A\nprincipal hipótese diagnóstica é:","options":{"A":"carcinoma lobular in situ","B":"doença de Paget","C":"fibroadenoma","D":"tumor filoide"},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-334831","number":"334831","sourceNumber":"334831","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"O Tumor filodes é raro e mais comum na raça negra, ocorre mais frequentemente entre\n30 e 50 anos, e pode estar associado a\nfibroadenomas. A descrição evolutiva do tumor filodes de\nmama (cistosarcoma phylloides) é a seguinte:","options":{"A":"nódulo único, encapsulado, pequeno, de consistência endurecida, crescimento lento e tendência\na recidiva.","B":"nódulo múltiplo, encapsulado, pequeno, de consistência fibroelástica, crescimento rápido e\ntendência a malignidade.","C":"nódulo único, encapsulado, volumoso, de consistência fibroelástica, crescimento rápido e\ntendência a recidiva.","D":"nódulo único, encapsulado, volumoso, de consistência endurecida, crescimento lento e\ntendência a não recidivar."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-321607","number":"321607","sourceNumber":"321607","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma mulher de 18 anos de idade vem sentindo desconforto pélvico há vários meses.\nAo exame ginecológico, há massa anexial\ndireita de 10cm. A TC do abdome revela que a massa\nparece ser sólida e circunscrita. Com a remoção cirúrgica, a massa é sólida e branca, com\npequenas áreas de necrose. Microscopicamente, contém principalmente células mesenquimais\nprimitivas, juntamente com um pouco de cartilagem, músculo e focos de diferenciação\nneuroepitelial. Qual é o diagnóstico mais provável?","options":{"A":"Tumor do Seio Endodérmico.","B":"Disgerminoma.","C":"Teratoma imaturo.","D":"Tumor mülleriano misto maligno."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-330130","number":"330130","sourceNumber":"330130","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente, 60 anos, com mamas indolores e sem massas, No exame de rotina, a\nmamografia demonstra um pequeno grupo de calcificações em torno de uma pequena massa.\nNeste caso:","options":{"A":"A mamografia não apresentou achados mamográficos característicos que são suspeitos de\ncâncer.","B":"O achado mamográfico dispensa a obtenção de tecido para diagnóstico histológico.","C":"Devido ao elevado risco de malignidade, é indicada uma biópsia central estereotáxica com\nagulha.","D":"A mamografia não deve ser considerada para o rastreamento do câncer de mama."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-330137","number":"330137","sourceNumber":"330137","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente, 47 anos, apresenta massa indolor de 1,5 cm na mama direita, sem alterações\ncutâneas ou adenopatia e achados da mamografia e da ultrassonografia normais. A biópsia central\nrevela carcinoma intraductal infiltrante. O impacto mais significativo no prognóstico da paciente\né:","options":{"A":"Presença de alterações cutâneas.","B":"Estado do receptor hormonal.","C":"Rigidez da mama.","D":"Tamanho do câncer primário."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-321632","number":"321632","sourceNumber":"321632","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Os métodos existentes para a detecção precoce do câncer de mama não reduzem a\nincidência, mas podem reduzir a mortalidade pela doença. Nesse sentido, o Ministério da Saúde\npreconiza que, na população de risco padrão para o câncer de mama, o rastreio seja realizado pela\nmamografia,","options":{"A":"em intervalos bianuais, em mulheres entre 50 e 69 anos.","B":"em intervalos anuais, em mulheres entre 40 e 69 anos.","C":"em grupo familiar menor que 40 anos, com antecedente positivo para o câncer de mama, em\nmulheres com idade menor que 40 anos.","D":"em meio familiar, com antecedente familiar positivo para o câncer de mama, em mulheres com\nidade superior a 70 anos."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-4-300907","number":"300907","sourceNumber":"300907","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Em relação aos macrocistos mamários, considere as seguintes assertivas: I.\nrepresentam etapa involutiva dos lóbulos\nmamários. II. tem incidência máxima após os 50 anos de\nidade. III. o tratamento consiste na simples punção esvaziadora. IV. a relação Na/K no líquido\ncístico pode guardar relação com risco de malignização. Estão CORRETAS:","options":{"A":"I, II e III.","B":"I, III e IV.","C":"II, III e IV.","D":"I e II."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-300908","number":"300908","sourceNumber":"300908","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente procura ginecologista para avaliação de ultrassom mamário que evidenciou\ncisto de 1,5 cm em mama esquerda. Ao exame\nfísico não é possível palpar o nódulo. A paciente\nnega antecedente familiar para câncer de mama. A MELHOR conduta no momento é:","options":{"A":"PAAF guiado por ultrassom.","B":"acompanhamento clínico.","C":"biópsia por agulha grossa.","D":"exploração cirúrgica."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-308225","number":"308225","sourceNumber":"308225","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente 33 anos, usuária de método contraceptivo injetável, com dor súbita e\nlancinante em fossa ilíaca esquerda, que\ncomeçou há 1 hora, procura atendimento médico. Ao\nexame normotensa, afebril, taquicardia, com sinais de abdome agudo. O toque vaginal evidencia\nintensa dor a mobilização de colo, palpando-se massa dolorosa de 9 cm na região anexial\nesquerda. No ultrassom evidencia-se formação heterogênea, com calcificações e sombra acústica,\ncom 8 cm, ocupando a região anexial esquerda. Há pequena quantidade de líquido livre na pelve.\nO diagnóstico mais provável é:","options":{"A":"Abscesso tubo -ovariano.","B":"Aborto tubário.","C":"Torção anexial.","D":"Cisto hemorrágico do ovário."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-308226","number":"308226","sourceNumber":"308226","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Jovem de 22 anos vem ao consultório preocupada, pois avó acaba de falecer de câncer\nde ovário, aos 80 anos de idade. Você explica\npara a paciente sobre os fatores de risco e\nprevenção do câncer de ovário. Assine a alternativa que reduz o risco de câncer de ovário:","options":{"A":"Uso de contraceptivos hormonais.","B":"Nuliparidade.","C":"Menopausa tardia.","D":"Uso de medicações para induzir a ovulação."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-302851","number":"302851","sourceNumber":"302851","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente de 31 anos de idade apresenta câncer de mama ductal invasivo luminal A,\ndiagnosticado por biópsia por agulha grossa. O tumor está em quadrante superolateral esquerdo e\nmede 1,7 cm. A axila é clinicamente livre. Devido à idade da paciente e às características desse\ntumor, indica-se:","options":{"A":"Quadrantectomia com biópsia de linfonodo sentinela. Se negativo, realizar hormonioterapia com\ntamoxifeno ou inibidor de aromatase.","B":"Quadrantectomia com biópsia de linfonodo sentinela. Se positivo, realizar radioterapia e\nquimioterapia.","C":"Adenomastectomia com reconstrução imedia ta, seguida por quimioterapia e hormonioterapia\ncom tamoxifeno.","D":"Mastectomia com esvaziamento axilar, radioterapia, quimioterapia e tamoxifeno.","E":"Quadrantectomia, esvaziamento axilar, radioterapia, hormonioterapia com inibidor de aromatase."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-308240","number":"308240","sourceNumber":"308240","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Homem trans de 50 anos foi ao consultório médico para avaliação de rotina e o médico\nsolicitou qual exame de rastreamento mais provável?","options":{"A":"PSA total e livre.","B":"Ultrassonografia de próstata.","C":"Mamografia bilateral.","D":"CA 125."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-308241","number":"308241","sourceNumber":"308241","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Mastologista recebeu paciente do sexo masculino de 75 anos em seu consultório com\nrelato de dor e aumento de volume unilateral de mama esquerda com nodulação de\naproximadamente 3cm retroareolar associada a retração mamilar. Qual o procedimento mais\nadequado para diagnóstico?","options":{"A":"USG de mamas.","B":"Biópsia por agulha grossa.","C":"Punção por agulha fina (PAAF).","D":"Biópsia excisional."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-316338","number":"316338","sourceNumber":"316338","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Abaixo estão listados fatores relacionados ao câncer de mama, exceto:","options":{"A":"História familiar positiva.","B":"Falta de reposição hormonal na menopausa.","C":"A incidência aumenta continuamente com a idade.","D":"50% dos homens são portadores dos genes responsáveis pela doença."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-316340","number":"316340","sourceNumber":"316340","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Com relação à propedêutica para rastreamento de neoplasias nas consultas\nginecológicas de rotina, analise os itens\nabaixo. I. Em mulheres que já tiveram atividade sexual,\ndeve-se realizar citopatológico de colo uterino anual a partir dos 25 anos de idade, podendo-se\nprolongar esse intervalo para cada 3 anos, após dois exames consecutivos negativos com intervalo\nanual. II. Em mulheres de baixo risco para câncer de mama, deve-se realizar mamografia a cada 2\nanos entre os 40 e 50 anos e, após, anual. III. Deve-se realizar ultrassonografia transvaginal\nanual,\napós a menopausa, para screening de câncer de ovário. IV. Deve-se realizar obrigatoriamente\nbiópsia de endométrio na presença de sangramento uterino anormal em pacientes na pré ou\n\npós-menopausa com fatores de risco para carcinoma de endométrio. Quais estão corretos?","options":{"A":"Apenas I e II.","B":"Apenas II e IV.","C":"Apenas I, II e IV.","D":"Apenas II, III e IV."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-317190","number":"317190","sourceNumber":"317190","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma mulher de 25 anos, G3P2 na sexta semana de gestação segundo seu último\nperíodo menstrual (DUM) foi submetida a\nultra-sonografia trans-vaginal em virtude de sangramento\nvaginal. A ultrassonografia confirma gestação intra-uterina com atividade cardíaca compatível com\n6 semanas. O estudo dos anexos revela cisto simples de 3cm no ovário esquerdo. Qual a\nalternativa verdadeira?","options":{"A":"Está paciente provavelmente apresenta tanto uma gestação intra-uterina como uma gestação\nectópica","B":"Esta paciente deve ser informada de que provavelmente vai sofrer um aborto","C":"O cisto ovariano não deve ser removido","D":"Esta paciente apresenta um ovo anembrionado"},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-315819","number":"315819","sourceNumber":"315819","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"As metástases do câncer de mama são mais comuns (por ordem do mais frequente ao\nmenos frequente) em:","options":{"A":"Ossos, pulmões, fígado, cérebro.","B":"Fígado, ossos, pulmões, cérebro.","C":"Pulmões, ossos, fígado, cérebro.","D":"Cérebro, ossos, pulmões, fígado."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-295392","number":"295392","sourceNumber":"295392","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"O carcinoma de mama é a segunda neoplasia maligna mais frequente na mulher,\nsuperado apenas pelo câncer de pele não\nmelanoma. No Brasil, aproximadamente 66 mil mulheres\nsão acometidas por câncer de mama anualmente, com taxa de mortalidade ao redor de 20%. Sobre\no câncer de mama sabe-se que:","options":{"A":"para que ocorra o câncer, é necessário um erro genético, que pode ser herdado, através de\nmutações germinativas, que são as mais frequentes, 99% dos casos, ou adquirido ao longo da\nvida, em decorrência de mutações somáticas, que são raras, 1%.","B":"dentre os fatores de risco, pode-se citar menarca tardia, menopausa precoce, multiparidade,\ngestação precoce e mamas predominantemente\nadiposas.","C":"dentre as manifestações clínicas, geralmente é observado nódulo indolor, fixo, endurecido e\naderido aos planos profundos.","D":"o autoexame e a ultrassonografia são fortemente recomendados para prevenção primária e\nsecundária."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-317981","number":"317981","sourceNumber":"317981","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Adolescente de 14 anos chega ao pronto-socorro com história de dores em região\nhipogástrica, com início há cerca de seis\nhoras, com piora progressiva. Tem antecedentes de ciclos\nmenstruais irregulares quanto aos intervalos, menstruações com duração de cinco a sete dias,\nassociadas a dismenorreia primária, menarca há três anos e última menstruação há cerca de duas\nsemanas. A ultrassonografia pélvica mostra, em topografia de anexo direito, tumoração anecoica,\nde paredes regulares e finas; sem septos e/ou debris em seu interior e com maior diâmetro de 6,0\ncm. A dopplerfluxometria mostrou alta resistência. Diante do exposto, a hipótese diagnóstica mais\nprovável é de","options":{"A":"cistoadenoma mucinoso.","B":"cistoadenoma seroso.","C":"cisto funcional.","D":"teratoma."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-317982","number":"317982","sourceNumber":"317982","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Em relação ao rastreamento do câncer de mama, sabe-se que:","options":{"A":"em mulheres com mamas gordurosas, a ressonância nuclear magnética é o método mais\nsensível.","B":"a mamografia é o único método que diminui a incidência de câncer de mama.","C":"em mamas gordurosas, são mais frequentes os resultados falsos-negativos na mamografia.","D":"a ultrassonografia é mais sensível em mamas densas do que em mamas gordurosas."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-300859","number":"300859","sourceNumber":"300859","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Acerca da mastite, infecção dolorosa do tecido mamário, responsável por dor e\ndesconforto nos peitos, é CORRETO afirmar:","options":{"A":"Se a mastite persistir, mesmo após o tratamento, e houver formação de abscesso, será preciso\numa pequena cirurgia.","B":"São causadas por bactérias denominadas Staphylococcus aureus e Haemophilus influenzae.","C":"Os sintomas incluem dor nas mamas, inchaço, calor, febre, suor, respiração ofegante e calafrios.","D":"Basta que haja amamentação contínua e uso de anti-inflamatórios não esteroidais em seu\ntratamento."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-295398","number":"295398","sourceNumber":"295398","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Diversas doenças podem ser acompanhadas de processo inflamatório nas mamas,\ndestacando-se, dentre elas, a doença de Mondor, mastite diabética, sarcoidose, mastite actínica,\nmastite por lúpus eritematoso disseminado e mastite granulomatosa. Dentre os tipos de mastites\ncrônicas tem-se:","options":{"A":"a mastite actínica, que se caracteriza por flebite superficial autolimitada, benigna,\ncaracterizada\npor cordão doloroso, que acompanha o trajeto\nvenoso cutâneo da mama.","B":"a doença de Mondor, que é decorrente de radioterapia mamária, devido a esclerose progressiva\nda íntima vascular. Caracteriza-se por\nhiperemia, dor e aumento da temperatura da mama.","C":"a mastite diabética também conhecida como mastite obliterante, comedomastite ou mastite de\ncélulas plasmáticas, que acomete os ductos lactíferos subareolares e caracteriza-se pela dilatação\nductal com acúmulo de detritos celulares.","D":"a mastite granulomatosa, que é uma inflamação de causa desconhecida, caracterizada por\nreação granulomatosa crônica composta por células\nepitelióides, células gigantes multinucleadas\ndos tipos corpo estranho e de Langhans."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-313242","number":"313242","sourceNumber":"313242","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma paciente de 45 anos relata descarga mamilar. Em face disso, deve-se prosseguir a\ninvestigação quando essa descarga for:","options":{"A":"uniductal e sanguinolenta","B":"unilateral e leitosa","C":"bilateral e amarelada","D":"espontânea e esverdeada"},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-313243","number":"313243","sourceNumber":"313243","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma paciente de 36 anos realizou ultrassonografia de mamas, identificando ectasia\nductal focal na mama esquerda como achado único.\nO exame foi realizado devido à queixa de\nmastalgia antecedendo a menstruação. A paciente nega descarga mamilar. Assinale a alternativa\nque apresenta a conduta correta:","options":{"A":"biópsia por agulha grossa","B":"biópsia por agulha fina","C":"acalmar a paciente e fazer acompanhamento anual","D":"controle em 3 meses"},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-294322","number":"294322","sourceNumber":"294322","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma mulher de 65 anos de idade tem apresentado aumento do volume abdominal há\nseis meses. No exame físico, há distensão abdominal com onda de líquidos. A ultrassonografia\npélvica revela a presença de massa ovariana cística de 10 cm à direita. A massa é removida\ncirurgicamente. Ao exame macroscópico, a massa removida é um cisto unilocular repleto de líquido\nclaro; e as projeções papilares se estendem à luz central do cisto. O exame microscópico mostra\nque as papilas são cobertas por células cuboides atípicas que invadem o estroma subjacente.\n\nNesse caso, qual é o diagnóstico mais provável?","options":{"A":"Cistadenoma seroso.","B":"Cistoadenocarcinoma seroso.","C":"Disgerminoma.","D":"Teratoma cístico maduro."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-295410","number":"295410","sourceNumber":"295410","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma mulher de 18 anos de idade vem sentindo desconforto pélvico há vários meses.\nAo exame ginecológico, há massa anexial\ndireita de 10 cm. A TC do abdome revela que a massa\nparece ser sólida e circunscrita. Com a remoção cirúrgica, a massa é sólida e branca, com\npequenas áreas de necrose. Microscopicamente, contém principalmente células mesenquimais\nprimitivas, juntamente com um pouco de cartilagem, músculo e focos de diferenciação\nneuroepitelial. Nesse caso, qual é o diagnóstico mais provável?","options":{"A":"Tumor do seio endodérmico.","B":"Disgerminoma.","C":"Tumor de células da granulosa.","D":"Teratoma imaturo."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-317997","number":"317997","sourceNumber":"317997","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma mulher de 18 anos vem sentindo desconforto pélvico há vários meses. Ao exame\nginecológico, há massa anexial direita de 10 cm. A TC do abdome revela que a massa parece ser\nsólida e circunscrita. Com a remoção cirúrgica, a massa é sólida e branca, com pequenas áreas de\nnecrose. Microscopicamente, contém principalmente células mesenquimais primitivas, juntamente\ncom um pouco de cartilagem, músculo e focos de diferenciação neuroepitelial. Nesse caso, qual é o\ndiagnóstico mais provável?","options":{"A":"Tumor de Brenner.","B":"Disgerminoma.","C":"Tumor mülleriano misto maligno.","D":"Teratoma imaturo."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-318016","number":"318016","sourceNumber":"318016","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Em uma mamografia, as calcificações com aspecto em \"pipoca\" indicam como principal\npossibilidade diagnóstica:","options":{"A":"hemangioma.","B":"esteatonecrose.","C":"plasmocitose.","D":"fibroadenoma."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-300993","number":"300993","sourceNumber":"300993","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Sobre o câncer de mama, assinale a CORRETA:","options":{"A":"O tipo mais prevalente é o sarcoma lobular, que tem origem nos lóbulos mamários.","B":"O tipo mais prevalente é o carcinoma ductal, que tem origem nos ductos mamários e\ncorresponde a cerca de 80% dos casos.","C":"O tipo mais frequente é o carcinoma lobular, que tem origem nos lóbulos mamários e\ncorresponde a cerca de 80% dos casos.","D":"O tipo mais frequente é o carcinoma lobular, que tem origem na transição ducto-lobular, e\ncorresponde a mais de 95% dos casos."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-274441","number":"274441","sourceNumber":"274441","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma menina de cinco anos apresenta aumento da mama, sangramento vaginal e\nmassa pélvica de 8 cm, das alternativas seguintes qual é a etiologia mais provável?","options":{"A":"Teratoma cístico benigno (dermoide).","B":"Tumor do seio endoderma.","C":"Tumor de Brenner.","D":"Tumor de célula da granulosa-teca."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-265838","number":"265838","sourceNumber":"265838","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Puérpera no terceiro mês de pós-parto, amamentando de forma não exclusiva,\napresenta dor mamária unilateral com calor\nlocal e sensação tátil de cordão fibroso subcutâneo. O\ndiagnóstico MAIS provável nesse caso é:","options":{"A":"Mastite.","B":"Ectasia ductal.","C":"Doença de Mondor.","D":"Esteatonecrose."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-265845","number":"265845","sourceNumber":"265845","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Em mulheres com mutação dos genes BRCA 1 e 2 o rastreamento com mamografia\ndeve começar com a idade de:","options":{"A":"20 anos.","B":"30 anos.","C":"35 anos.","D":"40 anos."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-285080","number":"285080","sourceNumber":"285080","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente de 44 anos, eumenorreica, assintomática, realizou mamografia e ultrassom de\nmamas que identificaram cistos simples\nbilaterais menores que 5 mm e calcificações redondas\nisoladas bilaterais. Exame físico normal. Realizou mamoplastia redutora (cirurgia estética), cujo\nresultado patológico identificou, em mama direita, neoplasia lobular in situ grau 3, com a margem\ncirúrgica lateral coincidente. Dentre as alternativas, abaixo a melhor conduta é:","options":{"A":"Quadrantectomia à direita e radioterapia adjuvante.","B":"Mastectomia direita com biópsia do linfonodo sentinela.","C":"Biópsia do linfonodo sentinela e radioterapia adjuvante.","D":"Tamoxifeno 20mg/dia por 5 anos.","E":"Controle clínico e ultrassonográfico annual."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-285082","number":"285082","sourceNumber":"285082","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"São considerados fatores de risco para câncer de mama, exceto:","options":{"A":"Ser mulher.","B":"Ingestão regular de bebida alcoólica.","C":"Tabagismo.","D":"Menarca precoce e menopausa tardia.","E":"Obesidade central."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-285083","number":"285083","sourceNumber":"285083","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Em uma mulher de 60 anos, o exame mais indicado para rastreamento do câncer de\nmama é:","options":{"A":"Palpação das mamas.","B":"Ultrassonografia mamária.","C":"Mamografia convencional.","D":"Mamografia digital.","E":"Ressonância magnética das mamas."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-285084","number":"285084","sourceNumber":"285084","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Com relação à cicatriz radial, assinale a opção correta:","options":{"A":"Surge normalmente após 6 meses da data da cirurgia prévia.","B":"A biópsia cirúrgica é necessária para o diagnóstico diferencial histopatológico.","C":"O seu diagnóstico é feito em associação com a ultrassonografia.","D":"O aspecto radiológico é de imagem estrelada, com centro denso, espículas lineares e regulares\nde espessura variável.","E":"É uma alteração precursora do câncer de mama."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-274779","number":"274779","sourceNumber":"274779","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"De acordo com a classificação de IOTA (International Ovarian Tumor Analysis) uma\nmassa anexial tem risco de malignidade\naumentada, quando apresenta:","options":{"A":"conteúdo aneicóide.","B":"sombra acústica posterior.","C":"septo único.","D":"projeções papilares."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-274481","number":"274481","sourceNumber":"274481","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Referente a noções básicas de mastologia escolha a INCORRETA:","options":{"A":"A mamografia com o intuito de rastreamento do câncer de mama deve ser realizada segundo o\nMinistério da Saúde do Brasil em mulheres a partir dos 40 anos e até os 69 anos, a cada dois anos.","B":"Pacientes com implantes de silicone devem realizar a mamografia para rastreamento do câncer\nde mama independente do resultado da\nultrassonografia mamária, que não a substitui com este\nintuito.","C":"Durante a linfadenectomia axilar para tratamento do câncer de mama deve-se primar pela\npreservação vascular e nervosa, em especial o\nnervo torácico longo ou nervo de Bell pelo risco de\nlesão chamada de \"\"escápula alada\"\".","D":"No estadiamento do câncer de mama o achado de linfonodos supraclaviculares homolaterais à\ndoença mamária deve ser classificado como N3 e\nnão M1."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-282001","number":"282001","sourceNumber":"282001","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"MCBF. 42 anos, em uso de contraceptivo combinado oral, procura atendimento médico\npor apresentar fluxo papilar espontâneo,\naquoso, uniductal apenas em mama esquerda.\n\nConsiderando que o exame clínico, ultrassonográfico e mamográfico estão todos normais, qual a\nconduta correta?","options":{"A":"Exérese do ducto comprometido.","B":"Se citologia normal, controle mamográfico semestral.","C":"Pesquisa de adenoma hipofisário.","D":"Punção aspirativa com agulha fina."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-282003","number":"282003","sourceNumber":"282003","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente JKM, 25 anos, procura o ginecologista com resultado de ultrassonografia\ndemonstrando cisto com 9 cm de diâmetro,\napresentando áreas sólidas, septos espessados e fluxo\nsanguíneo intratumoral. Foi solicitado o antígeno carboidrato 125 (CA-125). Qual valor desse\nantígeno é considerado diagnóstico para o carcinoma ovariano?","options":{"A":">200 U/mL","B":">50 U/mL","C":">100 U/mL","D":">150 U/m/L"},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-277438","number":"277438","sourceNumber":"277438","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Os nódulos mamários benignos são responsáveis por até 80% das massas palpáveis.\nSeu diagnóstico diferencial é amplo, feito por meio\nde ultrassonografia e punção aspirativa por\nagulha fina. As neoplasias mais comuns são:","options":{"A":"cistos mamários","B":"fibroadenomas","C":"papilomas","D":"hamartomas"},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-281294","number":"281294","sourceNumber":"281294","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente feminina, 50 anos, com queixa de dor pélvica de início há 6 meses,\nprogressiva, insidiosa, associada a aumento de\nvo abdominal, mais notado nas últimas 3 semanas.\nNega sintomas urinários. Menarca aos 13 anos, com climat anos. Fez uso de anticoncepcional oral\ndos 20 aos 42 anos. Sem filhos. Nega tabagismo. Realizou ecografia de pelve que eviden lesão\nexpansiva cística, de conteúdo heterogêneo, apresentando numerosas formações ovaladas interior,\nhiperecoicas na US e móveis à mudança de decúbito da paciente. ovaladas que apresentavam\nsinal intermediário em T1 e T2, sem evidência de perda do sinal nas sequên gordura ou de queda\ndo sinal na sequência T1 gradiente A principal hipótese diagnóstica é:","options":{"A":"Cisto dermoide.","B":"Endometrioma.","C":"Adenocarcinoma.","D":"Lipoma."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":["question_bank/media/medcurso/medcurso-gineco-gin-4/281294.png"],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-282006","number":"282006","sourceNumber":"282006","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"O tipo de tumor de ovário mais frequente é:","options":{"A":"Mucinoso.","B":"Seroso.","C":"Células claras.","D":"Endometrioide."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-281296","number":"281296","sourceNumber":"281296","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma paciente de 23 anos procura ginecologista apresentando um nódulo mamário de 2\ncm, consistência fibroelástica, com boa mobilidade, indolor. O provável diagnóstico, nesse caso, é:","options":{"A":"Tumor filodes.","B":"Ectasia ductal.","C":"Hamartoma.","D":"Fibroadenoma."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-274792","number":"274792","sourceNumber":"274792","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Com o objetivo de padronizar a interpretação e a descrição de laudos de mamografia e\nultrassonografia foi desenvolvida a classificação BI-RADS. Sobre a mamografia é correto afirmar\nque:","options":{"A":"a classificação de BIRAD 0 representa achados negativos, não sendo necessários a\ncomplementação de outros métodos.","B":"a classificação de BIRADS 2 representa achados provavelmente benignos e deve-se ter o\nseguimento em 6 meses.","C":"a categoria 5 representa malignidade conhecida, ou seja, o diagnóstico já foi feito por um\nbiopsia\nprévia.","D":"a categoria 3 representa achados provavelmente benignos apresentam risco de malignidade\nmenor que 2%."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-258215","number":"258215","sourceNumber":"258215","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma das classificações histológicas mais utilizadas nas neoplasias ovarianas é a que\nse baseia na origem embrionária das células.\nOs tumores podem ser classificados em epiteliais,\ntumores do estroma, cordões sexuais e células germinativas. Em relação às neoplasias ovarianas,\nsabe-se que:","options":{"A":"dentre os tumores ovarianos de células germinativas podem ser citados o seroso e o mucinoso.","B":"o disgerminoma e o teratoma são tumores derivados do epitélio celômico epitelial.","C":"o tumor endometrioide e o tumor de células claras são derivados de células germinativas e\nestroma gonadal, respectivamente.","D":"o tecoma e tumores de células da granulosa são derivados do estroma gonadal (cordão sexual)."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-258216","number":"258216","sourceNumber":"258216","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"O câncer de mama do ciclo grávido-puerperal é assim definido quando a neoplasia é\ndiagnosticada durante a gravidez, no primeiro ano pós-parto, pós-aborto ou em qualquer tempo\ndurante a lactação. O tipo histopatológico mais comum é o carcinoma ductal invasivo (85% dos\ncasos) seguido pelo lobular (10% dos casos). A maioria dos carcinomas é de grande volume, alto\ngrau de malignidade, frequentemente com receptores hormonais negativos e cerca de 30% dos\ncasos são HER-2 positivos. No momento do diagnóstico, os linfonodos axilares geralmente já estão\ncomprometidos. Sobre as particularidades do diagnóstico e do tratamento do câncer de mama,\nsabe-se que:","options":{"A":"o retardo do diagnóstico não é comum em mulheres gestantes com câncer de mama e não\nimpacta negativamente na sobrevida.","B":"a mamografia não pode ser realizada de forma segura na gestação, sendo proscrita o seu\nemprego durante a gravidez.","C":"a punção aspirativa por agulha fina (PAAF) apresenta sensibilidade reduzida em vista das\nalterações morfológicas fisiológicas decorrentes da gravidez ou lactação, sendo que a biópsia\npercutânea com agulha grossa (core biopsy) é o método de escolha para o diagnóstico\nhistopatológico.","D":"a pesquisa do linfonodo sentinela com marcador radioativo tecnécio 99 não é segura durante a\ngestação, enquanto o uso do corante azul patente V é recomendado na mulher grávida."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-258217","number":"258217","sourceNumber":"258217","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Sobre a mastalgia, sabe-se que:","options":{"A":"Na mastalgia acíclica, a dor é difusa e bilateral, variando ao longo do ciclo menstrual,\nintensificando na última semana do ciclo e melhorando após a menstruação.","B":"Na mastalgia cíclica, a dor é frequentemente localizada e unilateral, em geral causada por\ncistos,\nmastites, traumas e tromboflebite superficial.","C":"O tratamento inicial na mastalgia acíclica é preferencialmente feito com tamoxifeno por um\nperíodo de três a cinco dias.","D":"No tratamento da mastalgia, são importantes as medidas comportamentais como atividade\nfísica, dieta pobre em lipídios, diminuição do\npeso, controle da ansiedade, abolição do tabagismo e\noutros hábitos são importantes no tratamento da mastalgia."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-257775","number":"257775","sourceNumber":"257775","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Em relação ao rastreamento de câncer de mama na rede pública, o Ministério da Saúde\nrecomenda a realização da mamografia em mulheres com idade","options":{"A":"entre 40 e 65 anos, anualmente.","B":"entre 50 e 65 anos, anualmente.","C":"entre 50 e 69 anos, a cada dois anos.","D":"acima de 50 anos, a cada dois anos."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-257778","number":"257778","sourceNumber":"257778","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma mulher de 65 anos tem apresentado aumento de volume abdominal há seis\nmeses. No exame físico, há distensão\nabdominal com ondas de líquidos. A ultrassonografia revela\na presença de massa ovariana cística de 10 cm à direita. A massa foi removida cirurgicamente. Ao\nexame macroscópico, a massa removida é cisto unilocular repleto de líquido claro, e as projeções\npapilares se estendem à luz central do cisto. O exame microscópico mostra que as papilas são\ncobertas por células cuboides atípicas que invadem o estroma subjacente. Nessa caso, qual é o\ndiagnóstico mais provável?","options":{"A":"Cistadenoma seroso.","B":"Cistadenocarcinoma seroso.","C":"Disgerminoma.","D":"Tumor mulleriano misto maligno."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-247443","number":"247443","sourceNumber":"247443","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Dentre as patologias mamárias benignas descritas abaixo, qual apresenta fator de risco\npara câncer de mama?","options":{"A":"Adenose esclerosante.","B":"Fibradenoma simples.","C":"Cisto mamário.","D":"Ectasia ductal."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-249524","number":"249524","sourceNumber":"249524","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Mulher de 55 anos, sem antecedentes patológicos, nuligesta, com laudo de mamografia\nBI-RADS 2. A conduta nesse caso é:","options":{"A":"complementar com ultrassom.","B":"biópsia dirigida por ultrassom caso o nódulo não seja palpável.","C":"complementar com ressonância magnética.","D":"mamografia de rotina anual."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-249530","number":"249530","sourceNumber":"249530","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente procura mastologista com queixa de descarga papilar. No exame das mamas\nfica evidente que se trata de fluxo benigno\nporque o mesmo é:","options":{"A":"multiductal, bilateral.","B":"uniductal bilateral.","C":"uniductal, unilateral.","D":"multiductal, unilateral."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-229568","number":"229568","sourceNumber":"229568","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"NÃO faz parte dos achados compatíveis com classificação BI-RADS 3 à mamografia:","options":{"A":"nódulo sólido circunscrito, sem calcificações.","B":"assimetria focal.","C":"agrupamento de calcificações redondas ou puntiformes.","D":"linfonodo em prolongamento axilar."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-254293","number":"254293","sourceNumber":"254293","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Mariana tem 52 anos e tem o costume de procurar a Unidade Básica de Saúde para\navaliar sua saúde de forma geral. Neste\nano, foi orientado por seu médico de família e comunidade\nsobre a possibilidade de realizar mamografia para rastreamento de câncer de mama, devido a\ncritério de idade, visto que Mariana não possui histórico familiar ou sintomas relacionados à mama.\nApós realizar o exame, a paciente leva seu resultado, que mostra nódulo em mama esquerda, com\nlaudo de BIRADS 3. A atitude recomendada neste caso é de:","options":{"A":"Encaminhar ao mastologista para realização de PAAF.","B":"Solicitar ultrassonografia de mama para elucidação do quadro.","C":"Repetir mamografia anualmente e, depois, a cada 3 anos em caso de persistência do resultado.","D":"Repetir mamografia de 6 em 6 meses no primeiro ano e anualmente nos dois anos seguintes."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-gineco-gin-4-218243","number":"218243","sourceNumber":"218243","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"A relação entre a história familiar positiva para câncer de mama (parentes próximos\ncom a doença) e o risco da mulher\ndesenvolver a doença ao longo de sua vida já é conhecida de\nlonga data. Hoje em dia, esta relação hereditária de risco pode ser confirmada com avaliação da\npresença de mutações patogênicas nos genes BRCA1 e/ou BRCA2. Em mulheres com diagnóstico\nde carcinoma infiltrante de mama, qual a porcentagem de casos com história familiar positiva para\ncâncer de mama e de casos com mutações nos genes BRCA1 e/ou BRCA2 confirmadas?","options":{"A":"Identifica-se história familiar positiva entre 20% e 30% dos casos e mutações dos genes BRCA1\ne/ou BRCA2 entre 5% e 10% dos casos.","B":"Identifica-se história familiar positiva entre 40% e 50% dos casos e mutações dos genes BRCA1\ne/ou BRCA2 entre 20% e 30% dos casos.","C":"Identifica-se história familiar positiva entre 60% e 70% dos casos e mutações dos genes BRCA1\ne/ou BRCA2 entre 40% e 50% dos casos.","D":"Identifica-se história familiar positiva entre 80% e 90% dos casos e mutações dos genes BRCA1\ne/ou BRCA2 entre 60% e 70% dos casos."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-216482","number":"216482","sourceNumber":"216482","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"A orientação a ser dada para a repetição do exame de mamografia nos casos abaixo,\né: A., 55 anos, exame clínico de mama\nnormal, sem queixas e mamografia BI-RADS 1; B., 67 anos,\nqueixa de mastalgia, com presença de nódulo mamário no autoexame clínico de mama normal,\nmamografia BI-RADS 2.","options":{"A":"1 ano para ambos os casos.","B":"1 ano para o caso A e 6 meses para o caso B.","C":"2 anos para ambos os casos.","D":"3 anos para o caso A e 1 ano para o caso B."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-216496","number":"216496","sourceNumber":"216496","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"A USG mamária é indicada para:","options":{"A":"Detectar nódulos em mamas muito adiposas.","B":"Rastrear câncer de mama.","C":"Detectar microcalcificações.","D":"Avaliar achado duvidoso na mamografia."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-216446","number":"216446","sourceNumber":"216446","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Embora não sejam fundamentais para diagnóstico dos tumores ovarianos, os\nmarcadores tumorais são de grande valia no\nseguimento desses tumores. Em relação ao tipo\nhistopatológico e aos marcadores tumorais, tem-se que:","options":{"A":"O CA-125 é marcador de tumores epiteliais.","B":"CEA é marcador do disgerminomas.","C":"A alfafetoproteína é marcadora dos tumores do seio endodérmico.","D":"Os esteroides sexuais são marcadores dos tumores embrionários."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-215389","number":"215389","sourceNumber":"215389","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Assinale a alternativa INCORRETA com relação à rotura de cistos ovarianos.","options":{"A":"Os cistos ovarianos foliculares ou de corpo lúteo podem apresentar sangramento para o interior\ndo parênquima ovariano com ou sem sangramento\nintraperitoneal.","B":"O principal diagnóstico diferencial é o leiomioma uterino com rotura de vasos na superfície.","C":"Além dos cistos funcionais, endometriomas, neoplasias benignas e malignas, também podem\napresentar rotura espontânea com extravasamento de seu conteúdo para a cavidade peritoneal e\ndor.","D":"O exame físico pode demonstrar sinais de irritação peritoneal, e o toque vaginal, a presença de\nabaulamento de fundo-de-saco vaginal e tumor anexial."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-216525","number":"216525","sourceNumber":"216525","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Em relação ao câncer de mama, é correto afirmar:","options":{"A":"O uso de contraceptivos não favorece a estimulação tumoral.","B":"O número de ciclos menstruais ovulatórios ocorridos durante a vida da mulher está relacionado à\nmenor incidência de câncer de mama.","C":"A ooforectomia, antes dos 45 anos, exerce efeito protetor, com redução do risco de\naparecimento dessa doença.","D":"A multiparidade parece ser um fator de risco importante."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-214928","number":"214928","sourceNumber":"214928","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"As imagens nodulares das mamas podem ter, à ultrassonografia, características de\ncistos, nódulos benignos ou malignos. São critérios ultrassonográficos que sugerem nódulo sólido\nbenigno, exceto:","options":{"A":"imagem hipoecoica com orientação do maior eixo vertical","B":"imagem hipoecoica com bordos estreitos","C":"imagem hipoecoica com maior eixo transversal","D":"imagem hipoecoica com ecos homogênicos"},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-210574","number":"210574","sourceNumber":"210574","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Considere o caso: A.V.C, 17 anos, nuligesta, DUM há 2 semanas, em uso de condom,\nvai ao consultório com relato de nódulo na\nmama direita percebido pelo autoexame há 2 meses.\n\nPaciente nega crescimento do mesmo. Apresenta história familiar de câncer de mama (avó aos 67\nanos) e câncer de estômago (pai). Ao exame físico apresenta área nodular móvel, regular,\naproximadamente 2cm em quadrante super-lateral de mama direita, descarga papilar negativa e\naxilas livres. Diante dessas informações, qual é a melhor conduta?","options":{"A":"Solicitar mamografia.","B":"Solicitar ultrassonografia de mama e axila direita.","C":"Realizar core-biopsy guiada por ultrassonografia.","D":"Realizar punção aspirativa por agulha fina.","E":"Encaminhar para tumorectomia."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-214201","number":"214201","sourceNumber":"214201","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Quando abordamos o tema linfadenectomia axilar é importante ressaltar os niveis de\nBerg, cuja estrutura de referência para estratificação é o músculo:","options":{"A":"Peitoral menor.","B":"Peitoral maior.","C":"Serrátil.","D":"Grande dorsal."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-217028","number":"217028","sourceNumber":"217028","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Assinale, a seguir, a alternativa que não apresenta uma característica ultrassonográfica\nde tumor ovariano que sugere malignidade.","options":{"A":"Vascularização intensa.","B":"Diâmetro maior que 10 cm.","C":"Unilateralidade.","D":"Presença de septações espessas.","E":"Tumor sólido irregular."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-201716","number":"201716","sourceNumber":"201716","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"São fatores predisponentes para o câncer de mama:","options":{"A":"Menarca tardia e histórico de câncer de mama em mãe, irmã ou filha.","B":"Idade maior ou igual a 40 anos e obesidade.","C":"Etilismo e menopausa precoce.","D":"Menarca tardia e sedentarismo."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-202686","number":"202686","sourceNumber":"202686","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Leia o caso clínico a seguir. Menina de 12 anos, sem menarca, com telarca em estágio\nM4 de Tanner, chega ao pronto-socorro com\nquadro de dor aguda, em cólica, intensa, em\nhipogástrico, associada a náuseas, vômitos e posição antálgica. Ao exame físico, palpa-se\ntumoração de cerca de 10 cm, intensamente dolorosa em FIE. A ultrassonografia mostra útero\npúbere, com eco endometrial = 5 mm, ovário direito = 6,0 cm³, ovário esquerdo não visualizado e\nregião parauterina esquerda ocupada por tumoração cística com maior diâmetro de 12 cm. Diante\ndo quadro, a hipótese diagnóstica e o tratamento são, respectivamente:","options":{"A":"malformação mulleriana com obstrução do fluxo sanguíneo - laparotomia.","B":"megaureter - tratamento clínico.","C":"cisto de ovário torcido - laparotomia.","D":"megacólon - tratamento clínico."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-210618","number":"210618","sourceNumber":"210618","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Assinale a alternativa que contém as síndromes ou genes já estabelecidos que\nconferem alto risco para câncer de mama.","options":{"A":"Síndrome de câncer gástrico difuso hereditário e síndrome de Cowden.","B":"Síndrome de câncer de mama e ovário hereditário e síndrome de Lynch.","C":"BRCA 1 e ATM.","D":"ATM e STK11.","E":"BRCA 2 e MSH2."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-205660","number":"205660","sourceNumber":"205660","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Em relação à síndrome do câncer de mama/ovário hereditária, assinale a alternativa\nINCORRETA.","options":{"A":"Aproximadamente 80% das mulheres com essa síndrome apresentam mutação nos genes\nBRCA 1 ou BRCA 2.","B":"As opções de tratamento para portadoras dessa síndrome sao as mesmas das mulheres que\nnão tem a mutação.","C":"Muitas mulheres com a síndrome optam por mastectomia bilateral profilática, o que é respaldado\npelas sociedades de mastologia.","D":"Não há relação do câncer de mama em homens com a mutação no BRCA1/BRCA2."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-187740","number":"187740","sourceNumber":"187740","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"BIRADS® (BreastImaging Reporting and Data System) foi desenvolvido pelo ACR\n(American College of Radiology) e adotado em\ndiversos países, inclusive no Brasil. As lesões\nidentificadas pela mamografia que são classificadas, de acordo com o BIRADS®, como categoria 3\nsão consideradas:","options":{"A":"Achados funcionais e devem ser conduzidos com exames de rotina anuais.","B":"Lesões provavelmente benignas, que devem ser seguidas inicialmente com controle da imagem\nem intervalos menores que um ano.","C":"Lesões provavelmente benignas, porém deve-se indicar o estudo histopatológico para\nconfirmação diagnóstica.","D":"Lesões suspeitas que devem ser retiradas cirurgicamente."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-175412","number":"175412","sourceNumber":"175412","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma mulher de 22 anos, usuária de contraceptivo hormonal oral há 3 anos, suspende o\nuso e, 15 dias após a 1ª mestruação sem\nuso da pílula, apresenta dor súbita na fossa ilíaca direita,\nde média intensidade. A hipótese diagnóstica mais provável é:","options":{"A":"torção do cisto ovariano","B":"apendicite aguda","C":"moléstia inflamatória pélvica aguda","D":"rotura de cisto folicular","E":"endometriose de ovário"},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-185199","number":"185199","sourceNumber":"185199","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"O abdômen agudo, na ginecologia, tem importância devido à sua alta morbidade e\nsequelas na vida da paciente. Sobre as urgências de causas ginecológica, pode-se afirmar que:","options":{"A":"na rotura de cisto lúteo ou cisto folicular, é necessário frequentemente a abordagem cirúrgica.","B":"a gravidez ectópica é um diagnóstico que tem que ser descartado em pacientes em idade fértil,\napesar de sua prevalência estar diminuindo.","C":"as urgências vascullares assumem um papel importante e pode ser devido a torções anexias ou\nde miomas, pediculados.","D":"a síndrome de Fritz-Huhg-Curtis ocorre devido ao rompimento de endometrioma e\nextravasamento de seu conteúdo na cavidade abdominal."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-186448","number":"186448","sourceNumber":"186448","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Considerando os tumores malignos do ovário, assinale a assertiva incorreta:","options":{"A":"O câncer de ovário tem sido associado à baixa paridade e infertilidade.","B":"O uso por longo período de contraceptivos orais está associado ao aumento do risco relativo\npara câncer de ovário.","C":"Tumores metastáticos do ovário são frequentemente do tubo digestivo e mama.","D":"A grande maioria dos cânceres epiteliais de ovário é esporádica; os cânceres familiares\nrespondem por apenas 5 a 10% dos casos."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-186453","number":"186453","sourceNumber":"186453","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente de 37 anos apresenta ultrassonagrafia transvaginal demonstrando massa\nanexial cística de pequeno volume e sem neovascularização ao estudo doppler. Esse quadro\nsugere:","options":{"A":"Cisto folicular ovariano.","B":"Prenhez ectópica.","C":"Tumor maligno do ovário.","D":"Abcesso tubovariano."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-186467","number":"186467","sourceNumber":"186467","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Assinale a alternativa que NÃO constitui sinal ecográfico sugestivo de malignidade dos\ntumores ovarianos:","options":{"A":"Achado de áreas sólidas dentro de massas císticas.","B":"Encontro de septações delgadas.","C":"Presença de massa acometendo ambos os ovários.","D":"Presença de multiloculações."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-182469","number":"182469","sourceNumber":"182469","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"A artéria ovariana, que irriga os ovários, as tubas uterinas e o ligamento largo, é ramo\nde que artéria?","options":{"A":"renal","B":"aorta","C":"ilíaca interna","D":"ilíaca comum"},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-187536","number":"187536","sourceNumber":"187536","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"No Brasil, exceto os tumores malignos de pele, os tumores malignos mais incidentes\nnas mulheres são mama e","options":{"A":"colo uterino e endométrio;","B":"colón/reto e colo uterino;","C":"colo uterino e ovário;","D":"estômago e colo uterino."},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-187539","number":"187539","sourceNumber":"187539","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Sobre o Câncer de mama em homens é incorreto afirmar que:","options":{"A":"representa um por cento de todos os casos de câncer de mama.","B":"pode estar presente em pessoas com história familiar de câncer de mama.","C":"não existe.","D":"pode ocorrer em homens com ginecomastia."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-182483","number":"182483","sourceNumber":"182483","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Ao ser examinada, uma paciente apresenta rash eczematoso focal do mamilo direito. A\nprincipal hipótese diagnóstica é:","options":{"A":"carcinoma lobular in situ","B":"doença de Paget","C":"fibroadenoma","D":"tumor filoide"},"answer":"B","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-178825","number":"178825","sourceNumber":"178825","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente, 44 anos, chega ao consultório ginecológico com queixa de nódulo na mama.\nTrouxe laudo de MMG de rotina realizada há 6\nmeses que revelou, em quadrante superolateral de\nmama direita, uma imagem arredondada e circunscrita medindo 2 cm. O exame de ultrassonografia\ncomplementar revelou cisto simples de 2,2 cm. A paciente repetiu recentemente a ultrassonografia\ne o cisto aumentou de tamanho, medindo então 3,0 cm. Qual a categoria BI-RADS?","options":{"A":"2","B":"3","C":"0","D":"4A","E":"4B"},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-182485","number":"182485","sourceNumber":"182485","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Uma paciente de 45 anos relata descarga mamilar. Em face disso, deve-se prosseguir a\ninvestigação quando essa descarga for:","options":{"A":"uniductal e sanguinolenta","B":"unilateral e leitosa","C":"bilateral e amarelada","D":"espontânea e esverdeada"},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-178832","number":"178832","sourceNumber":"178832","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente, 44 anos, chega ao consultório ginecológico com queixa de nódulo na mama.\nTrouxe laudo de MMG de rotina realizada há 6\nmeses, que revelou, em quadrante superolateral de\nmama direita, uma imagem arredondada e circunscrita medindo 2 cm. O exame de ultrassonografia\ncomplementar revelou cisto simples de 2,2 cm. A paciente repetiu recentemente a ultrassonografia\ne o cisto aumentou de tamanho, medindo então 3,0 cm. Qual deve ser a conduta em relação ao\ndiagnóstico?","options":{"A":"Solicitar uma ressonância magnética.","B":"Solicitar novo ultrassom em 1 mês.","C":"Exérese do cisto.","D":"Não fazer nada, apenas orientar a paciente.","E":"Indicar a PAAF mesmo se assintomática, pois o cisto apresentou aumento de tamanho."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-187530","number":"187530","sourceNumber":"187530","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente, 55 anos, obesa, ex tabagista, após consulta ginecológica, foi solicitado\nmamografia, cujo laudo assinalou a presença de imagem nodular de limites irregulares e\nespiculados em mama direita. Neste caso a categoria de classificação de BI-RADS é","options":{"A":"2.","B":"3.","C":"4.","D":"5."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-174128","number":"174128","sourceNumber":"174128","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Os tumores ovarianos mais comuns na infância e adolescência são os","options":{"A":"tumores das células das granulosas.","B":"tumores epiteliais.","C":"gonadoblastomas.","D":"teratomas císticos maduros."},"answer":"D","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-174492","number":"174492","sourceNumber":"174492","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente de 17 anos, assintomática, nuligesta, procura ambulatório de ginecologia para\navaliação de rotina. Realizado um ultrassom endovaginal, é evidenciado cisto anecóico de 4 cm de\ndiâmetro. A conduta neste caso é:","options":{"A":"Realizar videolaparoscopia.","B":"Realizar punção do cisto guiada por ultrassonografia.","C":"Conduta expectante com repetição do ultrassom.","D":"Dosar CA 125."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-174118","number":"174118","sourceNumber":"174118","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Os cistos ovarianos funcionais incluem cistos foliculares, cistos do corpo lúteo e cistos\ntecaluteínicos. Em relação a estes cistos,","options":{"A":"os tecaluteínicos são os mais frequentes em mulheres no menacme.","B":"os de corpo lúteo estão associados à ruptura e ao hemoperitônio.","C":"os foliculares frequentemente levam a quadros de abdome agudo.","D":"os de corpo lúteo são mais frequentes em usuárias de anticoncepcional hormonal."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-174089","number":"174089","sourceNumber":"174089","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Mulher de 55 anos, menopausada aos 50, sem nunca ter usado TH, em\nultrassonografia de rotina, apresenta\ntumoração ovariana esquerda anecoica, com 10 cm de maior\ndiâmetro, contornos regulares, limites precisos, com septos grosseiros em seu interior e sem debris;\nsem líquido em fundo de saco e ovário direito atrófico. A principal causa e o tratamento adequado\nsão, respectivamente:","options":{"A":"cisto funcional - realização de nova ultrassonografia após três meses.","B":"cistoadenocarcinoma mucinoso - realização de laparotomia.","C":"cistoadenoma seroso - realização de laparotomia.","D":"cistoadenocarcinoma - realização de cirurgia de Wertheim-Meigs."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-178853","number":"178853","sourceNumber":"178853","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Paciente, 31 anos, de risco habitual, refere dor de leve intensidade em mamas que se\ninicia cerca de 5 dias antes da menstruação e cessa após menstruar. Está preocupada, pois sua\namiga de 30 anos foi diagnosticada com câncer de mama. Exame físico mamário sem\nanormalidades. Qual a melhor conduta?","options":{"A":"Mamografia.","B":"Ultrassonografia.","C":"Ressonância magnética.","D":"PAAF.","E":"Orientação."},"answer":"E","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-173536","number":"173536","sourceNumber":"173536","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Que grupo de neoplasias ovarianas é mais frequente?","options":{"A":"Epitélio de superfície.","B":"Células germinativas.","C":"Cordões sexuais.","D":"Estroma ovariano."},"answer":"A","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-187556","number":"187556","sourceNumber":"187556","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"A irrigação principal da mama e drenagem linfática são:","options":{"A":"1/3 pela artéria torácica interna e 2/3 pela artéria torácica externa com drenagem linfática com\nfluxo unidirecional de linfa do plexo superficial para profundo.","B":"2/3 pela artéria torácica interna e 1/3 pela artéria torácica externa com drenagem linfática com\nfluxo bidirecional de linfa do plexo superficial para profundo.","C":"2/3 pela artéria torácica interna e 1/3 pela artéria torácica externa com drenagem linfática com\nfluxo unidirecional de linfa do plexo superficial para profundo.","D":"1/3 pela artéria torácica interna de 2/3 pela artéria torácica externa com drenagem, linfática\ncom\nfluxo bidirecional de linfa do plexo superficial para profundo."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-183302","number":"183302","sourceNumber":"183302","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Em relação à Galactorréia, assinale a alternativa CORRETA:","options":{"A":"Está presente em quase todos os casos de hiperprolactinemia.","B":"Sempre acontece amenorréia associada.","C":"Pode ser causada por medicamentos como, por exemplo, Metildopa.","D":"Causada pelo aumento da macroprolactina."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-gineco-gin-4-156397","number":"156397","sourceNumber":"156397","collectionBlock":"medcurso:medcurso-gineco-gin-4","collectionLabel":"Medcurso · GIN 4","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"GIN 4","subtopic":"","stem":"Qual o método de avaliação das mamas a ser utilizado visando ao diagnóstico precoce\nno rastreamento das lesões pré-malignas, em\nmulheres com mais de 40 anos de idade?","options":{"A":"Autoexame.","B":"Ultrassonografia.","C":"Mamografia.","D":"Teste para identificação de linfonodo sentinela."},"answer":"C","source":"Gineco/GIN 4/GIN 4.txt","sourceLabel":"Medcurso · GIN 4","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","GIN 4","Medcurso"],"answerSource":"explicit","commentDeferred":true}]};
